--s_wip				="\n\n<c=o>（開發中）</c>"
--wpn_prof_d		="你知道在戰鬥中如何使用這類武器。"--\n\n此類武器攻擊+4。	+4 bonus on attack rolls with weapons of the group.	+4 bonus aux jets d'attaque avec les armes du groupe.	このグループの武器を使用した攻撃ロールに＋４のボーナス。	你知道在戰鬥中如何使用這類武器。You understand how to use weapons of this group in combat.Vous savez comment utiliser les armes de ce type en combat.このグループの武器を戦闘で使用する方法を理解している。戦闘でこのグループの武器の使い方を理解している。\n\nこのグループの武器を使った攻撃時に+4のボーナスを得る。
--simple_wpn_d		="\n\n顧名思義，此類武器簡單易用，大多數職業都擅長所有簡易武器。"..s_auto_prof
--s_exotic_wp_d		="你知道在戰鬥中如何使用這種異種武器。\n\n相對於簡易和軍用武器，異種武器較為罕見且難以使用，需要接受專門的訓練才能運用自如。"--\n\n此種武器攻擊+4。	+4 bonus on attack rolls with the weapon.	+4 bonus aux jets d'attaque avec l'arme.	武器の攻撃ロールに+4ボーナス。
s_for_touch			="本專長也適用於接觸攻擊。"
s_for_touch_m		="本專長也適用於近戰接觸攻擊。"
s_for_touch_r		="本專長也適用於遠端接觸攻擊。"
melee_only			="本專長僅適用於近戰。"
ch_1_eff			="\n\n每次重擊只能引發1個重擊效果，除非擁有重擊掌握專長。"
use_a				="\n\n<c=fc_b>每天使用次數：5 + 角色等級/4。\n最多15次/天。</c>"
use_b				="\n\n<c=fc_b>每天使用次數：角色等級/4。\n最多5次/天。</c>"
s_feat_x_spl_add_2x	="可多次獲得此專長。"
s_feat_x_spl_cvt_1x	="可多次獲得此專長，每次須選擇不同的法術。"
s_feat_x_spl_cpy_1x	="可多次獲得此專長，每次須選擇不同的法術或類法術能力。"
s_feat_x_mle_undr	="可多次獲得此專長，每次須選擇不同的特殊材料。你的近戰武器在穿透傷害減免時視為用所有這些材料製成。"
s_feat_x			="可多次獲得此專長，效果疊加。"
s_feat_x_max		="最多可獲得%d次。"
s_feat_x_23			="兩個兩倍等於三倍，以此類推。"
s_feat_no_stk		="此專長不能和類似能力疊加。"
s_feat_no_stk_itm	="此專長不能和魔法物品或非永久魔法效果給予的類似效果疊加。"
s_shp_lmt			="體型限制和你的動物變身體型限制相同。"
s_x_nwpns			="%d個或更多天生武器"
s_has_perm_sr		="有來自專長、職業特性或其他永久效果的法抗"
s_has_som_9			="能施展該學派至少一個九環法術"
s_has_cst_max_spl	="能施展至少一個施法者職業能施展的最高階法術"
s_has_acst_max_spl	="能施展一個奧術施法者職業能施展的最高階法術"
s_epic_feats		="傳奇專長"	s_epic_feats_d=[[向百米開外的對手發射箭矢，空手赤拳便能斬敵首級，亦或用美妙歌聲來迷惑巫妖——這就是傳奇專長的力量。

和普通專長一樣，傳奇專長也是一種特殊能力，它要麼賦予你的角色一種新的能力，要麼增強一項已有的能力。然而，傳奇專長將能力的領域從平凡昇華至神話。

傳奇專長只適用於角色等級為21級或以上的傳奇角色。傳奇角色在很大程度上是由其所選擇的傳奇專長來定義的。]]


s_turn1				="精通驅散"		s_turn1_d				="驅散檢定+1加值。"
s_turn2				="高等驅散"		s_turn2_d				="精通驅散的加值再+1。"
s_turn_extra		="額外驅散"		s_turn_extra_d			="驅散的每天使用次數+4。"

s_abi_1_1x			="提升力量"		s_abi_1_1x_d			="你的肌肉和體能超出常人。\n\n力量增加1點。"
s_abi_2_1x			="提升敏捷"		s_abi_2_1x_d			="你的靈敏和協調超出常人。\n\n敏捷增加1點。"
s_abi_3_1x			="提升體質"		s_abi_3_1x_d			="你的健康和堅韌超出常人。\n\n體質增加1點。"
s_abi_4_1x			="提升智力"		s_abi_4_1x_d			="你的理解和學習能力超出常人。\n\n智力增加1點。"
s_abi_5_1x			="提升感知"		s_abi_5_1x_d			="你的意志力和洞察力超出常人。\n\n感知增加1點。"
s_abi_6_1x			="提升魅力"		s_abi_6_1x_d			="你的說服力和領導力超出常人。\n\n魅力增加1點。"
s_abi_7_1x			="提升體能屬性"	s_abi_7_1x_d			="體能屬性增加1點。"
s_abi_8_1x			="提升心靈屬性"	s_abi_8_1x_d			="心靈屬性增加1點。"
s_abi_9_1x			="提升所有屬性"	s_abi_9_1x_d			="所有屬性增加1點。"
s_hp_20x			="傳奇健壯"		s_hp_20x_d				="你異常得強壯。\n\n生命值+20點。"
s_ft_4				="傳奇強韌"		s_ft_4_d				="你異常得堅韌。\n\n所有強韌檢定+4加值。"
s_rf_4				="傳奇反射"		s_rf_4_d				="你擁有超常得快速反應。\n\n所有反射檢定+4加值。"
s_wl_4				="傳奇意志"		s_wl_4_d				="你擁有超常得堅強意志。\n\n所有意志檢定+4加值。"
s_spd_6				="傳奇神速"		s_spd_6_d				="你比正常人移動更迅速。\n\n速度提升30尺。\n\n特殊：穿著重甲時，此專長無效。"-- 先決條件：敏捷21，飛跑。
s_haste_5x			="閃電速度"		s_haste_5x_d			="你能短時間爆發出高速行動。\n\n每天能在如同加速術作用下行動5輪（無需連續）。啟用此能力是一個自由動作。"-- 先決條件：敏捷25。	，每次增加5輪/天的加速效果。Each time you take the feat, it grants an additional 5 rounds of haste per day.
s_init_4x2			="高階先攻"		s_init_4x2_d			="戰鬥中，你比正常人反應更快。\n\n先攻檢定+4加值。"-- 先決條件：精通先攻	此加值已包含（而非疊加）精通先攻的加值。This bonus overlaps (does not stack with) the bonus from Improved Initiative.
s_nac_2x			="裝甲面板"		s_nac_2x_d				="你的面板如同護甲。\n\nAC+2天生防禦加值，或現有天生防禦加值增加2點。"
s_dr_3x				="傷害減免"		s_dr_3x_d				="你能減少攻擊對你造成的部分傷害。\n\n獲得傷害減免3/-。"-- 先決條件：體質21。	，但能和永久魔法效果、職業能力或此專長自身給予的傷害減免疊加	, but it does stack with any damage reduction granted by permanent magical effects, class features, or this feat itself	特殊：可多次獲得此專長，每次增加3點傷害減免。Each time you gain the feat, your damage reduction increases by 3.
s_hr_3x				="快速痊癒"		s_hr_3x_d				="你的傷口癒合得很快。\n\n獲得快速痊癒3，或現有快速痊癒增加3。"-- 先決條件：體質25。
s_imm_ill_psn		="完美體魄"		s_imm_ill_psn_d			="你免疫普通的疾病和毒素。\n\n免疫所有非魔法疾病，以及DC25及以下的毒素。"-- 先決條件：體質25，強韌加強
s_er_10x			="能量抗力"		s_er_10x_d				="你能抵抗某些型別的能量效果。\n\n選擇一種能量型別（強酸、寒冷、電擊、火焰、音波），獲得10點對此能量型別的抗力，或現有此能量型別抗力增加10點。"-- 若選了同一種能量型別，則效果疊加。if the same type of energy is chosen, the effects stack.
s_sr_2x				="強化法術抗力"	s_sr_2x_d				="你對魔法效果的天生抵抗力增加了。\n\n法術抗力+2加值。"-- 先決條件：必須有來自專長、職業特性或其他永久效果的法術抗力。Prerequisite: Must have spell resistance from a feat, class feature, or other permanent effect.
s_dk_vis_2x			="強化黑暗視覺"	s_dk_vis_2x_d			="你在黑暗中視物的能力超乎尋常。\n\n黑暗視覺距離加倍。"-- 先決條件：黑暗視覺。
s_ll_vis_2x			="強化昏暗視覺"	s_ll_vis_2x_d			="你的昏暗視覺看得更遠。\n\n昏暗視覺距離加倍。"-- 先決條件：昏暗視覺。

s_sa_ao				="藉機偷襲"		s_sa_ao_d				="一旦對手放鬆警惕，你就可以進行偷襲。\n\n你所做的任何藉機攻擊都被視為是一次偷襲。"-- 先決條件：偷襲+8d6，趁勢攻擊職業特性。
s_sa_dot			="延續傷害"		s_sa_dot_d				="你的偷襲在你出手後仍會繼續造成傷害。\n\n你成功造成偷襲傷害後，目標在你的下一回合將再次受到等同此偷襲額外傷害值的傷害。"-- 先決條件：偷襲+8d6，要害攻擊職業特性。
s_rf_as_ft			="靈活堅韌"		s_rf_as_ft_d			="你能以非凡的靈敏抵抗物理攻擊。\n\n每輪一次，當被需強韌檢定的效果作為目標時，你可以進行一個反射檢定來避免此效果（反射閃避不適用）。"-- 先決條件：敏捷25，心智靈活職業能力。
s_rf_as_wl			="靈活意志"		s_rf_as_wl_d			="你能以非凡的靈敏抵抗脅迫效果。\n\n每輪一次，當被需意志檢定的效果作為目標時，你可以進行一個反射檢定來避免此效果（反射閃避不適用）。"-- 先決條件：敏捷25，心智靈活職業能力。
s_dodge_atk			="傳奇閃避"		s_dodge_atk_d			="你能以非凡的靈敏閃避攻擊。\n\n每輪一次，當被武器攻擊命中時，你能自動避開這次攻擊的所有傷害。"-- 先決條件：敏捷 25，閃避，翻滾30級，精通反射閃避，翻躲職業特性。
s_miss_10			="自我隱蔽"		s_miss_10_d				="戰鬥中，你的形體變得模糊不清，很難被擊中。\n\n對你的攻擊有10%的失手率，類似隱蔽的效果。當你失去AC的敏捷加值時，你也會失去此效果。"-- 先決條件：敏捷30，躲藏30級，滾翻30級，精通反射閃避。
s_rage_4_2			="強力狂暴"		s_rage_4_2_d			="你的狂暴更具威力。\n\n狂暴時，力量和體質+8加值，意志檢定+4士氣加值（用這些加值替換正常狂暴加值）。"-- 先決條件：力量21，體質21，大狂暴職業特性，狂暴5次/天。
s_rage_us			="激發狂暴"		s_rage_us_d				="當你進入狂暴時，60尺內的所有盟友會受你影響全部進入狂暴（盟友可自由選擇不狂暴）。只要你仍在狂暴，盟友獲得+4力量，+4體質，以及意志豁免+2士氣加值，但AC受到-2減值。\n\n受影響盟友的狂暴持續時間等於3+他們的體質調整值，不管他們是否停留在你周圍60尺內。其他方面則與正常的野蠻人狂暴一樣（包括結束時的疲乏）。\n\n特殊：這是一個影響心靈的效果。"-- 先決條件：魅力25，大狂暴職業特性。
s_rage_chaos		="混沌狂暴"		s_rage_chaos_d			="你的狂暴對秩序生物更具傷害性。\n\n狂暴時你揮舞的任何武器均視為混沌武器（對守序陣營生物+2d6點傷害）。"-- 先決條件：狂暴5次/天，混亂陣營。	...不疊加（例如已是混沌武器）。This ability does not stack with similar abilities (for instance, if the weapon is already a chaotic weapon).
s_rage_thdr			="雷鳴狂暴"		s_rage_thdr_d			="狂暴時你發出雷鳴般得咆哮，能把敵人震聾。\n\n狂暴時你揮舞的任何武器均視為雷鳴武器。重擊時造成額外1d8點音波傷害。若武器重擊倍數為x3，則為2d8；x4則3d8。\n\n而且目標須進行一次強韌豁免檢定（DC=10+1/2你的等級+你的力量調整值），失敗則永久耳聾。"
s_rage_obj			="破壞狂暴"		s_rage_obj_d			="狂暴時你能對物體造成極大傷害。\n\n狂暴時，你的攻擊無視物體硬度。而且你在蠻力破壞物體而非造成正常傷害的力量檢定上的力量加值翻倍（包括掙脫束縛，如繩子或鐐銬）。"-- 先決條件：力量25，猛力攻擊，精通擊破武器，狂暴5次/天。
s_smite_2x			="強力重破斬"		s_smite_2x_d			="你的破邪斬或破善斬更具威力。\n\n當你成功使用破邪斬或破善斬時，在傷害值上加上兩倍的適用等級值（而非僅一倍）。"-- 先決條件：魅力25，破邪斬或破善斬（職業特性或領域賦予的能力）。
s_wpn_as_good		="神聖打擊"		s_wpn_as_good_d			="你的攻擊能對邪惡生物造成巨大傷害。\n\n你揮舞的任何武器均視為神聖武器（善良陣營，對邪惡陣營的生物造成額外2d6點傷害）。若武器已有陣營，則此專長對此武器無效。"-- 先決條件：破邪斬職業特性，任意善良陣營。
s_wpn_as_evil		="邪惡打擊"		s_wpn_as_evil_d			="你的攻擊能對善良生物造成巨大傷害。\n\n你揮舞的任何武器均視為邪惡武器（邪惡陣營，對善良陣營的生物造成額外2d6點傷害）。若武器已有陣營，則此專長對此武器無效。"-- 先決條件：破善斬職業特性，任意邪惡陣營。
s_aura_vs_fear_8	="強化勇氣靈光"	s_aura_vs_fear_8_d		="你的勇氣靈光能產生更強的作用。\n\n你的勇氣靈光在盟友對抗恐懼效果的豁免檢定上+8士氣加值。"-- 先決條件：魅力25，勇氣靈光職業特性。
s_aura_saves_n4		="強化絕望暗氣"	s_aura_saves_n4_d		="你的絕望暗氣能產生更強的作用。\n\n你的絕望暗氣在敵人所有豁免檢定上-4士氣減值。"-- 先決條件：魅力25，絕望暗氣職業特性。
s_aura_vs_fear_r20	="擴充勇氣光環"	s_aura_vs_fear_r20_d	="你的勇氣光環能影響更大的範圍。\n\n你的勇氣光環能影響100尺內的所有盟友。"-- 先決條件：魅力25，勇氣靈光職業特性。
s_aura_saves_r20	="擴充絕望暗氣"	s_aura_saves_r20_d		="你的絕望暗氣能影響更大的範圍。\n\n你的絕望暗氣能影響100尺內的所有敵人。"-- 先決條件：魅力25，絕望暗氣職業特性。
s_fav_enm_1x		="強化宿敵"		s_fav_enm_1x_d			="對宿敵的唬騙、聆聽、察言觀色、偵查、生存檢定，以及傷害骰均+1加值。"-- 先決條件：5個或更多的宿敵。
s_fav_enm_2_2d6		="宿敵剋星"		s_fav_enm_2_2d6_d		="你能對宿敵造成巨大的傷害。\n\n特殊：攻擊宿敵時，你揮舞的任何武器均視為破敵武器（+2增強加值，+2d6傷害）。"-- 先決條件：生存24級，5個或更多的宿敵（巡林客職業特性）。
s_fav_enm_kill		="宿敵殺手"		s_fav_enm_kill_d		="你一擊就能殺掉你的宿敵。\n\n當你成功重擊宿敵時，它須進行一次強韌豁免檢定（DC=10+1/2你的巡林客等級+你的感知調整值），失敗將立刻死亡。\n\n特殊：對重擊免疫的生物不受本專長影響。"-- 先決條件：宿敵剋星，生存30級，5個或更多的宿敵（巡林客職業特性）。
s_shp_ani_s2		="微型變身"		s_shp_ani_s2_d			="你能用野性變身變成微型動物。"-- 先決條件：能用野性變身變成超大型動物。	正常：若無此專長，你無法用野性變身變成超小型以下的動物。\n\nNormal: Without this feat, you cannot wild shape into an animal [of ]smaller than Tiny size.
s_shp_ani_s1		="超微型變身"		s_shp_ani_s1_d			="你能用野性變身變成超微型動物。"-- 先決條件：能用野性變身變成微型生物。	...
s_shp_ani_s8		="巨型變身"		s_shp_ani_s8_d			="你能用野性變身變成巨型動物。"-- 先決條件：能用野性變身變成超大型動物。	...超大型...Huge
s_shp_ani_s9		="超巨型變身"		s_shp_ani_s9_d			="你能用野性變身變成超巨型動物。"-- 先決條件：巨型變身	...
s_shp_plt			="植物變身"		s_shp_plt_d				="你能用野性變身變成植物。"-- 先決條件：自然知識24級，野性變身4次/天。	...形態。你能用正常的野性變身能力變身為植物。
s_shp_bug			="蟲類變身"		s_shp_bug_d				="你能用野性變身變成蟲類生物。"-- 先決條件：自然知識24級，野性變身6次/天。	...
s_shp_mbs			="魔法獸變身"		s_shp_mbs_d				="你能用野性變身變成魔法獸。你獲得所變成的魔法獸的所有超自然能力。"-- 先決條件：感知25，自然知識27級，野性變身6次/天。	...
s_shp_dgn			="龍之變身"		s_shp_dgn_d				="你能用野性變身變成龍（可選：黑龍、藍龍、綠龍、紅龍、白龍、黃銅龍、青銅龍、赤銅龍、金龍或銀龍）。你獲得所變成的龍的所有特異和超自然能力。"-- 先決條件：感知30，自然知識30級，野性變身6次/天。	...
s_shp_elm_all		="強化元素變身"	s_shp_elm_all_d			="你能變身為更多種類的元素生物。\n\n你變身為元素生物的能力可包含所有元素生物（而非僅風、土、火和水元素）。你獲得所變成的元素生物的所有特異和超自然能力。"-- 先決條件：感知25，能用野性變身變成元素。	例如，如果你通常能用野性變身變成巨型動物，你現在也能變身成巨型元素生物。\n\n正常：若無此專長，你只能用野性變身變成小型、中型或大型風、土、火或水元素。For instance, if you are normally capable of using wild shape to become a Huge animal, you can now wild shape into a Huge elemental creature.\n\nNormal: Without this feat, you may only wild shape into a Small, Medium-size, or Large air, earth, fire, or water elemental.
s_cmp_mbs			="魔法獸夥伴"		s_cmp_mbs_d				="你能與有限智力的魔法獸成為朋友。\n\n以下魔法獸新增到你能選擇的動物夥伴列表。\n1級（無調整）：蚊蝠，暗幕魔獸\n4級（-3）：鷲馬，電蜥蜴\n7級（-6）：蛇雞獸，掘地蟲，移位獸，獅鷲，梟熊，貓魚*\n10級（-9）：石化蜥蜴，恐獸，四臂猩猩，食蛛獸\n13級（-12）：鯊蜥獸，奇美拉，百足魔獸\n16級（-15）：石化牛，灰袋獸\n\n特殊：有星號標記的生物僅在水生環境可選。"-- 先決條件：自然知識24級，野性變身6次/天。
s_mus_deaf			="震耳歌謠"		s_mus_deaf_d			="你的吟唱能讓周圍生物變聾。\n\n你能用歌謠或詩歌讓你周圍30尺內的所有敵人暫時耳聾。強韌檢定（DC=10+1/2你的職業等級+你的魅力調整值）成功則無效。只要你持續演奏震耳歌謠，耳聾效果就一直持續，最多可持續演奏10輪。"-- 先決條件：表演24級，吟唱職業特性。	你可以選擇讓任何角色不受此效果影響（通常是你的盟友）。你可以一邊歌唱、演奏或朗誦一邊做其他事，但不能與魔法有關（詳見吟遊詩人的激發勇氣能力）。使用震耳歌謠計入你一天的吟唱次數。	You can choose to exclude any characters from this effect (usually your allies). You may sing, play, or recite a deafening song while taking other mundane actions, but not magical ones (see the bard's inspire courage ability for more details). Using the deafening song counts as one of your uses of song or poetics for the day.
s_mus_uncst			="擾亂歌謠"		s_mus_uncst_d			="你的吟唱能干擾敵對施法者。\n\n你能用歌謠或詩歌干擾你周圍30尺內的施法者。若想在此區域內成功施法，施法者需進行專注檢定，如同防禦式施法，且檢定上受到你等級一半的減值。最多可持續演奏擾亂歌謠10輪。"-- 先決條件：震耳歌謠，表演27級，吟唱職業特性。	...擾亂...	...hindering...
s_mus_abi			="提振潛能"		s_mus_abi_d				="你能透過表演提升同伴的能力。\n\n你能用歌謠或詩歌使盟友的一項屬性獲得加值。盟友須聽到吟唱1整輪才會受影響。吟唱時效果一直持續，停止吟唱（或聽不到吟唱）後還會持續5輪。\n\n吟唱前你必須先選擇一個屬性，被提振盟友的此屬性值+4表現加值。\n\n特殊：此專長是一種超自然、影響心靈的能力。就影響屬性的專長而言，此專長視為吟唱提振能力。"-- 先決條件：表演30級，吟唱職業特性。	吟唱時，吟遊詩人可以戰鬥但不能施法、觸發儲法物品（比如卷軸）或用指令啟動魔法物品（比如魔杖）。	使用這個專長計入你每天的吟唱次數。	While singing, the bard can fight but cannot cast spells, activate magic items by spell completion (such as scrolls), or activate magic items by command word (such as wands).	Using this feat counts as one of your uses of song or poetics for the day.	比如，你可以給所有的盟友力量加值或是體質加值，但你不能給一部分盟友力量加值，又給另一部分盟友體質加值。For instance, you could grant all allies a bonus to Strength, or all allies a bonus to Constitution, but you couldn't grant some allies a bonus to Strength and some a bonus to Constitution with the same performance.
s_mus_rng			="遠距吟唱"		s_mus_rng_d				="你的吟唱能影響更大的範圍。\n\n所有吟唱能力的影響範圍（若有）加倍。"-- 先決條件：表演25級，吟唱職業特性。	舉例來說，有這個專長的詩人唱破咒曲時影響範圍為60尺（而不是普通的30尺）；你可以使最遠180尺外的一個生物迷魂；你可以給最遠60尺內的所有盟友提振技能或提振戰力。（如果生物必須聽到吟唱才能受影響，這個條件不會改變，不管吟唱能力的範圍有多遠）。For instance, you can use countersong to protect creatures within 60 feet of you (rather than 30 feet); you can fascinate a creature up to 180 feet away; and you can inspire competence or greatness in an ally up to 60 feet away. (If the creature must hear the bard to be affected by the ability, that requirement doesn’t change regardless of any extended range the bard’s ability may have.)
s_mus_fast			="快速吟唱"		s_mus_fast_d			="你能更快得吟唱以激勵盟友。\n\n能以標準動作使用任意吟唱提振能力，動作完成後立刻生效。"-- 先決條件：表演25級，吟唱職業特性。
s_mus_dur			="持久激發"		s_mus_dur_d				="你的歌聲在你的聲音消逝很久以後仍繼續激勵著盟友。\n\n所有吟唱提振能力在吟唱結束後的持續時間（若有）為正常的10倍。"-- 先決條件：表演25級，吟唱職業特性。	（比如提振技能）(such as inspire competence)	你的吟唱提振能力在吟唱結束後效果額外持續正常10倍的時間。此專長對停止吟唱後無持續效果的提振能力無效。
s_mus_grp			="群體振奮"		s_mus_grp_d				="你的提振技能和提振戰力能同時激勵更多盟友。\n\n提振技能、提振戰力可影響的盟友數量加倍。當提振技能影響多個盟友時，可選擇給他們提振不同的技能。"-- 先決條件：表演30級，吟唱職業特性。
s_mus_1x			="傳奇吟唱"		s_mus_1x_d				="你的吟唱擁有超常的激勵效果。\n\n吟唱能力給予的所有表現加值、閃避加值和士氣加值均+1。若有提振戰力吟唱能力，則增加的HD數+1。"-- 先決條件：魅力25，表演30級，吟唱職業特性。
s_mus_mind			="神之頌謠"		s_mus_mind_d			="你的吟唱能影響那些通常免疫影響心靈效果的生物。但那些生物對抗此類效果的意志檢定+10加值。"-- 先決條件：魅力25，表演30級，吟唱職業特性。	你的吟唱能影響免疫影響心靈效果的生物。\n\n你的吟唱甚至
s_mus_unspl_anytime	="直覺破咒"		s_mus_unspl_anytime_d	="你能用破咒曲對抗音波或基於語言的魔法攻擊。\n\n你能在任何時候開始吟唱破咒曲，即使不在你的回合。因此，你可以使用破咒曲作為反應動作對抗音波或基於語言的魔法攻擊。\n\n你不能在使用其他吟唱能力時使用直覺破咒（雖然你可以停下其他吟唱能力再開始直覺破咒）。"-- 先決條件：戰鬥反射，表演30級，吟唱職業特性。	回合（就像法師準備動作反制魔法），但你無需事先準備動作	\n\n正常：若無此專長，你只能在你的回合使用破咒曲。 (much like a wizard who has readied a counterspell action), though you don’t have to ready an action to do so.	\n\nNormal: Without this feat, you can only use countersong on your turn.
s_zdd_def_6			="防禦壁壘"		s_zdd_def_6_d			="防禦姿態的加值提升為+4力量，+6體質，所有豁免檢定+4抗力加值，AC+6閃避加值。"-- 先決條件：體質25，防禦姿態3次/天。
s_zdd_def_mov_2		="移動防禦"		s_zdd_def_mov_2_d		="你能在保持防禦姿態的情況下調整站位。\n\n防禦姿態下，每輪能做一個五尺快步而不失去防禦姿態的優勢。"-- 先決條件：敏捷15，閃避，靈活移動，跳躍攻擊，防禦姿態3次/天職業特性。	正常：若無此專長，防禦姿態下不能移動。Normal: Without this feat, you can’t move while in a defensive stance.
s_zaa_da_2x			="強化死亡箭"		s_zaa_da_2x_d			="死亡箭的DC+2。"-- 先決條件：敏捷19，感知19，近程射擊，精準射擊，死亡箭職業特性。
s_zas_da_2x			="精通奪命攻擊"	s_zas_da_2x_d			="奪命攻擊的DC+2。"-- 先決條件：奪命攻擊職業特性，偷襲+5d6。

s_all_atk_1x		="傳奇神武"		s_all_atk_1x_d			="你在戰鬥中獲得了高超的技巧。\n\n所有攻擊檢定+1加值。"
s_wpn_atk_2x2		="傳奇專攻武器"	s_wpn_atk_2x2_d			="你尤其擅長使用某些武器。\n\n所有擅長武器的攻擊檢定+2加值。"-- 先決條件：專攻武器。	特殊：可多次獲得此專長，但每次必須選擇不同的武器。Special: You can gain this feat multiple times. Its effects do not stack. Each time you take the feat, it applies to a different type of weapon.
s_wpn_dmg_4x2		="傳奇專精武器"	s_wpn_dmg_4x2_d			="你使用某些武器能造成超常的傷害。\n\n使用擅長武器造成的傷害+4加值。遠端武器僅在30尺內有此傷害加值。"-- 先決條件：傳奇專攻武器，專攻武器，武器專精（都在選擇的武器上）	...
s_ch_kill			="致命重擊"		s_ch_kill_d				="你使用某些武器能一擊斃敵。\n\n當你使用擅長的近戰武器造成重擊時，目標必須進行一次強韌豁免檢定（DC=10+你的角色等級/2+你的力量調整值），失敗將立刻死亡。\n\n此專長對免疫重擊的生物無效。"-- 先決條件：力量25，順勢斬，強力順勢斬，精通重擊（必須選同一種武器）、毀滅性重擊（必須選同一種武器）、猛力攻擊、專攻武器（必須選同一種武器）。	特殊：可多次獲得此專長，但是每次必須選新的一種武器。
s_natk_pen_0		="精通多重攻擊"	s_natk_pen_0_d			="此生物特別善於同時使用其所有的天生武器。\n\n使用天生武器進行次要攻擊無減值。"-- 先決條件：三個及以上的天生武器，多重攻擊。	次要攻擊仍只能將此生物的力量加值的一半（若有）加到傷害檢定上。正常：若無此專長，此生物使用天生武器進行次要攻擊受到-5減值（若有多重攻擊專長則為-2減值）。They still add only one-half the creature’s Strength bonus, if any, to damage dealt.\n\nNormal: Without this feat, the creature’s secondary natural attacks have a –5 penalty (or a –2 penalty if it has the Multiattack feat).	[General]

s_ww_std			="精通旋風攻擊"	s_ww_std_d				="你變成一股令人眼花繚亂的劍刃風暴，同時攻擊周圍的所有敵人。\n\n以一個標準動作，對攻擊範圍內的每個對手各進行一次近戰攻擊，最多攻擊次數為你的基本攻擊加值（包括傳奇加值）/5。這些攻擊（以及你在下一輪開始前做出的所有其他攻擊）受到-4減值。"-- 先決條件：智力13，敏捷23，閃避，寓守於攻，靈活移動，跳躍攻擊，旋風攻擊。	epic attack bonus; round fractions down	\n\n使用此專長時，你還會失去其他專長或能力（比如順勢斬和加速術）帶來的獎勵或額外攻擊。\n\n由於這些攻擊都是一個標準動作的一部分，你在攻擊期間不能進行五尺快步。\n\n正常：若無此專長，旋風攻擊是整輪動作，而你可在任意兩次攻擊期間進行五尺快步。 For example, if your base attack bonus plus epic attack bonus were +24, you could make four separate melee attacks as a single standard action.\n\nWhen you use the Improved Whirlwind Attack feat, you also forfeit any bonus or extra attacks granted by other feats or abilities (such as Cleave or the haste spell).\n\nSince these attacks are made as part of a standard action, you can’t take a 5-foot step between them.\n\nNormal: Without this feat, using the Whirlwind Attack feat requires a full attack action, and you can take a 5-foot step between any two of the attacks.
s_chg_fatk_1		="恐怖衝鋒"		s_chg_fatk_1_d			="你能以整輪攻擊作為衝鋒的一部分。\n\n如果你在戰鬥的第一輪或突襲輪對某個敵人發起衝鋒，則你可對其進行整輪攻擊。"-- 先決條件：精通先攻。	（或突襲輪，若你此時能行動的話）	正常：若無此專長，你衝鋒時只能進行一次攻擊。	surprise round, if you are allowed to act in it	\n\nNormal: Without this feat, you may only make a single attack as part of a charge.
s_ao_x				="精通戰鬥反射"	s_ao_x_d				="你能在任意數量的對手放鬆警惕時作出反應。\n\n你在一輪內可進行任意多次藉機攻擊。"-- 先決條件：敏捷21，戰鬥反射。	但一次藉機仍然最多進行一次藉機攻擊。(You still can’t make more than one attack of opportunity for a given opportunity.)
s_def_cst_pen		="壓制施法者"		s_def_cst_pen_d			="受你威脅的施法者很難進行防禦式施法。\n\n任何施法者在你威脅範圍內進行防禦式施法時，專注檢定會受到-10減值。"-- 先決條件：戰鬥反射。
s_mle_undr			="穿透傷害減免"	s_mle_undr_d			="你能穿透生物的傷害減免。\n\n選擇一種特殊材料，你的近戰武器（包括天生武器）在穿透生物的傷害減免時視為用所選材料製成。特殊材料的其他特性不會應用到你的近戰武器上。"-- 你的近戰攻擊能穿透生物的傷害減免，如同你的武器是用此材料製作的。	（比如精金的忽視硬度，或煉銀武器的傷害-1） (such as adamantine’s ability to ignore hardness, or the –1 penalty to damage for silver weapons)

s_bow_no_ao			="格鬥箭術"		s_bow_no_ao_d			="你能安全地在近戰距離射箭。\n\n你能在敵人威脅範圍內射箭而不會導致藉機攻擊。"-- 先決條件：閃避，靈活移動，近程射擊。	正常：沒有這個專長，你在使用弓箭時會受到威脅你的敵人的藉機攻擊。Normal: Without this feat, you incur an attack of opportunity from all opponents who threaten you whenever you use a bow.
s_rng_no_miss_50	="離奇精確"		s_rng_no_miss_50_d		="你使用遠端武器時無視任何不高於全掩蔽或全隱蔽的情況。\n\n你的遠端攻擊無視全隱蔽導致的失手率。\n\n特殊：11級或更高等級的巡林客即使未滿足先決條件也可選擇本專長，但僅在穿著輕甲或無甲時有效。"-- 先決條件：敏捷21，基本攻擊加值+11，近程射擊，精準射擊，精通精準射擊，偵查20級。	你仍需攻擊正確的方格來獲得此專長的優勢。正常：沒有這個專長時，遠端攻擊全隱蔽的目標有50%的失手機率。You must aim your attacks at the correct square to gain the advantage of this feat.\n\nNormal: Without this feat, you suffer a 50% miss chance when making a ranged attack against a target with total concealment.
s_thr_all			="投擲風暴"		s_thr_all_d				="你化身為投擲武器的風暴，席捲附近所有對手。\n\n以一個整輪動作，使用一件魔法輕武器以最高基本攻擊加值對30尺內的每個對手各投擲一次。"-- 先決條件：敏捷23，近程射擊，即時備戰（速拔），快速射擊。	而且你可以混合使用不同的武器，比如一個人類可以混合投擲匕首、飛鏢和飛斧。All light weapons thrown need not be the same type; for instance, a human could throw a mix of daggers, darts, and throwing axes.

s_dfl_any			="卓越撥擋"		s_dfl_any_d				="你能像撥擋箭矢一樣撥擋任何遠端攻擊，包括需遠端接觸攻擊的法術。"-- 先決條件：敏捷21，感知19，撥擋飛箭，精通徒手擊打。	傳奇偏轉	你能撥擋任何型別的遠端攻擊。You can deflect any type of ranged attack.
s_rfl_any			="折返飛箭"		s_rfl_any_d				="你能把遠端攻擊折返回攻擊者身上。\n\n當你撥擋箭矢或其他遠端攻擊後，此攻擊會以你的基本遠端攻擊加值返還給攻擊者。"-- 先決條件：敏捷25，撥擋飛箭，精通徒手擊打。
s_dfl_x				="無限撥擋"		s_dfl_x_d				="每輪你能進行任意次數的撥擋。"-- 先決條件：敏捷25，戰鬥反射，撥擋飛箭，精通徒手擊打。	無限偏轉	你能撥擋無限數量的投射物。You can deflect an infinite number of projectiles.
s_grap_10			="傳奇擒抱"		s_grap_10_d				="你格外擅長擒抱。\n\n所有擒抱檢定+10加值。\n\n特殊：武僧無需精通徒手擊打即可選擇此專長。"-- 先決條件：力量21，敏捷21，精通徒手擊打，脫逃術15級。
s_unarm_law			="秩序擊打"		s_unarm_law_d			="你的徒手擊打對混亂陣營生物更具傷害性。\n\n你的徒手擊打視為守序武器（守序陣營，對混亂陣營的生物造成額外2d6點傷害）。"-- 先決條件：感知19，精通徒手擊打，震懾拳，守序陣營，鬥氣擊（守序）。	...疊加（例如其他效果已給予你的徒手擊打守序特性）。(for instance, if some other effect has granted the axiomatic property to your unarmed strike).
s_unarm_ch3			="鋒銳擊打"		s_unarm_ch3_d			="你的徒手擊打利如劍刃。\n\n你的徒手擊打具有重擊範圍18-20且造成揮砍傷害（你可選擇造成鈍擊傷害，但無法享有增強的重擊範圍）。"-- 先決條件：力量23，感知23，精通重擊（徒手擊打），精通徒手擊打，震懾拳，鬥氣擊（精金）。	此能力不與其他擴充套件徒手擊打重擊範圍的能力疊加。This ability doesn’t stack with other abilities that expand your unarmed strike’s threat range.
s_unarm_kill		="斬首擊打"		s_unarm_kill_d			="你的徒手擊打能將對手斬首。\n\n你的徒手擊打視為揮砍型斬首武器（你可選擇造成鈍擊傷害，但會失去斬首特性）。"-- 先決條件：力量25，感知25，精通重擊（徒手擊打），精通徒手擊打，銳鋒擊打，震懾拳，鬥氣擊（精金）。	碎顱擊	...疊加（例如其他效果已給予你的徒手擊打斬首特性）。(for instance, if some other effect has already granted your unarmed strikes the vorpal quality).

s_spl_dc_1			="法術專攻"		s_spl_dc_1_d			="你的某些魔法學派的法術比其他法術強力得多。\n\n所選學派的法術豁免檢定DC+1加值。"-- 法術專攻 專攻法術	選擇一個法術學派。所選擇學派的法術的所有豁免檢定DC都獲得+1加值。特殊：你可以多次選擇本專長。其效果並不累加。每次必須選擇不同的學派。高等專攻法術	選擇一個你已經擁有專攻法術專長的法術學派。效果：所選擇學派的法術的豁免檢定DC都獲得+1加值。該加值與專攻法術的加值可累加。特殊：你可以多次選擇此專長，其效果並不累加。每次你都必須選擇不同的已擁有專攻法術的學派。Choose a school of magic. Add +1 to the Difficulty Class for all saving throws against spells from the school of magic you select. Special: You can gain this feat multiple times. Its effects do not stack. Each time you take the feat, it applies to a new school of magic. Greater Spell Focus	Choose a school of magic to which you already have applied the Spell Focus feat. Add +1 to the Difficulty Class for all saving throws against spells from the school of magic you select. This bonus stacks with the bonus from Spell Focus. Special: You can gain this feat multiple times. Its effects do not stack. Each time you take the feat, it applies to a new school of magic to which you already have applied the Spell Focus feat.
s_spl_dc_2			="高等法術專攻"	s_spl_dc_2_d			=s_spl_dc_1_d
s_spl_dc_3			="傳奇法術專攻"	s_spl_dc_3_d			=s_spl_dc_1_d
s_spl_unsr1			="法術穿透"		s_spl_unsr1_d			="你的法術十分強力，較容易戰勝目標的法術抗力。\n\n對抗目標的法術抗力時，你的施法者等級檢定+2加值。"
s_spl_unsr2			="高等法術穿透"	s_spl_unsr2_d			="你的法術特別強力，比正常情況下更容易戰勝法術抗力。\n\n對抗目標的法術抗力時，你的施法者等級檢定+2加值。"
s_unsr_6			="傳奇法術穿透"	s_unsr_6_d				="你的法術極度強力，能輕鬆突破法術抗力。\n\n對抗目標的法術抗力時，你的施法者等級檢定+2加值。"
s_spl_summ1			="強效召喚"		s_spl_summ1_d			="召喚生物力量+4加值，體質+4加值。"
s_spl_elem1			="塑能專精"		s_spl_elem1_d			="塑能系傷害性法術的傷害檢定+2加值。"
s_cst_no_ao			="精通戰鬥施法"	s_cst_no_ao_d			="你在受威脅時施法不會引發藉機攻擊。"-- 先決條件：戰鬥施法，專注25級。	你在受威脅時施法不必擔心被攻擊。You can cast spells while threatened without fear of being attacked.
s_spl_add_2x		="奧術知識"		s_spl_add_2x_d			="你習得兩個新奧術，其等級不超過你能施展的最高等級。"-- 先決條件：能夠施展某一奧術施法者職業正常所能施展的最高階法術。Ability to cast spells of the maximum normal spell level of an arcane spellcasting class.	此專長不會帶來額外的法術位。This feat does not grant any additional spell slots.	將兩個額外的奧術新增到你的法術列表。You add two additional arcane spells to your repertoire.
s_spl_cpy_1x		="法術仿製"		s_spl_cpy_1x_d			="選擇一個你擁有的類法術能力或能施放的法術。一旦該魔法在你附近被使用，你就能獲得其效果。\n\n你與所選魔法高度同調。若另一施法者在你周圍300尺內使用該魔法，你也能立刻獲得該魔法的效果，就如同那個施法者將該魔法用在你身上一樣。\n\n你與施法者之間必須有直接的效果線以獲得該同調魔法的好處（雖然你不必知道施法者的存在，而且你可以處於措手不及狀態）。魔法的持續時間、效果等細節由其原施法者的等級決定。"-- 先決條件：辨識法術24級，施法者等級12。
s_spl_cvt_1x		="自發施法"		s_spl_cvt_1x_d			="選擇一個你能施放的法術，你能將任何準備好的同級法術自發轉化成所選法術，就像牧師引導能量將其他法術轉化成治療法術一樣。"-- 先決條件：辨識法術25級，能夠施展至少一個施法者職業所能施展的最高階法術。	ability to cast the maximum normal spell level of at least one spellcasting class.	選擇一個你能施放的法術。你能將其他同級法術自發轉化為該法術。You can spontaneously convert spells of that spell’s level into that spell.

s_sf_3				="技能專攻"		s_sf_3_d				="所選技能的所有相關檢定+3加值。"
s_sf_10				="傳奇技能專攻"	s_sf_10_d				="你在某些技能上有著非凡的造詣。\n\n所選技能的所有相關檢定+10加值。"-- 先決條件：所選技能等級20。	Choose a skill, such as Move Silently.選擇一個技能，例如潛行。你在該技能上有著非凡的造詣。特殊：可多次獲得此專長，每次須選擇不同的技能。You can gain this feat multiple times. Its effects do not stack. Each time you take the feat, it applies to a different skill.
s_sf_4_rep			="傳奇名望"		s_sf_4_rep_d			="你的名聲在與他人的互動中能提供極大的增益。\n\n唬騙、交涉、收集資訊、威嚇、表演檢定+4加值。"
s_polyglot			="全語通"		s_polyglot_d			="你會說任何語言。若識字，你還能讀寫任何語言（不包括魔法符文）。"-- 先決條件：智力25，語言（五種語言）。	magical script	你會說、讀、寫任何語言。You can speak, read, and write all languages.
s_bus_svy			="商業頭腦"		s_bus_svy_d				="你在建立和經營盈利的商業上非常有天賦。\n\n所有盈利檢定+2加值。此外，在解決任何與商業有關的事件時，所有的攻擊檢定、豁免和其他檢定+1運氣加值。"
-- z_add_pwr
s_wis_melee			="禪宗武術"		s_wis_melee_d			="近戰攻擊時，你可以在攻擊檢定中使用你的感知調整值代替力量調整值。"
s_str_throw			="蠻力投擲"		s_str_throw_d			="使用投擲武器進行遠端攻擊時，你可以在攻擊檢定中使用你的力量調整值代替敏捷調整值。"
s_quick_draw		="即時備戰"		s_quick_draw_d			="拔取或切換武器的動作視為即時動作，而非移動動作，且不會引發藉機攻擊。"
s_atk_m_dmg2		="蓄力攻擊"		s_atk_m_dmg2_d			="單次近戰攻擊造成2倍傷害。即使失手也能造成一半傷害。"..use_a
s_atk_m_dmg3		="精通蓄力攻擊"	s_atk_m_dmg3_d			="蓄力攻擊的傷害提升為3倍。"
s_atk_m_dmg4		="高等蓄力攻擊"	s_atk_m_dmg4_d			="蓄力攻擊的傷害提升為4倍。"
s_atk_r_dmg2		="蓄力射擊"		s_atk_r_dmg2_d			="單次遠端攻擊造成2倍傷害。即使失手也能造成一半傷害。"..use_a
s_atk_r_dmg3		="精通蓄力射擊"	s_atk_r_dmg3_d			="蓄力射擊的傷害提升為3倍。"
s_atk_r_dmg4		="高等蓄力射擊"	s_atk_r_dmg4_d			="蓄力射擊的傷害提升為4倍。"

s_pa				="猛力攻擊"		s_pa_d					=[[以超出的近戰攻擊加值換取傷害。

當你的近戰攻擊加值高過對手的防禦等級時，超出部分自動轉化為傷害加值（最多為你的基本攻擊加值）。

當以雙手武器攻擊，或雙手持握一把單手武器，或唯一主要天生武器，此傷害加值翻倍；而輕武器則無此傷害加值（除了徒手攻擊或天生武器）。]]--pa_note		= "\n\n無需主動使用，條件符合時自動生效（如目標等級很低或處於睡眠昏迷等狀態）。"	pa_note			= "\n\nNo need to use actively, the feat takes effect automatically when the conditions are met (e.g. target of very low level or stunned)."	pa_note			= "\n\nPas besoin de l'utiliser activement, le don prend effet automatiquement lorsque les conditions sont réunies (par exemple cible de très bas niveau ou étourdi)."	pa_note			="\n\nこの特技は積極的に使用する必要はなく、條件が満たされれば（例えば、非常に低いレベルのターゲットや朦朧狀態の場合）自動的に有効になる。"
pwr_rng_pa_n		="猛力射擊"		pwr_rng_pa_d	="類似<t=@pwr_pa c=fc_b>猛力攻擊</t>，但應用於遠端攻擊（除了傷害加值翻倍規則）。"

s_tw			="雙武器戰鬥"		s_tw_d			=[[你可以兩手各持一把武器戰鬥。你每輪可以用第二把武器做一次額外攻擊。

以這種方式進行戰鬥時，你的常規攻擊或主手攻擊會受到-6的減值，而你的副手攻擊則會受到-10的減值。

你可以用以下兩種方法來降低這些減值：
- 若你副手為輕型武器，則雙手減值各降低2（徒手攻擊始終視為輕型武器）。
- 雙武器戰鬥專長可以使主手減值降低2，副手減值降低6。

下表歸納了所有這些因素組合作用時的效果。

雙武器戰鬥減值：
<b>情況			主手	副手</b>
正常減值		-6	-10
副手輕武器		-4	-8
雙武器戰鬥專長		-4	-4
專長 + 輕武		-2	-2

<b>雙頭武器：</b>你可以使用雙頭武器副手端所在的那一頭進行一次額外攻擊，如同使用兩把武器戰鬥一樣。計算減值時，副手端所在的那一頭視為一把輕型武器。]]
s_hr_tw_ratk_2	="<t=$s_tw_nd c=fc_b>雙武器戰鬥</t>：常規攻擊時也有額外的一次副手攻擊<c=twa>（未選：僅全力攻擊時）</c>"
pwr_tw_n		="雙武器戰鬥"		pwr_tw_d		="降低你使用兩把武器戰鬥時受到的減值。你的主手減值降低2，副手減值降低6。\n\n通常："..s_tw_d
pwr_tw1_n		="精通雙武器戰鬥"		pwr_tw1_d		="除了原本額外的一次副手攻擊外，你還可以用副手多攻擊一次，但有-5減值。"
pwr_tw2_n		="高等雙武器戰鬥"		pwr_tw2_d		="你可以用副手武器作出第三次攻擊，但有-10減值。"
pwr_tw3_n		="完美雙武器戰鬥"		pwr_tw3_d		="你可以用副手武器進行和主手相同的攻擊，包括相同的攻擊次數，相同的基本攻擊加值。你仍會受到使用雙武器戰鬥的減值。"
pwr_tw_def_n	="雙武器防禦"		pwr_tw_def_d	="當舞動一把雙頭武器或兩把武器（不包括天生武器或徒手擊打）時，你的防禦等級獲得+1盾牌加值。\n\n當你進行全力防禦時，此盾牌加值增加為+2。"
pwr_tw_def1_n	="精通雙武器防禦"		pwr_tw_def1_d	="雙武器防禦的加值翻倍。"
pwr_tw_off_n	="雙切"				pwr_tw_off_d	="副手傷害應用全部力量加值。\n\n你的副手武器在傷害上獲得你的全部力量加值。通常你在副手武器上只能將力量調整值的一半計入傷害投骰。\n\n本專長也適用於猛力攻擊和衝鋒的額外傷害加成。"
pwr_tw_rend_n	="雙武器撕裂"		pwr_tw_rend_d	="近戰雙武器同時命中時，撕裂對手。\n\n若你主手武器和副手武器的攻擊都命中對手，則你額外造成1d10+1.5倍你的力量調整值的傷害。撕裂傷害導致的死亡不引發順勢斬。"

pwr_th_n="雙手武器戰鬥"	pwr_th_d="近戰雙手武器的傷害檢定+2加值。"
pwr_th1_n="精通雙手武器戰鬥"	pwr_th1_d="雙手武器戰鬥的加值再+2。"
pwr_th_ko_n="擊倒"	pwr_th_ko_d="近戰雙手武器命中時，10%機率觸發擊倒檢定，目標戰技對抗失敗則倒地。"
pwr_th_ko1_n="精通擊倒"	pwr_th_ko1_d="擊倒的機率變為20%。"
pwr_th_atk1_n="雙手武器專攻"	pwr_th_atk1_d="近戰雙手武器的攻擊檢定+1加值。"

pwr_rng_near_n="近程射擊"		pwr_rng_near_d="使用遠端武器攻擊30英尺內的目標時，攻擊和傷害檢定+1加值。"
pwr_rng_far_n="遠端射擊"	pwr_rng_far_d="當你使用彈射類武器時（如弓），射程增加1/2（即乘1.5）。當你使用投擲類武器時，射程翻倍。"-- 特殊：戰士可以選擇本專長作為其戰士獎勵專長。Special: A fighter may select Far Shot as one of his fighter bonus feats.	range increment
pwr_rng_precise_n="精準射擊"	pwr_rng_precise_d="遠端攻擊混戰中的目標不受減值。\n\n你對處於混戰中的對手進行遠端攻擊時不需在攻擊上承受通常的-4減值。"
pwr_rng_precise1_n="精通精準射擊"	pwr_rng_precise1_d="你的遠端攻擊忽略所有掩蔽和隱蔽效果，除了完全掩蔽或完全隱蔽。\n\n此外，當你遠端攻擊處於擒抱狀態的目標時，你不會誤傷（無此專長則需投隨機骰來確定究竟攻擊到誰）。"-- 除全掩蔽以外，你的遠端攻擊忽略任何其他較弱事物給目標帶來的防禦等級，同時除全隱蔽外，你還忽視任何其他較弱事物給目標帶來的失手機率。全掩蔽和全隱蔽仍對你的遠端攻擊起正常作用。此外...你自動命中你選定的敵人	正常：掩蔽和隱蔽效果見其正常規則。無此專長的角色向擒抱中的敵人射擊或投擲遠端武器時必須投隨機骰來確定該攻擊究竟攻擊到誰。	戰士可以選擇本專長作為其戰士獎勵專長。	A fighter may select Improved Precise Shot as one of his fighter bonus feats.	No cover or concealment chance on ranged attacks.	Your ranged attacks ignore the AC bonus granted to targets by anything less than total cover, and the miss chance granted to targets by anything less than total concealment. Total cover and total concealment provide their normal benefits against your ranged attacks.	Normal: See the normal rules on the effects of cover and concealment. Without this feat, a character who shoots or throws a ranged weapon at a target involved in a grapple must roll randomly to see which grappling combatant the attack strikes.
pwr_atk_r_atk2_n="快速射擊"	pwr_atk_r_atk2_d="你使用遠端武器時，每輪可以多攻擊一次。這次攻擊基於你最高基本攻擊加值，但該輪內所有攻擊檢定（額外的這次和正常的那些）均有-2減值。你必須在全力攻擊時使用本專長。"
pwr_atk_r_atk2_1_n="精通快速射擊"	pwr_atk_r_atk2_1_d="免除快速射擊的懲罰。"
pwr_atk_r_atk2_2_n="高等快速射擊"	pwr_atk_r_atk2_2_d="快速射擊的攻擊次數變為3次。"
pwr_atk_r_tgt3_n="多重射擊"	pwr_atk_r_tgt3_d="對指定範圍內的多個敵人，分別進行一次遠端攻擊。所有攻擊基於你最高基本攻擊加值，但有-2減值。"..use_a
pwr_atk_r_tgt3_1_n="精通多重射擊"	pwr_atk_r_tgt3_1_d="免除多重射擊的懲罰。"
pwr_atk_r_tgtx_n="箭雨"	pwr_atk_r_tgtx_d="對遠端攻擊範圍內的所有敵人，分別進行一次遠端攻擊。所有攻擊基於你最高基本攻擊加值，但有-2減值。"..use_b
pwr_atk_r_tgtx_1_n="精通箭雨"	pwr_atk_r_tgtx_1_d="免除箭雨的懲罰。"
pwr_rng_xbow_n="弩狙擊"	pwr_rng_xbow_d="弩類武器的傷害檢定+2加值。"
pwr_rng_wis_n="禪宗箭術"	pwr_rng_wis_d="遠端攻擊時，你可以在攻擊檢定中使用你的感知調整值代替敏捷調整值。"--不適用於重投擲。 Not for heavy thrown weapons. Ne fonctionne pas sur les armes lourdes.重投擲武器には適用不可。

pwr_stunning_fist_d=[[
你徒手攻擊打出的震懾拳除正常造成傷害外，還進行一次強韌檢定（你的角色等級/2 + 感知調整值 vs 目標的強韌防禦），成功則目標被<t=@cond_stunned_nd c=r>震懾</t>一輪。

每天使用次數：武僧等級 + 非武僧等級/4。
每輪最多使用1次。攻擊失手時也會消耗次數。
]]-- 一般專長 敏捷13、感知13、精通徒手擊打、基本攻擊加值+8。	被震懾的生物無法行動，防禦等級上失去所有敏捷加值，並且還有-2減值。	構裝生物、泥狀怪物、植物、不死生物、虛體生物和免疫重擊的生物無法被震懾。	攻擊之前必須先宣佈使用本專長（因此，若攻擊檢定失敗則即失去該次嘗試機會）。	特殊：武僧可以在1級時選擇本專長作為獎勵專長，即使未滿足先決條件。選擇了本專長的武僧每天可以使用震懾攻擊的次數等於其武僧級別加上非武僧級別除以四。戰士可以選擇本專長作為戰士的獎勵專長。

pwr_ch_mle_dmg_d=[[
使用擅長的近戰武器重擊時，能造成額外傷害：
若武器致命係數為x2，加1d6點傷害。
若武器致命係數為x3，加2d6點傷害。
若武器致命係數為x4，加3d6點傷害。

此專長對免疫重擊的生物無效。
]]-- Epic 選擇一種近戰武器（如長劍或巨斧），此武器的重擊效果更強。	力量23，猛力攻擊，順勢斬，強力順勢斬，精通重擊（同一種武器），專攻武器（同一種武器）。	特殊：你可以多次選擇本專長。效果不累加。每次你獲得此專長，其應用於新的武器型別。

pwr_rage_fear_d=[[
狂暴時，你能讓對手陷入恐慌。

當你狂暴時，所有看見你的敵人都必須進行一次意志檢定（你的威嚇等級 vs 敵人的意志防禦），成功時：

若敵人角色等級 ＜ 你的角色等級，則陷入恐慌，持續1d4輪。

若敵人角色等級 ≥ 你的角色等級但 ≤ 你的人物等級x2，則陷入戰慄，持續1d4輪。

若敵人角色等級 ＞ 你的角色等級x2，則不受影響。
]]-- Epic 	威嚇25級，5次狂暴/每天。Intimidate 25 ranks, rage 5/day.

pwr_unarmed_strike_d=[[
武僧受過嚴格的徒手戰鬥訓練，徒手作戰時具有很強的威力。

武僧的攻擊可以用雙拳，也可以用肘、膝、或腳，所以即使雙手都拿著東西仍可使用徒手攻擊。武僧徒手攻擊時也無主副手之分，總是將完整的力量加值加到傷害骰上。

隨著武僧等級的提升，其徒手擊打擁有更多的攻擊次數（6、14、18級時各增加1次）和更高的傷害。

各體型武僧徒手擊打傷害表：
等級	小體型	中體型	大體型
1	1d4	1d6	1d8
4	1d6	1d8	2d6
8	1d8	1d10	2d8
12	1d10	2d6	3d6
16	2d6	2d8	3d8
20	2d8	2d10	4d8

<c=o>此能力作為開關能力開啟時，近戰始終徒手攻擊，即使正持握近戰武器。</c>
]]-- z_lv_dmg_dice	通常武僧的徒手攻擊造成的是正常傷害，不過他也可以選擇造成非致命傷而不必受到任何命中減值。在擒抱時他同樣可以選擇造成何種傷害。	在考慮增強人工武器或天生武器的法術效果時，武僧的徒手攻擊既視為人工武器又視為天生武器。	當使用法術效果（例如「魔牙術」或「魔化武器」）來提升或強化人造武器或天生武器時，武僧的徒手攻擊可被同時視為人造及天生武器。		武僧的攻擊可以用雙拳，也可以用肘，膝，或腳。這意味著武僧甚至可以在雙手都拿著東西的情況下進行徒手攻擊。對武僧的徒手攻擊來說，沒有副手攻擊這個概念。武僧可以將其完整的力量加值加在所有的徒手攻擊上。

pwr_flurry_of_blows_d=[[
未著防具時，武僧可以犧牲準確性來換取疾風連擊的能力。

1級：	額外攻擊1次。本輪所有攻擊檢定-2減值。
5級：	減值降為-1。
9級：	無減值。
11級：	額外攻擊2次。

必須徒手或使用特殊武僧武器進行疾風連擊。徒手時，徒手擊打本身的額外攻擊次數也生效。

疾風連擊的傷害骰上總是應用完整的力量加值。

當穿著盔甲、持用盾牌、中載或過載時，無法使用此能力。
]]-- Ex	（單鐮、雙截棍、木棍、十手、手裡劍、破魔椎）	11級起，額外攻擊次數再+1。	當使用武器時，無論單手或雙手持用，傷害骰上都應用完整的力量加值。	可以交替使用徒手和武僧武器進行攻擊。	不能使用非武僧武器來做疾風攻擊。	如果使用的武器是木棍，在進行疾風連擊時木棍的兩頭當作是不同的武器。即使木棍需要雙手持用，只要疾風連擊的攻擊次數允許，武僧仍然能使用徒手攻擊。例如8級武僧進行疾風連擊時可攻擊三次，他可以使用木棍攻擊兩次（分別用木棍兩端），攻擊加值為+5，第三次使用徒手攻擊，攻擊加值為+0。他也可以使用木棍攻擊一次，徒手攻擊一次，兩次的攻擊加值皆為+5，再用木棍攻擊第三次，攻擊加值為+0。不過在持用木棍時不能再持用其他武器。	（而非1+1/2或1/2的力量加值）	pf 8級額外攻擊2次 15級3

pwr_ac_bonus_d=[[
武僧受過良好的閃避訓練，具有獨特的第六感，可以下意識地躲開攻擊。

未著防具且未超重時，武僧可將感知加值加到防禦上。此外，每5個武僧等級獲得+1加值（5級+1，10級+2…）。

即使面對接觸攻擊或措手不及，這些加值仍有效。但若動彈不得、陷入無助、穿著盔甲或法袍等、持用盾牌、中載或過載時，則會失去這些加值。
]]-- Ex	pf 每4級 也用於cmd

pwr_ki_atk_d=[[
武僧的徒手攻擊中灌注著真氣，隨著武僧等級提升而增強。

徒手攻擊每5級+1增強加值（5級時+1，10級時+2…）。

穿透傷害減免時，其徒手攻擊視為特定型別的武器：
4級：	魔法武器
7級：	寒鐵和煉銀武器
10級：	守序武器
16級：	精金武器

<c=o>（寒鐵和守序武器相關怪物開發中）</c>
]]-- 攻破硬度時視為精金	pf 氣運丹田	氣池

pwr_quivering_palm_d=[[
武僧能使用恐怖的滲透勁，在其他生物體內製造致命的震盪。

此能力開啟時，若武僧擊中目標且造成傷害，則滲透勁攻擊成功。

此後任意時刻，武僧可嘗試直接用意念殺死目標：武僧等級/2 + 感知調整值 vs. 目標強韌，成功則目標死亡，失敗則此滲透勁失效。

此能力對免疫重擊的生物無效。]]-- 此後武僧等級天數內	武僧能在其他生物體內製造一種震盪，之後如果武僧願意，這震動足以致命。	對方將不會再因這次滲透勁而受到傷害，但是他依然可能被之後其他滲透勁攻擊所傷。	這之後武僧可以在一定天數內嘗試殺死對方，該時間期限天數為他的武僧等級。要做殺死對方，武僧只需要用意念讓對方死即可（即時動作），如果對方沒有通過強韌檢定（DC=10+1/2武僧等級+武僧感知修正），它就死了。如果該豁免檢定獲得成功，對方將不會再因這次滲透勁而受到傷害，但是他依然可能被之後其他滲透勁攻擊所傷。	滲透勁無法作用於構裝生物、泥形生物、植物、不死生物、虛體生物和無法遭受重擊的生物。	只須心中想著要使目標死亡（即時動作），目標便須進行強韌檢定（DC=10+武僧等級的一半+武僧感知調整值），若失敗則死亡。如果目標通過強韌檢定，則不會再受此次滲透勁所威脅（但或許下次又中了滲透勁）。

pwr_empty_body_d=[[
武僧能進入以太位面，化成靈體。

此能力持續期間，武僧身處以太位面，一個與正常主物質位面重疊共存的世界。能力結束時，武僧將返回主物質位面，變回實體。每日總維持輪數=武僧等級，可分多次使用。

對於主物質位面而言，靈體不可見也摸不到。而它可看見和聽見主物質位面，但一切看上去都是灰色的模糊的。它在主物質位面的視覺與聽覺範圍為60英尺。

一般而言，靈體生物和實體生物無法攻擊對方。而靈體生物或物品之間則如同均為實體。

另外，作為沒有實體的生物，靈體可以穿越主物質位面的固體，包括活物。若能力結束時它仍在固體中（如牆體），則會被擠到最近的空地，每經過5英尺遭受1d6點傷害。
]]-- pf 1分鐘


