pwr_harm2_x_d="類似重傷術，但針對多個目標。"
--[[
治療輕傷（Cure Light Wounds）
 咒法系（醫療）
等級：吟遊詩人1，牧師1，德魯伊1，醫療1，聖武士1，巡林客2
法術成分：言語，姿勢
施法時間：一個標準動作
距離：接觸
目標：接觸到的生物
持續時間：立即
豁免檢定：意志，通過則效果減半（無害）；見說明
法術抗力：可（無害）；見說明

用你的手掌接觸一個活著的生物並將正能量匯入，治療1d8點傷害，每施法者等級再+1點（最高5點）。

因為不死生物的能源為負能量，這個法術會對它們造成傷害而非治療。一個不死生物可以應用法術抗力抵抗，也可通過意志豁免檢定將傷害減半。

Cure Light Wounds
 Conjuration (Healing)
Level: Brd 1, Clr 1, Drd 1, Healing 1, Pal 1, Rgr 2
Components: V, S
Casting Time: 1 standard action
Range: Touch
Target: Creature touched
Duration: Instantaneous
Saving Throw: Will half (harmless); see text
Spell Resistance: Yes (harmless); see text

When laying your hand upon a living creature, you channel positive energy that cures 1d8 points of damage +1 point per caster level (maximum +5).

Since undead are powered by negative energy, this spell deals damage to them instead of curing their wounds. An undead creature can apply spell resistance, and can attempt a Will save to take half damage.

造成輕傷（Inflict Light Wounds）
 死靈系
等級：牧師 1，破壞 1
法術成分：言語，姿勢
施法時間：1個標準動作
距離：接觸
目標：接觸到的生物
持續時間：立即
豁免：意志，通過則減半
法術抗力：可

當你的手放在生物身體上時，你引導負能量造成1d8+每施法者等級1點（最多+5）傷害。

由於不死生物是用負能量作為能源，因此該法術治療等量的傷害，而不是傷害它們。

Inflict Light Wounds
 Necromancy
Level: Clr 1, Destruction 1
Components: V, S
Casting Time: 1 standard action
Range: Touch
Target: Creature touched
Duration: Instantaneous
Saving Throw: Will half
Spell Resistance: Yes

When laying your hand upon a creature, you channel negative energy that deals 1d8 points of damage +1 point per caster level (maximum +5).

Since undead are powered by negative energy, this spell cures such a creature of a like amount of damage, rather than harming it.

醫療術（Heal）
 咒法系（醫療）
等級：牧師 6，德魯伊 7，醫療 6
法術成分：言語，姿勢
施法時間：1個標準動作
距離：接觸
目標：接觸到的生物
持續時間：立即
豁免：意志，通過無效（無害）
法術抗力：可（無害）

你可以匯入正能量來醫治疾病和損傷。此法術可瞬間終結目標所受的所有以下不良狀態：屬性傷害（ability damage），目盲（blinded），困惑（confused），暈眩（dazed），目眩（dazzled），耳聾（deafened），疾病（diseased），力竭（exhausted），疲乏（fatigued），弱智術（feebleminded），精神錯亂（insanity），反胃（nauseated），噁心（sickened），震懾（stunned），以及中毒（poisoned）。同時醫療每施法者等級10點傷害，最高達到15級150點。

醫療術無法移除負向能級，也無法回覆被永久吸取的等級或被永久吸取的屬性值。

當作用於不死生物時，其作用如同重傷術（harm）。

Heal
 Conjuration (Healing)
Level: Clr 6, Drd 7, Healing 6
Components: V, S
Casting Time: 1 standard action
Range: Touch
Target: Creature touched
Duration: Instantaneous
Saving Throw: Will negates (harmless)
Spell Resistance: Yes (harmless)

Heal enables you to channel positive energy into a creature to wipe away injury and afflictions. It immediately ends any and all of the following adverse conditions affecting the Target: ability damage, blinded, confused, dazed, dazzled, deafened, diseased, exhausted, fatigued, feebleminded, insanity, nauseated, sickened, stunned, and poisoned. It also cures 10 hit points of damage per level of the caster, to a maximum of 150 points at 15th level.

Heal does not remove negative levels, restore permanently drained levels, or restore permanently drained ability score points.

If used against an undead creature, heal instead acts like harm.

重傷術（Harm）
 死靈系
等級：牧師 6,破壞 6
法術成分：言語，姿勢
施法時間：1個標準動作
距離：接觸
目標：接觸到的生物
持續時間：立即
豁免：意志，通過減半; 見下文
法術抗力：可

重傷術將負能量充入一個目標，這會造成每施法者等級10點的傷害（最高可達到15級時的150點）。如果該生物成功通過豁免，則重傷術只會造成一半傷害，但此時該法術無法讓目標的生命降至比1更少。

當作用於不死生物時，其作用如同醫療術（heal）。

Harm
 Necromancy
Level: Clr 6, Destruction 6
Components: V, S
Casting Time: 1 standard action
Range: Touch
Target: Creature touched
Duration: Instantaneous
Saving Throw: Will half; see text
Spell Resistance: Yes

Harm charges a subject with negative energy that deals 10 points of damage per caster level (to a maximum of 150 points at 15th level). If the creature successfully saves, harm deals half this amount, but it cannot reduce the target's hit points to less than 1.

If used on an undead creature, harm acts like heal.

群體治療輕傷（Cure Light Wounds, Mass）
 咒法系（醫療）
