法術抗力：可（無害）；見說明
 你將正能量匯入每一個被挑選的生物，治癒他們1d8+1點傷害，每施法者等級再+1點（最高25點）。
 和其他治療法術一樣，群體治療輕傷會對區域內的不死生物造成正能量傷害而非治療。每一個受影響的不死生物都可以做一個意志豁免檢定來將傷害減半。

