pwr_slay_live_d="你可以殺死任何活物。你必須通過近戰接觸攻擊成功的接觸到對方，而對方可以通過強韌豁免來避免死亡。如果對方豁免成功，那麼它只會受到每3級1d6+每級1點傷害。"
pwr_dead_finger_d="你能殺死任何距離內的一個活物。目標可以進行一次強韌豁免來避免被殺。如果該豁免成功，該生物將只受到每4級1d6+每級1點傷害。"
pwr_wail_of_the_banshee_d="你發出恐怖的尖叫，聞者皆亡（除了你自己）。"
--[[
殺生術（Slay Living）
 死靈系 [死亡]
等級：牧師 5，死亡 5
法術成分：言語，姿勢
施法時間：一個標準動作
距離：接觸
目標：被接觸的活物
持續時間：立即
豁免：強韌，通過則部分有效
法術抗力：可

你可以殺死任何活物。你必須通過近戰接觸攻擊成功的接觸到對方，而對方可以通過強韌豁免來避免死亡。如果對方豁免成功，那麼它只會受到3d6+每施法者等級1點傷害。

Slay Living
 Necromancy [Death]
Level: Clr 5, Death 5
Components: V, S
Casting Time: 1 standard action
Range: Touch
Target: Living creature touched
Duration: Instantaneous
Saving Throw: Fortitude partial
Spell Resistance: Yes

You can slay any one living creature. You must succeed on a melee touch attack to touch the subject, and it can avoid death with a successful Fortitude save. If it succeeds, it instead takes 3d6 points of damage +1 point per caster level.

死亡一指（Finger of Death）
 死靈系[死亡]
等級：德魯伊 8，術士/法師 7
法術成分：言語，姿勢
施法時間：一個標準動作
距離：近距（25英尺+5英尺/每2等級）
目標：一個活物
持續時間：立即
豁免：強韌，通過則部分生效
法術抗力：可

你能殺死任何距離內的一個活物。目標可以進行一次強韌豁免來避免被殺。如果該豁免成功，該生物將只受到3d6+1/每施法者等級（最多+25）的傷害。

即便目標豁免成功，它依然有可能因為受到傷害而死亡。

Finger of Death
 Necromancy [Death]
Level: Drd 8, Sor/Wiz 7
Components: V, S
Casting Time: 1 standard action
Range: Close (25 ft. + 5 ft./2 levels)
Target: One living creature
Duration: Instantaneous
Saving Throw: Fortitude partial
Spell Resistance: Yes

You can slay any one living creature within range. The target is entitled to a Fortitude saving throw to survive the attack. If the save is successful, the creature instead takes 3d6 points of damage +1 point per caster level (maximum +25).

The subject might die from damage even if it succeeds on its saving throw.

女妖之嚎（Wail of the Banshee）
 死靈系[死亡，音波]
等級：死亡9，術士/法師9
法術成分：言語
施法時間：1個標準動作
距離：近距（25英尺+5英尺/2等級）
區域：40英尺擴散範圍內，1個活物/等級
持續時間：立即
豁免：強韌，通過則無效
法術抗力：可

你發出恐怖的尖叫，聞者皆亡（除了你自己）。最接近源發點的生物最先受影響。

Wail of the Banshee
 Necromancy [Death, Sonic]
Level: Death 9, Sor/Wiz 9
Components: V
Casting Time: 1 standard action
Range: Close (25 ft. + 5 ft./2 levels)
Area: One living creature/level within a 40-ft.-radius spread
Duration: Instantaneous
Saving Throw: Fortitude negates
Spell Resistance: Yes

You emit a terrible scream that kills creatures that hear it (except for yourself ). Creatures closest to the point of origin are affected first.
]]


pwr_false_life_d="控制反生命的力量讓你獲得能在一定限度內避開死亡的能力。當此法術生效時，你獲得每3級1d10+每級1點的暫時生命值。"
pwr_aid_d="援助術給目標的攻擊投骰和對抗恐懼效果的豁免上提供+1士氣加值，外加每3級1d8+每級1點的暫時生命值。"
pwr_death_knell_d=[[
你吸取生物正在減弱的生命力以補充自己的力量。施展此法術時，你要接觸一個剩餘1/5或更少生命值的生物。

若該生物豁免檢定失敗則死亡，同時你可獲得每3級1d8點暫時生命值和力量+2加值。

另外，你的有效施法者等級上升1，從而增強與此有關的施法能力。（這不會增加你的可用法術數量。）
]]
--[[
虛假生命（False Life）
 死靈系
等級：術士/法師 2
法術成分：言語，姿勢，材料
施法時間：一個標準動作
距離：個人
目標：你自己
持續時間：1小時/每等級或直到被耗散掉；見正文

控制反生命的力量讓你獲得能在一定限度內避開死亡的能力。當此法術起作用時，你獲得1d10+1/每施法者等級（最多+10）的暫時生命值。

材料成分：少量酒精或蒸餾烈酒，在施法的時候用它在你身體上畫出某些符號。在酒精或烈酒蒸發後，這些符號將變得不可見。

False Life
 Necromancy
Level: Sor/Wiz 2
Components: V, S, M
Casting Time: 1 standard action
Range: Personal
Target: You
Duration: 1 hour/level or until discharged; see text

You harness the power of unlife to grant yourself a limited ability to avoid death. While this spell is in effect, you gain temporary hit points equal to 1d10 +1 per caster level (maximum +10).

Material Component: A small amount of alcohol or distilled spirits, which you use to trace certain sigils on your body during casting. These sigils cannot be seen once the alcohol or spirits evaporate.

援助術（Aid）
 惑控系（脅迫）[影響心靈]
等級：牧師 2，善良 2，機運 2
法術成分：言語，姿勢，法器
施法時間：一個標準動作
距離：接觸
目標：接觸的活物
持續時間：1分鐘/每等級
豁免：無
法術抗力：可（無害）

援助術給目標的攻擊投骰和對抗恐懼效果的豁免上提供+1士氣加值，再提供了1d8+施法者等級的暫時生命值（暫時生命值在施法者等級10級時達到最大，為1d8+10）。

Aid
 Enchantment (Compulsion) [Mind-Affecting]
Level: Clr 2, Good 2, Luck 2
Components: V, S, DF
Casting Time: 1 standard action
Range: Touch
Target: Living creature touched
Duration: 1 min./level
Saving Throw: None
Spell Resistance: Yes (harmless)

Aid grants the target a +1 morale bonus on attack rolls and saves against fear effects, plus temporary hit points equal to 1d8 + caster level (to a maximum of 1d8+10 temporary hit points at caster level 10th).

死亡喪鐘（Death Knell）
 死靈系 [死亡、邪惡]
等級：牧師 2，死亡 2
法術成分：言語，姿勢
施法時間： 一個標準動作
距離：接觸
目標：接觸到的活物
持續時間：立即/每目標HD 10分鐘；見說明
豁免檢定：意志，通過則無效
法術抗力：可

你吸取生物正在減弱的生命力以補充自己的力量。施展此法術時，你要接觸一個生命值-1或更少的生物。若該生物豁免檢定失敗則死亡，同時你可獲得1d8點暫時生命值和力量+2加值。另外，你的有效施法者等級也上升1，從而增強與此有關的施法能力。（這不會增加你的可用法術數量。）這些效果可持續受術者的HDx10分鐘。

Death Knell
 Necromancy [Death, Evil]
Level: Clr 2, Death 2
Components: V, S
Casting Time: 1 standard action
Range: Touch
Target: Living creature touched
Duration: Instantaneous/10 minutes per HD of subject; see text
Saving Throw: Will negates
Spell Resistance: Yes

You draw forth the ebbing life force of a creature and use it to fuel your own power. Upon casting this spell, you touch a living creature that has -1 or fewer hit points. If the subject fails its saving throw, it dies, and you gain 1d8 temporary hit points and a +2 bonus to Strength. Additionally, your effective caster level goes up by +1, improving spell effects dependent on caster level. (This increase in effective caster level does not grant you access to more spells.) These effects last for 10 minutes per HD of the subject creature.
]]


pwr_power_word_stun_d="別名“真言術：震”。你僅發出一個威力無比的詞就能讓你選定的一個生物昏迷1d4輪。目標當前生命值須低於150或最大生命值的1/5。"
pwr_power_word_kill_d="別名“真言術：死”。你僅發出一個威力無比的詞就能立即殺死你選定的一個活物。目標當前生命值須低於100或最大生命值的1/10。"
--[[
真言術：震（Power Word Stun）
 惑控系（脅迫） [影響心靈]
等級：術士/法師 8， 戰爭 8
法術成分：言語
施法時間：1個標準動作
距離：近距（25英尺+5英尺/每2等級）
目標：一個150或更少生命值的生物
持續時間： 見正文
豁免：無
法術抗力：可

你僅發出一個威力無比的詞就能讓你選定的一個生物震懾，不管它是否能聽見那個詞。該法術的持續時間和目標的當前總生命值相關。任何當前具有151或者更多生命值的生物都不受真言術：震影響。

生命值	持續時間
50或更少	4d4輪
51–100	2d4輪
101–150	1d4輪

Power Word Stun
 Enchantment (Compulsion) [Mind-Affecting]
Level: Sor/Wiz 8, War 8
Components: V
Casting Time: 1 standard action
Range: Close (25 ft. + 5 ft./2 levels)
Target: One creature with 150 hp or less
Duration: See text
Saving Throw: None
Spell Resistance: Yes

You utter a single word of power that instantly causes one creature of your choice to become stunned, whether the creature can hear the word or not. The duration of the spell depends on the target's current hit point total. Any creature that currently has 151 or more hit points is unaffected by power word stun.

Hit Points	Duration
50 or less	4d4 rounds
51-100		2d4 rounds
101-150		1d4 rounds

真言術：死（Power Word Kill）
 惑控系（脅迫） [死亡，影響心靈]
等級：術士/法師 9， 戰爭 9
法術成分：言語
施法時間：1個標準動作
距離：近距（25英尺+5英尺/每2等級）
目標：一個100或更少生命值的活物
持續時間：立即
豁免：無
法術抗力：可

你僅發出一個威力無比的詞就能立即殺死你選定的一個生物，不管它是否能聽見那個詞。任何當前具有101或者更多生命值的生物都不受真言術：死影響。

Power Word Kill
 Enchantment (Compulsion) [Death, Mind-Affecting]
Level: Sor/Wiz 9, War 9
Components: V
Casting Time: 1 standard action
Range: Close (25 ft. + 5 ft./2 levels)
Target: One living creature with 100 hp or less
Duration: Instantaneous
Saving Throw: None
Spell Resistance: Yes

You utter a single word of power that instantly kills one creature of your choice, whether the creature can hear the word or not. Any creature that currently has 101 or more hit points is unaffected by power word kill.
]]


pwr_bulls_strength_d="受術者變得更加強壯。力量+4加值。"
pwr_cats_grace_d="受術者變得更加優雅靈活，擁有十分良好的平衡性。敏捷+4加值。"
pwr_bears_endurance_d="受術者獲得更強的生命力和耐力。體質+4加值。"
pwr_foxs_cunning_d="受術者變得更聰明。智力+4加值。"
pwr_owls_wisdom_d="受術者變得更睿智。感知+4加值。"
pwr_eagles_splendor_d="受術者變得更自信，健談、富有人格魅力。魅力+4加值。"
pwr_mass_bulls_strength_d="類似牛之力量，但針對多個目標。"
pwr_mass_cats_grace_d="類似貓之優雅，但針對多個目標。"
pwr_mass_bears_endurance_d="類似熊之堅韌，但針對多個目標。"
pwr_mass_foxs_cunning_d="類似狐之狡黠，但針對多個目標。"
pwr_mass_owls_wisdom_d="類似梟之睿智，但針對多個目標。"
pwr_mass_eagles_splendor_d="類似鷹之威儀，但針對多個目標。"

pwr_true_strike_d="你暫時獲得敏銳的洞察力，可以看出下回合攻擊的時機。你的下一次攻擊檢定獲得+20洞察加值。"
pwr_divine_favor_d="呼喚神的力量與智慧，你在攻擊檢定和武器傷害檢定上獲得每3個施法者等級+1幸運加值（至少+1，最多+3）。\n\n攻擊檢定包括武器攻擊，戰技，接觸類法術的攻擊檢定。"-- 法術傷害無加值。	The bonus doesn't apply to spell damage.
pwr_divine_power_d="呼喚你所信仰神祗的威力，為自己注入一股戰鬥力量和技能。\n\n你的基本攻擊加值等同你的角色等級（可能獲得額外攻擊次數），力量獲得+6增強加值，並獲得每施法者等級1點暫時生命值。"
--[[
神能（Divine Power）
 塑能系
等級：牧師 4，戰爭 4
法術成分：言語，姿勢, 法器
施法時間： 一個標準動作
距離：個人
目標：自己
持續時間：1 輪/等級

呼喚你所信仰神祗的威力，為自己注入一股戰鬥力量和技能。你的基本攻擊加值變為等於你的人物等級（這也許可使你進行多次攻擊），你的力量獲得+6的增強加值，並獲得每施法者等級1點暫時生命值。

Divine Power
 Evocation
Level: Clr 4, War 4
Components: V, S, DF
Casting Time: 1 standard action
Range: Personal
Target: You
Duration: 1 round/level

Calling upon the divine power of your patron, you imbue yourself with strength and skill in combat. Your base attack bonus becomes equal to your character level (which may give you additional attacks), you gain a +6 enhancement bonus to Strength, and you gain 1 temporary hit point per caster level.
]]
pwr_heroism_d="目標在戰鬥中擁有無比的勇氣與高昂的士氣。攻擊和豁免檢定+2士氣加值。"
pwr_greater_heroism_d="類似英雄氣概，但加值為+4，同時免疫恐懼，並獲得等同於施法者等級的暫時生命值。"
--[[
高等英雄氣概（Heroism, Greater）
 惑控系（脅迫） [影響心靈]
等級：吟遊詩人 5，術士/法師6
持續時間：1分鐘/每等級

此法術如同英雄氣概，但生物是在攻擊，豁免和技能上獲得+4士氣加值，同時對恐懼效果免疫，並獲得等同於施法者等級的暫時生命值（最多20點）。

Heroism, Greater
 Enchantment (Compulsion) [Mind-Affecting]
Level: Brd 5, Sor/Wiz 6
Duration: 1 min./level

This spell functions like heroism, except the creature gains a +4 morale bonus on attack rolls, saves, and skill checks, immunity to fear effects, and temporary hit points equal to your caster level (maximum 20).
]]
pwr_shield_of_faith_d="創造一個閃著微光的魔法場環繞著目標，為其擋開敵人的攻擊。目標防禦等級+2偏斜加值（額外+1/每6施法者等級；最多在18級時獲得+5偏斜加值）。"
pwr_shield_d="創造一個隱形、可移動、塔盾般大小的力場碟在你前方盤旋，使你完全無視魔法飛彈的攻擊，並且防禦等級+4盾牌加值。"
pwr_mage_armor_d="在目標周圍創造一層隱形但又確實存在的力場，使其防禦等級+4盔甲加值。"
pwr_expeditious_retreat_d="速度+6增強加值。"
pwr_protection_from_spells_d="受術者對抗法術時+8抗性加值。"
pwr_death_ward_d="受術者免疫所有死亡法術、魔法死亡效果、以及任何負能量效果。"

s_fear1d	="移除恐懼"	s_fear1d_u	="對抗恐懼效果時+4士氣加值\n消除恐懼狀態"	s_fear1d_d	=[[將勇氣注入目標心中，使其對抗恐懼效果時獲得+4士氣加值，持續10分鐘。

若受到本法術時目標已在某恐懼效果影響下，則在本法術持續時間內該效果被壓制。]]
s_fear1		="驚恐術"	s_fear1_d	=[[目標變為驚懼狀態1d4輪；意志豁免成功則僅戰慄1輪。]]
s_fear2		="恐嚇術"	s_fear2_d	=[[類似驚恐術，但影響多個目標。]]
s_fear4		="恐懼術"	s_fear4_d	=[[一個不可見的恐怖錐形將其範圍內所有活物變為恐慌狀態1d4輪；意志豁免成功則僅戰慄1輪。

被逼到絕路時，恐慌的生物會變成畏縮狀態。]]

pwr_halt_undead_d="讓不死生物無法行動。非智慧的不死生物無法作豁免檢定；智慧的不死生物則可以。當目標被攻擊或受到傷害時，定身終止。"
pwr_hold_person_d="目標被麻痺，僵在原地無法做任何動作。\n\n每一輪當其行動時，會自動進行一次豁免檢定來嘗試終止該效果。"
pwr_hold_monster_d="類似人類定身術，但可用於任何活物。"
pwr_mass_hold_person_d="類似人類定身術，但作用範圍更大。"
pwr_mass_hold_monster_d="類似怪物定身術，但作用範圍更大。"

pwr_sleep_d="睡眠術會使生物陷入魔法睡眠。睡眠中的生物處於無助狀態，受到拍擊或傷害時會甦醒，但普通的聲響不會喚醒它們。\n\n睡眠術對已昏迷的生物，構裝體或不死生物無效。"
--[[
睡眠術（Sleep）
 惑控系 （脅迫）[影響心靈]
等級：吟遊詩人 1，術士/法師 1
法術成分：言語，姿勢，材料
施法時間：1輪
距離：中距（100英尺+10英尺/每等級）
區域：半徑十英尺爆發範圍內的數個活物
持續時間： 1分鐘/等級
豁免：意志，通過則無效
法術抗力：可
睡眠術會使4HD及以下的生物陷入昏睡。低HD的生物會先受到影響。在HD相同的生物中，靠近法術源起點的生物會先受影響。剩下的HD若不足以影響其它生物則捨去不計。
 睡眠中的生物陷入無助狀態。它們會在受到拍擊或是受傷時甦醒，但普通的聲響不會喚醒它們。喚醒一個生物是標準動作（協助他人的一種應用方式）。
睡眠術對已昏迷的生物，構裝體或不死生物無效。
材料成分：一把細沙，玫瑰花瓣，或一隻活蟋蟀。

Sleep
 Enchantment (Compulsion) [Mind-Affecting]
Level: Brd 1, Sor/Wiz 1
Components: V, S, M
Casting Time: 1 round
Range: Medium (100 ft. + 10 ft./level)
Area: One or more living creatures within a 10-ft.-radius burst
Duration: 1 min./level
Saving Throw: Will negates
Spell Resistance: Yes
 A sleep spell causes a magical slumber to come upon 4 Hit Dice of creatures. Creatures with the fewest HD are affected first.
 Among creatures with equal HD, those who are closest to the spell's point of origin are affected first. Hit Dice that are not sufficient to affect a creature are wasted.
 Sleeping creatures are helpless. Slapping or wounding awakens an affected creature, but normal noise does not. Awakening a creature is a standard action (an application of the aid another action).
Sleep does not target unconscious creatures, constructs, or undead creatures.
Material Component: A pinch of fine sand, rose petals, or a live cricket.
]]
pwr_irresistible_dance_d="受術者感受到無法抑制的強烈跳舞慾望並開始搖頭晃腦打拍子。\n\n目標除了手舞足蹈外什麼都做不了，反射-10，防禦等級-4並失去所有盾牌加值，在其每輪迴合開始時還會引發藉機攻擊。"
pwr_grease_d="在指定位置製造一片油膩區域。此區域視作困難地形，且其中的所有生物每回合都需進行一次反射檢定，失敗則跌倒。\n\n具有火焰傷害的法術可引燃油膩區域。燃燒時，其中的生物會受到2d8點火焰傷害。"
--[[
油膩術（Grease）
 咒法系（創造）
等級：吟遊詩人 1, 術士/法師 1
法術成分：言語，姿勢，材料
施法時間：一個標準動作
距離：近距（25英尺+5英尺/每2等級）
目標或區域：一個物品或一個10英尺邊長正方形
持續時間：1輪/每等級（可解消）
豁免：見正文
法術抗力：不可
油膩術能在固體表面上覆蓋一層光滑的油脂。施放法書時任何在此區域的生物都必須做一個成功的反射豁免，否則就會跌倒。只要生物繼續留在該區域，那麼每輪在你的回合時它都要重複一次這種豁免。走進或穿過油脂區域的生物可以通過一次DC 10的平衡檢定來以正常速度的一半行走。失敗則意味著在該輪沒法移動（同時必須進行一次反射豁免否則就會跌倒），失敗5或更多則意味著它跌倒了（詳見平衡技能說明）。
 該法術還可以用在物品上創造出一層油脂表面。沒被使用的非魔法物品必然會被此法術影響，但是正被生物持有或使用的物品可以進行一次反射豁免來避開它。如果這個初始反射失敗了，那麼該生物將立刻掉掉該物品。嘗試揀起或使用被油膩的物品需要每輪進行一次豁免。如果穿著被油膩的盔甲或衣服，那麼生物在進行脫逃術檢定和擒抱檢定來抵抗擒抱或從擒抱中脫身時，或脫離壓制時，它都能獲得+10環境加值。
材料成分：一小塊豬皮或牛油。

Grease
 Conjuration (Creation)
Level: Brd 1, Sor/Wiz 1
Components: V, S, M
Casting Time: 1 standard action
Range: Close (25 ft. + 5 ft./2 levels)
Target or Area: One object or a 10-ft. square
Duration: 1 round/level (D)
Saving Throw: See text
Spell Resistance: No
 A grease spell covers a solid surface with a layer of slippery grease. Any creature in the area when the spell is cast must make a successful Reflex save or fall. This save is repeated on your turn each round that the creature remains within the area. A creature can walk within or through the area of grease at half normal speed with a DC 10 Balance check. Failure means it can't move that round (and must then make a Reflex save or fall), while failure by 5 or more means it falls (see the Balance skill for details).
 The spell can also be used to create a greasy coating on an item. Material objects not in use are always affected by this spell, while an object wielded or employed by a creature receives a Reflex saving throw to avoid the effect. If the initial saving throw fails, the creature immediately drops the item. A saving throw must be made in each round that the creature attempts to pick up or use the greased item. A creature wearing greased armor or clothing gains a +10 circumstance bonus on Escape Artist checks and on grapple checks made to resist or escape a grapple or to escape a pin.
Material Component: A bit of pork rind or butter.
]]
pwr_web_d="製造一大片堅韌且粘稠的絲狀物。其中的生物每回合都會受到蛛網的糾纏，反射檢定失敗則禁足1回合。\n\n具有火焰傷害的法術可引燃蛛網區域。燃燒時，其中的生物會受到2d4點火焰傷害。"
--[[
蛛網術（Web）
 咒法系（創造）
等級：術士/法師2
法術成分：言語、姿勢、材料
施法時間：1個標準動作
距離：中距（100英尺+10英尺/每等級）
效果：半徑20英尺擴散範圍內的蜘蛛網
持續時間；10分鐘/每等級
豁免：反射，通過則無效；見下文
法術杭力：可
蛛網術可造出一大片多層又堅韌又粘稠的絲狀物。這些粘絲會困住其中的生物。它們看起來像蜘蛛網，但遠比蜘蛛網更大更粗。這些粘絲必須固定在兩個或多個完全相對的固定點上，否則就會因不能完全張開而消失。在蛛網中的生物會被粘絲糾纏住。但攻擊蛛網內的生物不會讓你也被糾纏住
 法術範圍內的任何生物都必須進行反射豁免。如果豁免成功，那麼儘管依然是被糾纏狀態，但是仍然能夠移動，只是移動會因糾纏而變得比往常困難（見後）。如果豁免失敗，那麼生物被纏住並且不能移動，但可以用一輪的時間掙脫，掙脫需要通過DC20的力量檢定或是DC25的脫逃檢定。一旦掙脫(不管是因為最初的反射豁免還是後來的力量檢定或脫逃檢定)，那麼生物儘管仍然被糾纏。但可以緩慢地在蛛網內移動。如果要進行移動，那麼每輪都要做一次新的力量或脫逃檢定。若檢定結果超過10，則每超過整5點可以移動5英尺。
 你和對手之間若至少有5英尺蛛網，就會形成掩蔽。若你們之間的蛛網有20英尺以上，則形成完全掩蔽。
蛛網術產生的粘絲是易燃物。一把魔法火焰劍可以輕鬆切開它。任何火焰可以以5平方英尺每輪的速度將其點燃燒除，蛛網燃燒時，困在其中的生物會受到2d4點火焰傷害。
蛛網術的效果可以利用魔法恆定術（permanency）永久化。被損傷的（而非被摧毀的）永久化蛛網會在10分鐘後復原。
材料成分：一點蜘蛛網。

Web
 Conjuration (Creation)
Level: Sor/Wiz 2
Components: V, S, M
Casting Time: 1 standard action
Range: Medium (100 ft. + 10 ft./level)
Effect: Webs in a 20-ft.-radius spread
Duration: 10 min./level (D)
Saving Throw: Reflex negates; see text
Spell Resistance: No
Web creates a many-layered mass of strong, sticky strands. These strands trap those caught in them. The strands are similar to spider webs but far larger and tougher. These masses must be anchored to two or more solid and diametrically opposed points or else the web collapses upon itself and disappears. Creatures caught within a web become entangled among the gluey fibers. Attacking a creature in a web won't cause you to become entangled.
 Anyone in the effect's area when the spell is cast must make a Reflex save. If this save succeeds, the creature is entangled, but not prevented from moving, though moving is more difficult than normal for being entangled (see below). If the save fails, the creature is entangled and can't move from its space, but can break loose by spending 1 round and making a DC 20 Strength check or a DC 25 Escape Artist check. Once loose (either by making the initial Reflex save or a later Strength check or Escape Artist check), a creature remains entangled, but may move through the web very slowly. Each round devoted to moving allows the creature to make a new Strength check or Escape Artist check. The creature moves 5 feet for each full 5 points by which the check result exceeds 10.
 If you have at least 5 feet of web between you and an opponent, it provides cover. If you have at least 20 feet of web between you, it provides total cover.
 The strands of a web spell are flammable. A magic flaming sword can slash them away as easily as a hand brushes away cobwebs. Any fire can set the webs alight and burn away 5 square feet in 1 round. All creatures within flaming webs take 2d4 points of fire damage from the flames.
Web can be made permanent with a permanency spell. A permanent web that is damaged (but not destroyed) regrows in 10 minutes.
Material Component: A bit of spider web.
]]
pwr_sum_d="召喚一隻隨機元素生物。它會立即開始自動攻擊你的敵人，直到戰鬥結束或被摧毀。同一時刻你只能維持1只元素生物的存在。\n\n召喚者的魅力調整值會應用於召喚物的3項體能屬性。"
pwr_mk_ud_d="將範圍內死亡生物的骨骼或屍體轉化為骷髏或殭屍。它們會立即開始自動攻擊你的敵人，直到戰鬥結束或被摧毀。同一時刻你最多隻能維持2只不死生物的存在。\n\n召喚者的魅力調整值會應用於召喚物的3項體能屬性。"
pwr_dispel_d="解除指定區域內，所有由法術產生的的效果，區域和生物。如隊友的睡眠狀態，蛛網術區域和各種召喚生物等。"
pwr_resurrect_d="使一個已經死亡的生命體起死回生。非生命體，如亡靈生物，構裝生物和元素生物無法用此法術復活。"
pwr_teleport_d="將自身傳送至指定位置；或將某目標傳送至目標附近的隨機位置。"




pwr_disintegrate_d=[[
一道細細的綠色射線從你指尖射出。你必須通過遠端接觸攻擊來命中目標。被擊中的生物受到每級2d6點傷害。強韌檢定成功則只受每2級1d6點傷害。生命值被此射線降到0或更低則立即被完全分解，只留下一點微細的灰燼痕跡。被解離的生物的裝備不受影響。
]]
--[[
解離術（Disintegrate）
 變化系
等級：毀滅 7，術士/法師 6
法術成分：言語，姿勢，材料/法器
施法時間： 一個標準動作
距離：中距 （100英尺+10英尺/等級）
效果：射線
持續時間：立即
豁免檢定：強韌，通過則效果減半（物體）
法術抗力：可
一道細細的綠色射線從你指尖射出。你必須通過遠端接觸攻擊來命中目標。被擊中的生物受到每施法者等級2d6點傷害（最多40d6）。生命值被此射線降到0或更低則立即被完全分解，只留下一點微細的灰燼痕跡。被解離的生物的裝備不受影響。
目標為物品時，射線可解離10立方英尺的非生命物品。因此，此法術只能解離龐大物體或結構的一部分。此法術甚至對完全由力場構成的物體也有效，如飛擊掌（forceful hand）或力場牆（wall of force），但對法術無效結界（globe of invulnerability）或反魔場（antimagic field）之類的法術效果無效。
 通過強韌檢定的生物或物體只受到5d6點傷害。若它們的生命值因此降到0或更低則立即被完全分解。
 只有第一個被擊中的生物或物品會被影響，這就是說，每次施法，射線只對一個目標有效。
奧術材料成分 ：一塊天然磁石和一小撮灰塵。

Disintegrate
 Transmutation
Level: Destruction 7, Sor/Wiz 6
Components: V, S, M/DF
Casting Time: 1 standard action
Range: Medium (100 ft. + 10 ft./level)
Effect: Ray
Duration: Instantaneous
Saving Throw: Fortitude partial (object)
Spell Resistance: Yes
A thin, green ray springs from your pointing finger. You must make a successful ranged touch attack to hit. Any creature struck by the ray takes 2d6 points of damage per caster level (to a maximum of 40d6). Any creature reduced to 0 or fewer hit points by this spell is entirely disintegrated, leaving behind only a trace of fine dust. A disintegrated creature's equipment is unaffected.
When used against an object, the ray simply disintegrates as much as one 10- foot cube of nonliving matter. Thus, the spell disintegrates only part of any very large object or structure targeted. The ray affects even objects constructed entirely of force, such as forceful hand or a wall of force, but not magical effects such as a globe of invulnerability or an antimagic field.
A creature or object that makes a successful Fortitude save is partially affected, taking only 5d6 points of damage. If this damage reduces the creature or object to 0 or fewer hit points, it is entirely disintegrated.
Only the first creature or object struck can be affected; that is, the ray affects only one target per casting.
Arcane Material Component: A lodestone and a pinch of dust.
]]

pwr_mislead_d=[[
]]
--[[
假象術（Mislead）
 幻術系（虛假幻覺，五官幻覺）
等級：吟遊詩人5，機運6，術士/法師6，詭術6
法術成分：姿勢
施法時間：1個標準動作
距離：近距（25英尺+5英尺/每2等級）
 目標/效果：自己/一個幻象分身
持續時間：1輪/施法者每等級（可解消）和專注+3輪；見說明
豁免：無；或意志，通過則不相信（若發生互動）；見說明
法術抗力：無
 你變為隱形（同高等隱形術（Greater Invisibility），為五官幻覺），同時出現一個跟你一樣的幻影（同強效幻影（major image），為虛假幻覺）。之後你和你的分身可以分開移動。分身會出現在法術有效範圍內，並往你指定的方向移動（需要在施法後的第一輪開始保持專注。你也可以使幻象分身在出現時完美地疊合在你的身體上，使敵人無法察覺分身出現而你已經隱形，然後你和分身接下來可以往不同方向移動。分身的移動速度和你一樣，它的說話方式和動作非常自然，跟真的一樣。分身不能攻擊或施法，但它可以做出類似的假動作。
 幻象分身的持續時間是專注+3輪。當你結束專注後，幻象分身將繼續進行與之前相同的動作直到其持續時間結束。高階隱形術效果的持續時間則是每等級1輪，而不會受到專注的影響。

Mislead
 Illusion (Figment, Glamer)
Level: Brd 5, Luck 6, Sor/Wiz 6, Trickery 6
Components: S
Casting Time: 1 standard action
Range: Close (25 ft. + 5 ft./2 levels)
Target/Effect: You/one illusory double
Duration: 1 round/level (D) and concentration + 3 rounds; see text
Saving Throw: None or Will disbelief (if interacted with); see text
Spell Resistance: No
 You become invisible (as improved invisibility, a glamer), and at the same time, an illusory double of you (as major image, a figment) appears. You are then free to go elsewhere while your double moves away. The double appears within range but thereafter moves as you direct it (which requires concentration beginning on the first round after the casting). You can make the figment appear superimposed perfectly over your own body so that observers don't notice an image appearing and you turning invisible. You and the figment can then move in different directions. The double moves at your speed and can talk and gesture as if it were real, but it cannot attack or cast spells, though it can pretend to do so.
 The illusory double lasts as long as you concentrate upon it, plus 3 additional rounds. After you cease concentration, the illusory double continues to carry out the same activity until the duration expires. The improved invisibility lasts for 1 round per level, regardless of concentration.
]]

pwr_eyebite_d=[[
你能以一個移動動作瞄準目標，然後用邪惡力量波攻擊它。
]]
--[[
攝心目光（Eyebite）
死靈系 [邪惡]
等級：吟遊詩人 6, 術士/法師 6
法術成分：言語，姿勢
施法時間： 一個標準動作
距離：近距（25英尺+5英尺/2等級）
目標：一個活物
持續時間：每三等級一輪；見說明
豁免檢定：強韌，通過則無效
法術抗力：可
每一輪，你都可以選擇一個目標，用邪惡力量波攻擊它。根據受術者的HD，此法術產生以下三種效果。
HD	效果
10或更多	噁心
5–9	恐慌，噁心
4 或更低	沉睡，恐慌，噁心
效果可累加，並同時發生。
噁心（Sickened）：目標遭到突如起來的痛苦及熱病。噁心狀態的生物在攻擊，傷害，豁免，技能及屬性檢定上承受-2的減值。此效果持續10分鐘/施法者等級。移除疾病（remove disease）和醫療術（heal）無法去除此效果，但移除詛咒（remove curse）可以。
恐慌（Panicked）：目標陷入恐慌狀態1d4輪。即便恐慌結束，目標依然會處於戰慄（shaken）狀態，持續時間為每施法者等級10分鐘，如果在此期間它又進入你的視線範圍，它會重新陷入恐慌。這屬於恐懼效果。
沉睡（Comatose）：目標陷入僵硬的病態沉眠，持續10分鐘/施法者等級。在此期間，生物無法以任何不足以解除此魔法的方式叫醒。這並非是睡眠效果，因此精靈不能免疫它。
此法術可持續每3施法者等級1輪，第一輪後每輪你必須以一個移動動作來瞄準目標。

Eyebite
Necromancy [Evil]
Level: Brd 6, Sor/Wiz 6
Components: V, S
Casting Time: 1 standard action
Range: Close (25 ft. + 5 ft./2 levels)
Target: One living creature
Duration: 1 round per three levels; see text
Saving Throw: Fortitude negates
Spell Resistance: Yes
Each round, you may target a single living creature, striking it with waves of evil power. Depending on the target's HD, this attack has as many as three effects.
HD	Effect
10 or more	Sickened
5-9	Panicked, sickened
4 or less	Comatose, panicked, sickened
The effects are cumulative and concurrent.
Sickened: Sudden pain and fever sweeps over the subject's body. A sickened creature takes a -2 penalty on attack rolls, weapon damage rolls, saving throws, skill checks, and ability checks. A creature affected by this spell remains sickened for 10 minutes per caster level. The effects cannot be negated by a remove disease or heal spell, but a remove curse is effective.
Panicked: The subject becomes panicked for 1d4 rounds. Even after the panic ends, the creature remains shaken for 10 minutes per caster level, and it automatically becomes panicked again if it comes within sight of you during that time. This is a fear effect.
Comatose: The subject falls into a catatonic coma for 10 minutes per caster level. During this time, it cannot be awakened by any means short of dispelling the effect. This is not a sleep effect, and thus elves are not immune to it.
The spell lasts for 1 round per three caster levels. You must spend a move action each round after the first to target a foe.
]]

pwr_flesh_to_stone_d=[[
受術者及其所有攜帶的裝備都被轉變為沒有心智，完全靜止的雕像。

如果這座被法術製造的雕像被打壞或受損，受術者（如果它轉化回之前的狀態）也會受到類似的傷害或缺損。

只有有肉的生物才會被此法術影響。
]]
--[[
石化術（Flesh to Stone）
 變化系
等級：術士/法師 6
法術成分：言語，姿勢，材料
施法時間：一個標準動作
距離：中距（100英尺+10英尺/每等級）
目標：一個生物
持續時間：立即
豁免：強韌，通過則無效
法術抗力：可

受術者及其所有攜帶的裝備都被轉變為沒有心智，完全靜止的雕像。如果這座被法術製造的雕像被打壞或受損，受術者（如果它轉化回之前的狀態）也會受到類似的傷害或缺損。當用觀命術（deathwatch）這類法術察看時，該生物並不算死，但是也不算活。

只有有肉的生物才會被此法術影響。

材料成分：石灰，水，泥土。

Flesh to Stone
 Transmutation
Level: Sor/Wiz 6
Components: V, S, M
Casting Time: 1 standard action
Range: Medium (100 ft. + 10 ft./level)
Target: One creature
Duration: Instantaneous
Saving Throw: Fortitude negates
Spell Resistance: Yes

The subject, along with all its carried gear, turns into a mindless, inert statue. If the statue resulting from this spell is broken or damaged, the subject (if ever returned to its original state) has similar damage or deformities. The creature is not dead, but it does not seem to be alive either when viewed with spells such as deathwatch.

Only creatures made of flesh are affected by this spell.

Material Component: Lime, water, and earth.
]]

pwr_stone_to_flesh_d=[[
此法術可使一個被石化的生物恢復原狀，但其必須通過一個DC15的強韌豁免才能在此過程中存活。
]]
--[[
解除石化（Stone to Flesh）
 變化系
等級：術士/法師 6
法術成分：言語，姿勢，材料
施法時間：一個標準動作
距離：中距（100英尺+10英尺/每等級）
目標：1個遭石化的生物，或者一個直徑1至3英尺，最高10英尺的石柱
持續時間：立即
豁免：強韌，通過則無效（物體）；見正文
法術抗力：可

此法術可使一個遭石化的生物恢復原狀，包括生命和它攜帶的物品。生物必須通過DC 15的強韌豁免才能在此過程中存活。任何體型的石化生物都可以被複原。

此法術也能將石頭轉化成肉體。這樣的肉體並沒有生命，除非被賦予生命或魔法能量。（比如，石魔像可由此變為肉魔像，但一般的石像只能變成屍體。）你可以影響的目標必須可以放在一個直徑1至3英尺，高10英尺的柱形區域內，也可以對更大的的石塊中符合上述限制的部分施法。

材料成分：一撮泥土和一滴血。

Stone to Flesh
 Transmutation
Level: Sor/Wiz 6
Components: V, S, M
Casting Time: 1 standard action
Range: Medium (100 ft. + 10 ft./level)
Target: One petrified creature or a cylinder of stone from 1 ft. to 3 ft. in diameter and up to 10 ft. long
Duration: Instantaneous
Saving Throw: Fortitude negates (object); see text
Spell Resistance: Yes

This spell restores a petrified creature to its normal state, restoring life and goods. The creature must make a DC 15 Fortitude save to survive the process. Any petrified creature, regardless of size, can be restored.

The spell also can convert a mass of stone into a fleshy substance. Such flesh is inert and lacking a vital life force unless a life force or magical energy is available. (For example, this spell would turn a stone golem into a flesh golem, but an ordinary statue would become a corpse.) You can affect an object that fits within a cylinder from 1 foot to 3 feet in diameter and up to 10 feet long or a cylinder of up to those dimensions in a larger mass of stone.

Material Component: A pinch of earth and a drop of blood.
]]

pwr_transformation_d=[[
你變成一個純粹的戰鬥機器 —— 更強，更狠，更快，更精於戰鬥。你的思維完全轉換為戰鬥型，享受戰鬥但無法施法。

你獲得：
- 你的基本攻擊加值等同你的角色等級（可能獲得額外攻擊次數）。
- 力量，敏捷，體質+4增強加值。
- 防禦等級+4天生防禦加值。
- 強韌+5能力加值。
- 擅長所有簡易和軍用武器。

但你失去施法能力。
]]
--[[
轉變術（Transformation）
 變化系
等級：術士/法師6
法術成分：言語，姿勢，材料
施法時間：1個標準動作
距離：個人
目標：自己
持續時間：1輪/等級

你變成一個純粹的戰鬥機器——更強，更狠，更快，更精於戰鬥。你的思維完全轉型成為戰鬥型別，所以你無法施法，甚至不能使用魔法物品。

你的力量，敏捷，體質獲得+4的增強加值，AC獲得+4的天生防禦加值，強韌檢定獲得+5能力加值，並且擅長所有簡易和軍用武器。你的基本攻擊加值為你的人物等級（這也許會使你可以進行多次攻擊）。

你將失去施法能力，包括需要利用法術啟動或完成的魔法物品，就好像你的職業能力裡不再有那些法術。

材料成分：一瓶牛之力量藥水，你必須喝掉它（它的效果包含在上文所述的法術效果中）。

Transformation
 Transmutation
Level: Sor/Wiz 6
Components: V, S, M
Casting Time: 1 standard action
Range: Personal
Target: You
Duration: 1 round/level

You become a virtual fighting machine - stronger, tougher, faster, and more skilled in combat. Your mind-set changes so that you relish combat and you can't cast spells, even from magic items.

You gain a +4 enhancement bonus to Strength, Dexterity, and Constitution, a +4 natural armor bonus to AC, a +5 competence bonus on Fortitude saves, and proficiency with all simple and martial weapons. Your base attack bonus equals your character level (which may give you multiple attacks).

You lose your spellcasting ability, including your ability to use spell activation or spell completion magic items, just as if the spells were no longer on your class list.

Material Component: A potion of bull's strength, which you drink (and whose effects are subsumed by the spell effects).
]]

pwr_iron_body_d=[[
此法術使你變成有生命的鋼鐵，從而具有多種強大的抵抗與防禦能力。

你獲得：
- 每級1/精金的傷害減免。
- 免疫重擊、電、毒、屬性傷害、震懾、目盲、耳聾、疾病，以及所有影響生理機能和呼吸方面的效果。
- 所受強酸和火焰傷害減半。
- 力量+6增強加值，敏捷-6減值（最低1）。
- 徒手攻擊視為武裝攻擊，傷害為1d6（小體型1d4）。

同時遭受下列效果：
- 速度減半。
- 50%奧術失敗率，-8防具檢定減值。
- 影響鐵魔像的特殊攻擊也影響你。
- 不能飲用藥劑。
]]
--[[
鋼筋鐵骨（Iron Body）
變化系
等級：土 8，術士/法師 8
法術成分：言語，姿勢，材料/法器
施法時間：1個標準動作
距離：個人
目標：自身
持續時間：1分鐘/每等級（可解消）

此法術使你變成有生命的鋼鐵，從而具有多種強大的抵抗與防禦能力。

你獲得15/精金的傷害減免。你對目盲、重擊、屬性傷害、耳聾、疾病、溺水、電、毒、震懾免疫，同時免疫所有影響生理機能及呼吸方面的法術，因為在法術影響期間你已完全沒有生理反應和呼吸。你對任意種類的酸和火只受一半傷害。但所有那些能影響鐵魔像的特殊攻擊也能對你造成傷害。

你在力量上獲得+6增強加值，但在敏捷上承受-6減值（最低到1），並且速度減半。你的奧術失敗率達到50%並有-8的防具檢定減值，就如同身穿全身甲。你不能飲水（因此不能使用藥劑）或演奏吹奏樂器。

你的徒手攻擊看作武裝攻擊，傷害如同和你體型對應的木棒（小體形1d4，中體形1d6）。

你的體重增加10倍，這使你在水中如石頭般下沉。但你能承受水底的高壓和無空氣狀態——至少在法術持續時間內。

奧術材料：一小塊鐵塊，必須曾是鐵魔像、英雄盔甲或是戰爭機器的一部分。


Iron Body
Transmutation
Level: Earth 8, Sor/Wiz 8
Components: V, S, M/DF
Casting Time: 1 standard action
Range: Personal
Target: You
Duration: 1 min./level (D)

This spell transforms your body into living iron, which grants you several powerful resistances and abilities.

You gain damage reduction 15/adamantine. You are immune to blindness, critical hits, ability score damage, deafness, disease, drowning, electricity, poison, stunning, and all spells or attacks that affect your physiology or respiration, because you have no physiology or respiration while this spell is in effect. You take only half damage from acid and fire of all kinds. However, you also become vulnerable to all special attacks that affect iron golems.

You gain a +6 enhancement bonus to your Strength score, but you take a -6 penalty to Dexterity as well (to a minimum Dexterity score of 1), and your speed is reduced to half normal. You have an arcane spell failure chance of 50% and a -8 armor check penalty, just as if you were clad in full plate armor. You cannot drink (and thus can't use potions) or play wind instruments.

Your unarmed attacks deal damage equal to a club sized for you (1d4 for Small characters or 1d6 for Medium characters), and you are considered armed when making unarmed attacks.

Your weight increases by a factor of ten, causing you to sink in water like a stone. However, you could survive the crushing pressure and lack of air at the bottom of the ocean - at least until the spell duration expires.

Arcane Material Component: A small piece of iron that was once part of either an iron golem, a hero's armor, or a war machine.
]]

pwr_spell_turning_d=[[
以你為目標的法術或類法術能力會彈回施法者身上。對遠端接觸類法術無效。

可反轉總法術等級為7~10，具體數值未知。若剩餘數值比目標法術等級低，則按比例反轉。

若你和施法攻擊者都受此效果的保護，則會產生共鳴場，結果投百分骰決定：
01–70	法術衰竭失效。
71–80	法術對雙方均造成全效。
81–97	雙方的法術反轉均無效1d4分鐘。
98–100	雙方被拋入另一位面的裂縫中。
]]
--[[
法術反轉（Spell Turning）
防護系
等級：機運 7，魔法 7，術士/法師 7
法術成分：言語，姿勢，材料/法器
施法時間：一個標準動作
距離：個人
目標：自己
持續時間：直到耗盡或10分鐘/等級
以你為目標的法術或類法術能力會彈回施法者身上。反轉效果僅對以你為目標的法術有效。效果型和區域法術不受影響，對遠端接觸類法術亦無效。
可反轉的法術等級為7到10（1d4+6）。具體數值由暗投決定。
若剩餘反轉等級比受到的目標法術的等級低，則該法術只能部分反轉。
此時，以該法術等級與剩餘反轉等級的差為分子，以該法術等級為分母，所得的結果即為該法術生效與被反轉的比率。若為傷害性法術，則按此比率受到傷害；若為非傷害性法術，你們受到影響的機率也依此計算。
若你和施法攻擊者都受法術反轉的保護，則會產生共鳴場，結果要投百分骰決定。
d%	效果
01–70	法術衰竭，無任何效果
71–80	法術完全生效，且對雙方造成同樣效果
81–97	法術的反轉均無效1d4分鐘
98–100	雙方被拋入另一位面的裂縫中
奧術材料成分：一面小銀鏡。

Spells and spell-like effects targeted on you are turned back upon the original caster. This effect is ineffective for touch range spells.\n\n7~10 spell levels are affected by the turning. The exact amount is unknown.\n\nWhen you are targeted by a spell of higher level than the amount of spell turning you have left, that spell is proportionally turned.\n\nIf you and a spellcasting attacker are both warded by spell turning effects in operation, a resonating field is created. Roll randomly to determine the result.\n01-70	Spell drains away without effect.\n71-80	Spell affects both of you equally at full effect.\n81-97	Both turning effects are rendered nonfunctional for 1d4 minutes.\n98-100	Both of you go through a rift into another plane.

Spell Turning
Abjuration
Level: Luck 7, Magic 7, Sor/Wiz 7
Components: V, S, M/DF
Casting Time: 1 standard action
Range: Personal
Target: You
Duration: Until expended or 10 min./level
Spells and spell-like effects targeted on you are turned back upon the original caster. The abjuration turns only spells that have you as a target. Effect and area spells are not affected. Spell turning also fails to stop touch range spells. 
From seven to ten (1d4+6) spell levels are affected by the turning. The exact number is rolled secretly.
When you are targeted by a spell of higher level than the amount of spell turning you have left, that spell is partially turned. The subtract the amount of spell turning left from the spell level of the incoming spell, then divide the result by the spell level of the incoming spell to see what fraction of the effect gets through. For damaging spells, you and the caster each take a fraction of the damage. For nondamaging spells, each of you has a proportional chance to be affected.
If you and a spellcasting attacker are both warded by spell turning effects in operation, a resonating field is created.
Roll randomly to determine the result.
d%	Effect
01-70	Spell drains away without effect.
71-80	Spell affects both of you equally at full effect.
81-97	Both turning effects are rendered nonfunctional for 1d4 minutes.
98-100	Both of you go through a rift into another plane.
Arcane Material Component: A small silver mirror.
]]

pwr_insanity_d=[[
]]
--[[
精神錯亂（Insanity）
 惑控系（脅迫） [影響心靈]
等級：術士/法師7
法術成分：言語，姿勢
施法時間：1個標準動作
距離：中距（100英尺+10英尺/每等級）
目標：1個活物
持續時間：立即
豁免：意志，通過無效
法術抗力：可
 該生物遭受持續性的困惑術（confusion）效果，效果等同於原法術。
移除詛咒（Remove curse）不能移除精神錯亂，而高等復原術（Greater restoration），醫療術（heal），有限祈願術（limited wish），神蹟術（miracle）或是祈願術（wish）可以。

Insanity
 Enchantment (Compulsion) [Mind-Affecting]
Level: Sor/Wiz 7
Components: V, S
Casting Time: 1 standard action
Range: Medium (100 ft. + 10 ft./level)
Target: One living creature
Duration: Instantaneous
Saving Throw: Will negates
Spell Resistance: Yes
 The affected creature suffers from a continuous confusion effect, as the spell.
Remove curse does not remove insanity. Greater restoration, heal, limited wish, miracle, or wish can restore the creature.
]]

pwr_mages_sword_d=[[
]]
--[[
法師之劍（Mage’s Sword）
 塑能系[力場]
等級：術士/法師7
法術成分：言語，姿勢，器材
施法時間：1個標準動作
距離：近距（25英尺+5英尺/每2等級）
效果：一把劍
持續時間：1輪/施法者每等級（可解消）
豁免：無
法術抗力：不可
 你造出一個閃閃發光的劍形力場。從你施展此法術的那一回合開始，此劍就會攻擊任何它範圍內你指定它攻擊的目標。此劍每輪在你的回合內對指定的目標進行一次攻擊。此劍的攻擊加值等於你的施法者等級加上你的智力調整值（法師）或魅力調整值（術士）再加上+3的增強加值。因為是由力場構成，此劍可以擊中靈體和虛體生物。它的傷害值為4D6+3點力場傷害，重擊威脅範圍是19-20，重擊倍數×2。
 此劍只能從你的方向攻擊，它不能得到夾擊加值，也不能幫助隊友夾擊。如果此劍離開法術有效距離、離開你的視野，或你未對它下命令，它便會回到你身邊盤旋待命。
 第一輪之後，每輪你可以以一個標準動作命令此劍攻擊一個新的目標，如果你不下命令，此劍將繼續攻擊上一輪的目標。
 此劍不能被物理攻擊所攻擊或傷害，但是解除魔法（dispel magic），解離術（disintegrate），毀滅黑洞（sphere of annihilation）或者抹消權杖（rod of cancellation）可以影響它。此劍的AC為13（10+中體型0體型調整值+3偏斜加值）。
 如果被攻擊的生物具有法術抗力，則第一次被法師之劍攻擊時，施法者要進行一次檢定以穿透目標的法術抗力，如果該檢定未通過的話，則此法術被解除。如果施法者成功穿透目標的法術抗力，則在法術持續時間內此劍都不再受此生物的法術抗力的影響。
 器材：一把微縮的白金模型劍，它的握柄與柄端由銅和鋅打造。打造這個模型劍需要250金幣。

Mage's Sword
 Evocation [Force]
Level: Sor/Wiz 7
Components: V, S, F
Casting Time: 1 standard action
Range: Close (25 ft. + 5 ft./2 levels)
Effect: One sword
Duration: 1 round/level (D)
Saving Throw: None
Spell Resistance: Yes
 This spell brings into being a shimmering, swordlike plane of force. The sword strikes at any opponent within its range, as you desire, starting in the round that you cast the spell. The sword attacks its designated target once each round on your turn. Its attack bonus is equal to your caster level + your Int bonus or your Cha bonus (for wizards or sorcerers, respectively) with an additional +3 enhancement bonus. As a force effect, it can strike ethereal and incorporeal creatures. It deals 4d6+3 points of force damage, with a threat range of 19-20 and a critical multiplier of x2.
 The sword always strikes from your direction. It does not get a bonus for flanking or help a combatant get one. If the sword goes beyond the spell range from you, if it goes out of your sight, or if you are not directing it, the sword returns to you and hovers.
 Each round after the first, you can use a standard action to switch the sword to a new target. If you do not, the sword continues to attack the previous round's target.
 The sword cannot be attacked or harmed by physical attacks, but dispel magic, disintegrate, a sphere of annihilation, or a rod of cancellation affects it. The sword's AC is 13 (10, +0 size bonus for Medium object, +3 deflection bonus).
 If an attacked creature has spell resistance, the resistance is checked the first time Mage's sword strikes it. If the sword is successfully resisted, the spell is dispelled. If not, the sword has its normal full effect on that creature for the duration of the spell.
Focus: A miniature platinum sword with a grip and pommel of copper and zinc. It costs 250 gp to construct.
]]

pwr_prismatic_spray_d=[[
]]
--[[
虹光噴射（Prismatic Spray）
塑能系
等級：術士/法師 7
法術成分：言語，姿勢
施法時間：1個標準動作
距離：60英尺
區域：錐形爆發區域
持續時間：立即
豁免：見正文
法術抗力：可
這個法術能讓你手中噴出七道閃爍不定，互相混雜的多彩光束。每道光束具有不同的威力。法術區域內8或更少HD的生物會自動目盲2d4輪。區域內的每個生物都會隨機的被一道或多道光束擊中，每道光束都有不同的額外效果。
1d8	光束顏色	效果
1	紅色	20點火焰傷害（反射減半）
2	橙色	40點強酸傷害（反射減半）
3	黃色	80點電擊傷害（反射減半）
4	綠色	毒（被殺；強韌通過則部分有效，只受到1d6點體質傷害）
5	藍色	變成石頭（強韌通過則無效）
6	青色	瘋狂，如同精神錯亂（insanity）法術（意志通過則無效）
7	紫色	傳送到其他位面（意志通過則無效）
8	被兩道光線擊中；重新投擲兩次，忽視任何為8的結果。

Prismatic Spray
Evocation
Level: Sor/Wiz 7
Components: V, S
Casting Time: 1 standard action
Range: 60 ft.
Area: Cone-shaped burst
Duration: Instantaneous
Saving Throw: See text
Spell Resistance: Yes
This spell causes seven shimmering, intertwined, multicolored beams of light to spray from your hand. Each beam has a different power. Creatures in the area of the spell with 8 HD or less are automatically blinded for 2d4 rounds. Every creature in the area is randomly struck by one or more beams, which have additional effects.
1d8	Color of Beam	Effect
1	Red	20 points fire damage (Reflex half)
2	Orange	40 points acid damage (Reflex half)
3	Yellow	80 points electricity damage (Reflex half)
4	Green	Poison (Kills; Fortitude partial, take 1d6 points of Con damage instead)
5	Blue	Turned to stone (Fortitude negates)
6	Indigo	Insane, as insanity spell (Will negates)
7	Violet	Sent to another plane (Will negates)
8	Struck by two rays; roll twice more, ignoring any "8" results.
]]

pwr_control_undead_d=[[
]]
--[[
操控死靈（Control Undead）
死靈系
等級：術士/法師7
法術成分：言語，姿勢，材料
施法時間：一個標準動作
距離：近距（25英尺+5英尺/每2等級）
目標：最多2HD/每等級的不死生物，任意兩個的間距不超過30英尺
持續時間：1分鐘/每等級
豁免檢定：意志，通過則無效
法術抗力：可
 這個法術讓你在短時間內控制一個或者更多的不死生物。你用聲音命令它們，它們也能聽懂你，不管你說什麼語言。你可以下達一些非常過分、無法忍受的要求，也不必擔心它們會攻擊你。法術結束後，受控制的不死生物將恢復正常的形態。
 智慧不死生物將記得你控制過它們。
材料成分：一小塊骨頭和一小塊生肉。

Control Undead
 Necromancy
Level: Sor/Wiz 7
Components: V, S, M
Casting Time: 1 standard action
Range: Close (25 ft. + 5 ft./2 levels)
Targets: Up to 2 HD/level of undead creatures, no two of which can be more than 30 ft. apart
Duration: 1 min./level
Saving Throw: Will negates
Spell Resistance: Yes
 This spell enables you to command undead creatures for a short period of time. You command them by voice and they understand you, no matter what language you speak. Even if vocal communication is impossible the controlled undead do not attack you. At the end of the spell, the subjects revert to their normal behavior.
 Intelligent undead creatures remember that you controlled them.
Material Component: A small piece of bone and a small piece of raw meat.
]]

pwr_waves_of_exhaustion_d=[[
負能量波使得法術範圍內的所有活物力竭。此法術對已力竭的生物無效。
]]
--[[
力竭波（Waves of Exhaustion）
死靈系
等級：術士/法師7
法術成分：言語，姿勢
施法時間：1個標準動作
距離：60英尺
區域：錐形爆發範圍
持續時間：立即
豁免：無
法術抗力：可
負能量波會使得法術範圍內的所有活物力竭（exhausted）。本法術對已經陷入力竭的生物無效。

Waves of Exhaustion
 Necromancy
Level: Sor/Wiz 7
Components: V, S
Casting Time: 1 standard action
Range: 60 ft.
Area: Cone-shaped burst
Duration: Instantaneous
Saving Throw: No
Spell Resistance: Yes
Waves of negative energy cause all living creatures in the spell's area to become exhausted. This spell has no effect on a creature that is already exhausted.
]]

pwr_ethereal_jaunt_d=[[
你進入以太位面，化成靈體。

此效果持續期間，你身處以太位面，一個與正常主物質位面重疊共存的世界。效果結束時，你將返回主物質位面，變回實體。

對於主物質位面而言，靈體不可見也摸不到。而它可看見和聽見主物質位面，但一切看上去都是灰色的模糊的。它在主物質位面的視覺與聽覺範圍為60英尺。

一般而言，靈體生物和實體生物無法攻擊對方。而靈體生物或物品之間則如同均為實體。

另外，作為沒有實體的生物，靈體可以穿越主物質位面的固體，包括活物。若效果結束時它仍在固體中（如牆體），則會被擠到最近的空地，每經過5英尺遭受1d6點傷害。
]]
--[[
幻化靈體（Ethereal Jaunt）
 變化系
等級：牧師 7，術士/法師 7
法術成分：言語，姿勢
施法時間： 一個標準動作
距離：個人
目標：自己
持續時間：1 輪/等級（可解消）
 你和你的裝備一起變成靈體。在法術持續時間內，你將身處靈界位面，這是一個與正常物質位面重疊的世界。一旦法術結束，你將變回實體。
 靈體生物是不可見也摸不到的，同時可以向任意方向移動，包括上下，但速度減半。作為沒有實體的生物，你可以穿越固體，包括活物。靈體生物可看見和聽見主物質位面，但一切看上去都是灰色的模糊的，在主物質位面的視覺與聽覺範圍為60英尺。
 力場效果和防護系法術對靈體有正常效果。這些效果可由物質位面延伸至以太位面，但反過來不是如此。靈體不能攻擊實體生物，施展的法術也只能影響其他靈體。某些實體生物的攻擊或效果卻可影響靈體。
 靈體生物或物品彼此視為正常物體。
 若法術解除時，你在固體物中（如固體牆），則會從最近的開口處擠出，每經過5英尺受到1d6點傷害。


對於主物質位面而言，靈體生物不可見也摸不到。而靈體生物可看見和聽見主物質位面，但一切看上去都是灰色的模糊的。靈體生物在主物質位面的視覺與聽覺範圍為60英尺。

一般而言，靈體生物和實體生物無法攻擊對方。而靈體生物或物品之間則如同均為實體。

另外，作為沒有實體的生物，你可以穿越主物質位面的固體，包括活物。若法術解除時，你在固體物中（如固體牆），則會從最近的開口處擠出，每經過5英尺受到1d6點傷害。

力場效果和防護系法術對靈體有正常效果。這些效果可由物質位面延伸至以太位面，但反過來不是如此。

以太位面與主物質位面（經常還有其他位面）共存。從以太位面可以看到主物質位面，但它的影像看起來微弱而不清晰，顏色互相混雜，而物體的邊界也會模糊失真。

雖然從以太位面可以看到主物質位面的情形，但對於主物質位面而言，以太位面通常是不可見的。一般來說，以太位面的生物無法攻擊主物質位面的生物，反之亦然。對於主物質位面者而言，以太位面的旅行者是不可見的，無實體的，絕對靜默的。

An ethereal creature is invisible and insubstantial. However, an ethereal creature can see and hear on the Material Plane, but everything looks gray and ephemeral. Sight and hearing onto the Material Plane are limited to 60 feet.

Normally, ethereal creatures and material creatures can't attack each other. Treat other ethereal creatures and ethereal objects as if they were material.

As an insubstantial creature, you can move through solid objects, including living creatures. If you end the spell and become material while inside a material object (such as a solid wall), you are shunted off to the nearest open space and take 1d6 points of damage per 5 feet that you so travel.

Force effects and abjurations affect an ethereal creature normally. Their effects extend onto the Ethereal Plane from the Material Plane, but not vice versa.

THE ETHEREAL PLANE
The Ethereal Plane is coexistent with the Material Plane and often other planes as well. The Material Plane itself is visible from the Ethereal Plane, but it appears muted and indistinct, its colors blurring into each other and its edges turning fuzzy.

While it is possible to see into the Material Plane from the Ethereal Plane, the Ethereal Plane is usually invisible to those on the Material Plane. Normally, creatures on the Ethereal Plane cannot attack creatures on the Material Plane, and vice versa. A traveler on the Ethereal Plane is invisible, incorporeal, and utterly silent to someone on the Material Plane.


Ethereal Jaunt
 Transmutation
Level: Clr 7, Sor/Wiz 7
Components: V, S
Casting Time: 1 standard action
Range: Personal
Target: You
Duration: 1 round/level (D)
 You become ethereal, along with your equipment. For the duration of the spell, you are in a place called the Ethereal Plane, which overlaps the normal, physical, Material Plane. When the spell expires, you return to material existence.
 An ethereal creature is invisible, insubstantial, and capable of moving in any direction, even up or down, albeit at half normal speed. As an insubstantial creature, you can move through solid objects, including living creatures. An ethereal creature can see and hear on the Material Plane, but everything looks gray and ephemeral. Sight and hearing onto the Material Plane are limited to 60 feet.
 Force effects and abjurations affect an ethereal creature normally. Their effects extend onto the Ethereal Plane from the Material Plane, but not vice versa. An ethereal creature can't attack material creatures, and spells you cast while ethereal affect only other ethereal things. Certain material creatures or objects have attacks or effects that work on the Ethereal Plane.
 Treat other ethereal creatures and ethereal objects as if they were material. 
 If you end the spell and become material while inside a material object (such as a solid wall), you are shunted off to the nearest open space and take 1d6 points of damage per 5 feet that you so travel.
]]

pwr_etherealness_d=[[
類似幻化靈體，不過你可與其他自願生物手牽手，連同他們的裝備一起變成靈體。不算自己，施法者每3施法者等級可多帶一個生物進入以太位面。一旦成為靈體，就無需再保持接觸。
]]
--[[
 同遊靈界（Etherealness）
 變化系
等級：牧師 9，術士/法師 9
距離：接觸；見說明
目標：自己，以及每三級可多帶一個被接觸的生物
持續時間：1 分鐘/等級（可解消）
法術抗力：可
和幻化靈體一樣，不過你可與其他自願生物手牽手，連同他們的裝備一起變成靈體。不算自己，施法者每3施法者等級可多帶一個生物進入以太位面。一旦成為靈體，就無需再保持接觸。
一旦持續時間終止，所有生物都會變回實體。

Etherealness
 Transmutation
Level: Clr 9, Sor/Wiz 9
Range: Touch; see text
Targets: You and one other touched creature per three levels
Duration: 1 min./level (D)
Spell Resistance: Yes
This spell functions like ethereal jaunt, except that you and other willing creatures joined by linked hands (along with their equipment) become ethereal. Besides yourself, you can bring one creature per three caster levels to the Ethereal Plane. Once ethereal, the subjects need not stay together.
When the spell expires, all affected creatures on the Ethereal Plane return to material existence.
]]

pwr_mind_blank_d=[[
此法術能保護受術者，使其免疫所有影響心靈的魔法和效果。
]]
--[[
心靈屏障（Mind Blank）
 防護系
等級：保護8，術士/法師8
法術成分：言語，姿勢
施法時間：1個標準動作
距離：近距（25英尺+5英尺/每2等級）
目標：一個生物
持續時間：24小時
豁免：意志，通過則無效（無害）
法術抗力：（無害）

此法術能保護受術者，使得所有能偵測、影響、感知思想或情緒的魔法或有相同功能的裝置，都無法對受術者發生作用。此法術不僅能阻絕所有影響心靈的魔法和效果，也能防止預言系法術或預言系效果的偵測。甚至如果用有限祈願術（limited wish），神蹟術（miracle）和祈願術（wish）來影響心靈或偵測資訊，心靈屏障也可以使其失效。若受術者處在大範圍探知法術（如祕法眼（arcane eye））的影響區域中，雖然該探知法術仍然會起作用，但卻無法偵測到心靈屏障的受術者。如果是針對受術者而來的探知法術，則完全不會有效。

Mind Blank
 Abjuration
Level: Protection 8, Sor/Wiz 8
Components: V, S
Casting Time: 1 standard action
Range: Close (25 ft. + 5 ft./2 levels)
Target: One creature
Duration: 24 hours
Saving Throw: Will negates (harmless)
Spell Resistance: Yes (harmless)

The subject is protected from all devices and spells that detect, influence, or read emotions or thoughts. This spell protects against all mind-affecting spells and effects as well as information gathering by divination spells or effects. Mind blank even foils limited wish, miracle, and wish spells when they are used in such a way as to affect the subject's mind or to gain information about it. In the case of scrying that scans an area the creature is in, such as arcane eye, the spell works but the creature simply isn't detected. Scrying attempts that are targeted specifically at the subject do not work at all.
]]

pwr_time_stop_d=[[
這個法術看上去像是讓除你之外所有人的時間都靜止了。事實上是你的速度變得非常快，使得其他生物看起來像是僵住，儘管實際上他們在正常行動。

你可以在1d4+1輪（以你的觀點）內自由行動：

- 現有的區域效果仍會傷害或影響到你。
- 其他生物不會因你的攻擊或法術而受傷；你不能以它們為攻擊或法術的目標。

大多數施法者利用這些額外的時間來加強防禦，召喚盟友，或逃離戰鬥。
]]
--[[
時間靜止（Time Stop）
 變化系
等級：術士/法師9，詭術9
法術成分：言語
施法時間：1個標準動作
距離：個人
目標：自己
持續時間：1d4+1輪（表面時間）

這個法術看上去像是讓除了你以外的其他人都進入時間靜止狀態。但事實上是你的速度變得非常快，使得其他生物看起來完全靜止，儘管他們實際上依然可以正常運動。你可以在1d4+1輪（以你的觀點）內自由行動。普通或是魔法火焰、寒冷、毒氣等依然會傷害你。時間靜止作用期間，其他生物不會因你的攻擊或法術而受傷，你不能以那些生物為物理攻擊或法術的目標。區域法術持續時間若比時間靜止剩下的時間長，則可在時間靜止結束後繼續生效。大多數施法者利用這些額外的時間來加強防禦、召喚盟友，或者逃離戰鬥。

若物品被其他生物所持有、攜帶或穿著，則你不能移動或傷害它們，但你可以影響無主物品。

在時間靜止的持續時間內，你不可被偵測。在時間靜止的效果下你不能進入被反魔場（antimagic field）保護的區域。

Time Stop
 Transmutation
Level: Sor/Wiz 9, Trickery 9
Components: V
Casting Time: 1 standard action
Range: Personal
Target: You
Duration: 1d4+1 rounds (apparent time); see text

This spell seems to make time cease to flow for everyone but you. In fact, you speed up so greatly that all other creatures seem frozen, though they are actually still moving at their normal speeds. You are free to act for 1d4+1 rounds of apparent time. Normal and magical fire, cold, gas, and the like can still harm you. While the time stop is in effect, other creatures are invulnerable to your attacks and spells; you cannot target such creatures with any attack or spell. A spell that affects an area and has a duration longer than the remaining duration of the time stop have their normal effects on other creatures once the time stop ends. Most spellcasters use the additional time to improve their defenses, summon allies, or flee from combat.

You cannot move or harm items held, carried, or worn by a creature stuck in normal time, but you can affect any item that is not in another creature's possession.

You are undetectable while time stop lasts. You cannot enter an area protected by an antimagic field while under the effect of time stop.
]]

pwr_interposing_hand_d=[[
]]
--[[
護身掌（Interposing Hand）
 塑能系 [力場]
等級：術士/法師 5
法術成分：言語，姿勢，器材
施法時間：1個標準動作
距離：中距（100英尺+10英尺/每等級）
效果：10英尺大小的手
持續時間：1輪/每等級（可解消）
豁免：無
法術抗力：可
護身掌能夠在你和一個敵人之間創造一隻大型魔法手。無論你如何改變位置，也不管你的敵人如何嘗試繞過去，這隻飄浮的無實體的手也會移動以確保始終處在在你們兩者之間，併為你在對抗這個敵人時提供遮掩（+4AC）。沒有什麼能欺騙這隻手，不論黑暗、隱形、變形或是任何隱藏或易容，它會一直跟隨著選定的敵人。但它也不會攻擊敵人。
護身掌大約長10英尺，五指張開時也大概那麼寬。它的生命值和你施法時未受傷的情況下相同，它的AC為20（-1體型，+11天生）。它會和一般生物一樣承受傷害，但大多數不造成傷害的法術對它無效。
 這隻手永遠不會被敵人所藉機攻擊。它不能穿過力場牆（wall of force），也無法進入反魔場（antimagic field），但它會受到虹光法牆（prismatic wall）與虹光法球（prismatic sphere）的全部效果。這隻手的豁免檢定與其施法者相同。
解離術（Disintegrate）或是成功的解除魔法（dispel magic）會摧毀這隻手。
 體重2,000磅或以下的生物能以半速從這隻手邊擠過去。體重2,000磅以上的生物的速度不會受此手影響，但攻擊依然會受阻。
 選擇新目標是一個移動等效動作。
器材：一隻軟手套。

Interposing Hand
 Evocation [Force]
Level: Sor/Wiz 5
Components: V, S, F
Casting Time: 1 standard action
Range: Medium (100 ft. + 10 ft./level)
Effect: 10-ft. hand
Duration: 1 round/level (D)
Saving Throw: None
Spell Resistance: Yes
Interposing hand creates a Large magic hand that appears between you and one opponent. This floating, disembodied hand then moves to remain between the two of you, regardless of where you move or how the opponent tries to get around it, providing cover (+4 AC) for you against that opponent. Nothing can fool the hand - it sticks with the selected opponent in spite of darkness, invisibility, polymorphing, or any other attempt at hiding or disguise. The hand does not pursue an opponent, however.
 An interposing hand is 10 feet long and about that wide with its fingers outstretched. It has as many hit points as you do when you're undamaged, and its AC is 20 (-1 size, +11 natural). It takes damage as a normal creature, but most magical effects that don't cause damage do not affect it.
 The hand never provokes attacks of opportunity from opponents. It cannot push through a wall of force or enter an antimagic field, but it suffers the full effect of a prismatic wall or prismatic sphere. The hand makes saving throws as its caster.
Disintegrate or a successful dispel magic destroys it.
 Any creature weighing 2,000 pounds or less that tries to push past the hand is slowed to half its normal speed. The hand cannot reduce the speed of a creature weighing more than 2,000 pounds, but it still affects the creature's attacks.
 Directing the spell to a new target is a move action.
Focus: A soft glove.
]]

pwr_forceful_hand_d=[[
]]
--[[
飛擊掌（Forceful Hand）
 塑能系[力場]
等級：術士/法師 6
法術成分：言語，姿勢，器材
 該法術作用類似護身掌（interposing hand），只是飛擊掌能夠追趕並把選定的對手推開。此攻擊視作衝撞，在力量檢定上有+14的加值（力量27帶來+8，大型+4，衝鋒時+2，而它總是可以獲得這一項）。這隻巨手總是和敵手一起移動來將目標推向所允許的最大距離，它沒有速度限制。將此法術指引向新的目標是一個移動動作。
 特別強壯的生物也無法將巨手推離方向，因為隨後巨手就會將自己重新定位在該生物和你之間，但是對手可以通過成功的衝撞巨手來將它推向你的方向。
器材：一隻皮製或厚布制的結實手套。

Forceful Hand
 Evocation [Force]
Level: Sor/Wiz 6
Components: V, S, F
 This spell functions like interposing hand, except that the forceful hand pursues and pushes away the opponent that you designate. Treat this attack as a bull rush with a +14 bonus on the Strength check (+8 for Strength 27, +4 for being Large, and a +2 bonus for charging, which it always gets). The hand always moves with the opponent to push that target back the full distance allowed, and it has no speed limit. Directing the spell to a new target is a move action.
 A very strong creature could not push the hand out of its way because the latter would instantly reposition itself between the creature and you, but an opponent could push the hand up against you by successfully bull rushing it.
Focus: A sturdy glove made of leather or heavy cloth.
]]

pwr_grasping_hand_d=[[
]]
--[[
擒拿掌（Grasping Hand）
 塑能系[力場]
等級：術士/法師 7，力量7
法術成分：言語，姿勢，器材/法器
 該法術類似護身掌（interposing hand），只是巨手還可以擒抱你選擇的一個對手。擒拿掌每輪可以獲得一次擒抱攻擊。
 要接觸對方時，它的攻擊加值為你的施法者等級加你的智力、感知、或魅力加值（分別對應法師、牧師、和術士），再加上巨手力量值（31）帶來的+10，再因為是大體型而-1。它的擒抱加值和之前演算法相同，只是大體型帶來的是+4修正而非-1。巨手可以抓住但不會傷害被擒抱的生物。
 指引該法術對新的目標是一個移動動作。
擒拿掌也可以像飛擊掌（forceful hand）一樣衝撞對手，但是在力量檢定上有+16加值（力量31帶來+10，大型+4，衝鋒時+2，而它總是可以獲得這一項）。也可以像護身掌一樣將自己插入到適當的位置。
 施放這個法術的牧師以他們的神祗來命名此法術。
奧術器材：一隻皮手套。

Grasping Hand
 Evocation [Force]
Level: Sor/Wiz 7, Strength 7
Components: V, S, F/DF
 This spell functions like interposing hand, except the hand can also grapple one opponent that you select. The grasping hand gets one grapple attack per round.
 Its attack bonus to make contact equals your caster level + your Intelligence, Wisdom, or Charisma modifier (for wizards, clerics, and sorcerers, respectively), +10 for the hand's Strength score (31), -1 for being Large. Its grapple bonus is this same figure, except with a +4 modifier for being Large instead of -1. The hand holds but does not harm creatures it grapples.
 Directing the spell to a new target is a move action.
 The grasping hand can also bull rush an opponent as forceful hand does, but at a +16 bonus on the Strength check (+10 for Strength 35, +4 for being Large, and a +2 bonus for charging, which it always gets), or interpose itself as interposing hand does.
 Clerics who cast this spell name it for their deities.
Arcane Focus: A leather glove.
]]

pwr_clenched_fist_d=[[
]]
--[[
金剛拳（Clenched Fist）
 塑能系[力場]
等級：術士/法師8，力量8
法術成分：言語，姿勢，器材/法器
 該法術類似護身掌（interposing hand），但它會用自己來給你提供防護，推開或擊打你所選定的目標。這個漂浮的魔手會以每輪60英尺的速度移動並在同一輪中進行攻擊。因為魔手是由你控制，所以它發現隱身和隱蔽的能力與你相同。
 魔手每輪可以攻擊一次，它的攻擊加值為你的施法者等級加上你的智力調整值（法師）、魅力調整值（術士）或感知調整值（牧師），再加上魔手本身的力量調整值+11（魔手力量33），再因為是大體型而-1。魔手每次攻擊造成1d8+11點傷害，任何被擊中的目標必須通過一次強韌檢定（對抗該法術豁免檢定DC）否則將被震懾1輪。命令魔手去選擇一個新的目標是一個移動動作。
金剛拳可以如同護身掌一樣將自己插入到適當的位置，也可以嘗試像飛擊掌（forceful hand）一樣衝撞對手，但它的力量檢定加值為+15。
 施放這個法術的牧師以他們的神祗來命名此法術。
奧術器材：一隻皮製手套。

Clenched Fist
 Evocation [Force]
Level: Sor/Wiz 8, Strength 8
Components: V, S, F/DF
 This spell functions like interposing hand, except that the hand can interpose itself, push, or strike one opponent that you select. The floating hand can move as far as 60 feet and can attack in the same round. Since this hand is directed by you, its ability to notice or attack invisible or concealed creatures is no better than yours.
 The hand attacks once per round, and its attack bonus equals your caster level + your Intelligence, Wisdom, or Charisma modifier (for a wizard, cleric, or sorcerer, respectively), +11 for the hand's Strength score (33), -1 for being Large. The hand deals 1d8+11 points of damage on each attack, and any creature struck must make a Fortitude save (against this spell's save DC) or be stunned for 1 round. Directing the spell to a new target is a move action.
 The clenched fist can also interpose itself as interposing hand does, or it can bull rush an opponent as forceful hand does, but at a +15 bonus on the Strength check.
 Clerics who cast this spell name it for their deities.
Arcane Focus: A leather glove.
]]

pwr_crushing_hand_d=[[
]]
--[[
粉碎掌（Crushing Hand）
 塑能系[力場]
等級：術士/法師9，力量9
法術成分：言語、姿勢、材料、器材/法器
 該法術類似護身掌（interposing hand），不同的是它能自動遮掩施法者，推開或碾壓一個你挑選的目標。
粉碎掌能像擒拿掌（grasping hand）一樣擒抱一個生物。它的擒抱加值等於你的施法者等級+你的智力（法師）、感知（牧師）、或者魅力（術士）修正，魔手本身力量加值+12（力量35），大體形+4加值。魔手可以在每次擒抱成功後對目標造成2d6+12點傷害（正常傷害，並非非致命傷）。
粉碎掌可以像護身掌一樣掩護你，也可以像飛擊掌（forceful hand）一樣衝撞對手，不過力量檢定加值為+18。
 指引該魔手往新的目標是一個類移動動作。
 施法的牧師以他的神祗來命名此法術。
奧術材料成分：一個雞蛋殼。
奧術器材：一隻蛇皮手套。

Crushing Hand
 Evocation [Force]
Level: Sor/Wiz 9, Strength 9
Components: V, S, M, F/DF
 This spell functions like interposing hand, except that the hand can interpose itself, push, or crush one opponent that you select.
 The crushing hand can grapple an opponent like grasping hand does. Its grapple bonus equals your caster level + your Intelligence, Wisdom, or Charisma modifier (for a wizard, cleric, or sorcerer, respectively), +12 for the hand's Strength score (35), +4 for being Large. The hand deals 2d6+12 points of damage (lethal, not nonlethal) on each successful grapple check against an opponent.
 The crushing hand can also interpose itself as interposing hand does, or it can bull rush an opponent as forceful hand does, but at a +18 bonus.
 Directing the spell to a new target is a move action.
 Clerics who cast this spell name it for their deities.
