pwr_mages_faithful_hound_d=[[
]]
--[[
法師忠犬（Mage’s Faithful Hound）
 咒法系（創造）
等級：術士/法師5
法術成分：言語，姿勢，材料
施法時間：1個標準動作
距離：近距（25英尺+5英尺/每2等級）
效果：魅影守護犬
持續時間：1小時/施法者等級或直到能量散發，之後1輪/施法者每等級；見說明
豁免：無
法術抗力：不可
 你造出一條只有你看得見的魅影守護犬。它會保衛創造地點周圍的區域（它不會移動）。如果有小型或更大的生物進入魅影守護犬附近30英尺內，它就會大聲開始吠叫。（如果守護犬出現時30英尺範圍內已經有生物存在，則這些生物可以在這一區域內自由移動。但如果他們離開此範圍又再進來，還是會引發吠叫。）守護犬可以看見隱形生物和靈體生物。它不會理會虛假幻影，但會發現幽影幻象。
 如果入侵者接近守護犬周圍5英尺內，它會停止吠叫並展開凶狠的攻擊，每輪可以咬一口（+10攻擊加值，2D6+3點穿刺傷害）。守護犬擁有隱形生物的戰鬥優勢。
 守護犬處於準備攻擊的狀態，所以可以在入侵者的回合中咬第一下。在對抗傷害減免時，守護犬的齧咬視為魔法武器。守護犬可以被解除，但不能被攻擊。
 未觸發前，法術的持續時間是1小時/施法者每等級。然而，一旦守護犬開始吠叫，持續時間就只剩下1輪/施法者每等級。如果你和狗的距離超過100英尺，法術就會終止。
材料成分：一個微型銀質哨子，一塊骨頭和一條線

Mage's Faithful Hound
 Conjuration (Creation)
Level: Sor/Wiz 5
Components: V, S, M
Casting Time: 1 standard action
Range: Close (25 ft. + 5 ft./2 levels)
Effect: Phantom watchdog
Duration: 1 hour/caster level or until discharged, then 1 round/caster level; see text
Saving Throw: None
Spell Resistance: No
 You conjure up a phantom watchdog that is invisible to everyone but yourself. It then guards the area where it was conjured (it does not move). The hound immediately starts barking loudly if any Small or larger creature approaches within 30 feet of it. (Those within 30 feet of the hound when it is conjured may move about in the area, but if they leave and return, they activate the barking.) The hound sees invisible and ethereal creatures. It does not react to figments, but it does react to shadow illusions.
 If an intruder approaches to within 5 feet of the hound, the dog stops barking and delivers a vicious bite (+10 attack bonus, 2d6+3 points of piercing damage) once per round. The dog also gets the bonuses appropriate to an invisible creature.
 The dog is considered ready to bite intruders, so it delivers its first bite on the intruder's turn. Its bite is the equivalent of a magic weapon for the purpose of damage reduction. The hound cannot be attacked, but it can be dispelled.
 The spell lasts for 1 hour per caster level, but once the hound begins barking, it lasts only 1 round per caster level. If you are ever more than 100 feet distant from the hound, the spell ends.
Material Component: A tiny silver whistle, a piece of bone, and a thread.
]]

pwr_feeblemind_c=[[
生物的智力和魅力值都掉到1，不能使用基於智力或魅力的技能，不能施法，不能理解語言，但依然能分清敵我。

醫療術可移除此效果。
]]

pwr_feeblemind_d=[[
如果目標生物在意志豁免中失敗，他的智力和魅力值都將掉到1。被影響的生物不能使用基於智力或魅力的技能，不能施法，不能理解語言，但依然能分清敵我。

醫療術可移除此效果。

能施展奧術的生物，例如術士或法師，在他的豁免判定中要受到-4減值。
]]
--[[
弱智術（Feeblemind）
 惑控系（脅迫）[影響心靈]
等級：術士/法師 5
法術成分：言語，姿勢，材料
施法時間：一個標準動作
距離：中距（100英尺+10英尺/每等級）
目標：一個生物
持續時間：立即
豁免：意志通過則無效；見正文
法術抗力：可
如果目標生物在意志豁免中失敗，他的智力和魅力值都將掉到1。被影響的生物不能使用任何基於智力或魅力的技能，不能施法，不能理解語言，也不能連貫的交流。但是他依然知道誰是他的朋友，也能跟隨他們行動，甚至可以保護他們。受術者會始終保持這一狀態，直到被醫療術（heal）、有限祈願術（limited wish）、神蹟術（miracle）、或祈願術（wish）來取消掉弱智術效果為止。能施展奧術的生物，例如術士或法師，在他的豁免判定中要受到-4減值。
材料成分：一把粘土、水晶、玻璃、或礦石小球。


Feeblemind
 Enchantment (Compulsion) [Mind-Affecting]
Level: Sor/Wiz 5
Components: V, S, M
Casting Time: 1 standard action
Range: Medium (100 ft. + 10 ft./level)
Target: One creature
Duration: Instantaneous
Saving Throw: Will negates; see text
Spell Resistance: Yes
If the target creature fails a Will saving throw, its Intelligence and Charisma scores each drop to 1. The affected creature is unable to use Intelligence- or Charisma-based skills, cast spells, understand language, or communicate coherently. Still, it knows who its friends are and can follow them and even protect them. The subject remains in this state until a heal, limited wish, miracle, or wish spell is used to cancel the effect of the feeblemind. A creature that can cast arcane spells, such as a sorcerer or a wizard, takes a -4 penalty on its saving throw.
Material Component: A handful of clay, crystal, glass, or mineral spheres.
]]

pwr_mind_fog_d=[[
心靈迷霧可以造出一片薄薄的霧氣來削弱身處其中生物的心智抵抗力。

霧氣中生物的感知檢定和意志豁免-10環境減值。意志豁免成功則不受影響，且不用再對同一團霧氣做檢定。

受影響的生物在霧氣中會一直遭受減值，離開後2d6輪恢復正常。

霧氣本身很稀薄，不會影響視覺。
]]
--[[
心靈迷霧（Mind Fog）
 惑控系（脅迫）[影響心靈]
等級：吟遊詩人5，術士/法師5
法術成分：言語，姿勢
施法時間：1個標準動作
距離：中距（100英尺+10英尺/施法者每等級）
效果：半徑20英尺，高20英尺的瀰漫範圍內充滿迷霧
持續時間：30分鐘+2D6輪；見說明
豁免：意志，通過則無效
法術抗力：可

心靈迷霧可以造出一片薄薄的霧氣來削弱身處其中生物的心智抵抗力。霧氣中的生物，在進行感知檢定和意志豁免時，受到-10的環境減值。（如果生物通過了對霧氣的意志檢定，將不受影響，並且不用再對同一團霧氣再做檢定，即使是繼續待在霧中也是一樣。）受影響的生物只要不離開霧氣範圍就會一直受到影響，離開後需要2d6輪才能恢復正常。霧氣本身不會移動，而且可以持續30分鐘（或直到被風吹散為止）。和風（時速11英里以上）在4輪之內吹散雲霧。強風（時速21英里以上）可以一輪吹散。

霧氣本身很稀薄，不會影響視覺。

Mind Fog
 Enchantment (Compulsion) [Mind-Affecting]
Level: Brd 5, Sor/Wiz 5
Components: V, S
Casting Time: 1 standard action
Range: Medium (100 ft. + 10 ft./level)
Effect: Fog spreads in 20-ft. radius, 20 ft. high
Duration: 30 minutes and 2d6 rounds; see text
Saving Throw: Will negates
Spell Resistance: Yes

Mind fog produces a bank of thin mist that weakens the mental resistance of those caught in it. Creatures in the mind fog take a -10 competence penalty on Wisdom checks and Will saves. (A creature that successfully saves against the fog is not affected and need not make further saves even if it remains in the fog.) Affected creatures take the penalty as long as they remain in the fog and for 2d6 rounds thereafter. The fog is stationary and lasts for 30 minutes (or until dispersed by wind).

A moderate wind (11+ mph) disperses the fog in four rounds; a strong wind (21+ mph) disperses the fog in 1 round.

The fog is thin and does not significantly hamper vision.
]]

pwr_waves_of_fatigue_d=[[
負能量波使得法術範圍內的所有活物疲乏。此法術對已疲乏的生物無效。
]]
--[[
疲乏波（Waves of Fatigue）
 死靈系
等級：術士/法師5
法術成分：言語，姿勢
施法時間：1個標準動作
距離：30英尺
區域：錐形爆發範圍
持續時間：立即
豁免：無
法術抗力：可
負能量波會使得法術範圍內的所有活物疲乏（fatigued）。本法術對已經陷入疲乏的生物無效。

Waves of Fatigue
 Necromancy
Level: Sor/Wiz 5
Components: V, S
Casting Time: 1 standard action
Range: 30 ft.
Area: Cone-shaped burst
Duration: Instantaneous
Saving Throw: No
Spell Resistance: Yes
Waves of negative energy render all living creatures in the spell's area fatigued. This spell has no effect on a creature that is already fatigued.
]]

pwr_goi_l_d=[[
一個散發著微光的固定魔法球體環繞著你，將3級或更低的法術效果排除在外，但不包括施放結界時已生效的法術。任何法術都可穿過或穿出此結界。
]]
--[[
次等法術無效結界（Globe of Invulnerability, Lesser）
 防護系
等級：術士/法師 4
法術成分：言語，姿勢，材料
施法時間：一個標準動作
距離：10英尺
區域：以你為中心的10英尺球形瀰漫範圍
持續時間：1輪/每等級（可解消）
豁免：無
法術抗力：不可
 一個散發著微光的固定魔法球體環繞著你，它可以將所有3級或更低的法術效果排除在外。任何這類法術的區域或效果將無法包括次等法術無效結界的區域。這類法術將無法影響結界內部的任何目標。被排斥的效果包括類法術能力和物品產生的法術或類法術效果。但是，任何型別的法術都可以穿過或穿出這個魔法結界。4級或更高等級的法術不受結界影響，那些在施放結界時已經發揮作用的法術也不受影響。結界可以被目標型解除魔法（dispel magic）所解除，但是不會被區域型解除魔法解除。你可以離開然後再返回結界，這樣不會有任何懲罰。
 注意，法術的效果不會被中止，除非它們的效果進入了結界。即使這樣也只是被壓制，而非被解除。
 如果給定的法術在不同職業施展的時候有不同的等級，那麼在確定次等法術無效結界是否能阻止它的時候使用和施法者對應的那個等級。
材料成分：一個玻璃或水晶珠，在法術持續時間結束時會粉碎。

Globe of Invulnerability, Lesser
 Abjuration
Level: Sor/Wiz 4
Components: V, S, M
Casting Time: 1 standard action
Range: 10 ft.
Area: 10-ft.-radius spherical emanation, centered on you
Duration: 1 round/level (D)
Saving Throw: None
Spell Resistance: No
 An immobile, faintly shimmering magical sphere surrounds you and excludes all spell effects of 3rd level or lower. The area or effect of any such spells does not include the area of the lesser globe of invulnerability. Such spells fail to affect any target located within the globe. Excluded effects include spell-like abilities and spells or spell-like effects from items. However, any type of spell can be cast through or out of the magical globe. Spells of 4th level and higher are not affected by the globe, nor are spells already in effect when the globe is cast. The globe can be brought down by a targeted dispel magic spell, but not by an area dispel magic. You can leave and return to the globe without penalty.
 Note that spell effects are not disrupted unless their effects enter the globe, and even then they are merely suppressed, not dispelled. 
 If a given spell has more than one level depending on which character class is casting it, use the level appropriate to the caster to determine whether lesser globe of invulnerability stops it.
Material Component: A glass or crystal bead that shatters at the expiration of the spell.
]]

pwr_goi_d=[[
類似次等法術無效結界，只是它還可以排斥4級法術和類法術效果。
]]
--[[
法術無效結界（Globe of Invulnerability）
 防護系
等級：術士/法師 6
該法術功能類似次等法術無效結界，只是它還可以排斥4級法術和類法術效果。

Globe of Invulnerability
 Abjuration
Level: Sor/Wiz 6
This spell functions like lesser globe of invulnerability, except that it also excludes 4th-level spells and spell-like effects.
]]

pwr_stoneskin_d=[[
受術者獲得對刀砍斧削的抵抗能力，擁有每5級10/精金的傷害減免。當吸收的傷害值達到10x施法者等級後，法術耗散。
]]
--[[
石膚術（Stoneskin）
 防護系
等級：德魯伊 5，土 6，術士/法師 4，力量 6
法術成分：言語，姿勢，材料
施法時間：一個標準動作
距離：接觸
目標：被接觸的生物
持續時間： 10分鐘/等級或直到能量散發
豁免：意志，通過則無效（無害）
法術抗力：可（無害）
受術者獲得對刀砍斧削的抵抗能力。受術者獲得10/精金的傷害減免（每次受到武器傷害時吸收前10點傷害，但無法吸收精金武器造成的傷害。）當法術吸收的傷害值達到10x施法者等級（最多150點）後，法術效果消失。
材料成分：花崗岩和價值250金幣的鑽石塵，撒在受術者面板上。.

Stoneskin
 Abjuration
Level: Drd 5, Earth 6, Sor/Wiz 4, Strength 6
Components: V, S, M
Casting Time: 1 standard action
Range: Touch
Target: Creature touched
Duration: 10 min./level or until discharged
Saving Throw: Will negates (harmless)
Spell Resistance: Yes (harmless)
The warded creature gains resistance to blows, cuts, stabs, and slashes. The subject gains damage reduction 10/adamantine. (It ignores the first 10 points of damage each time it takes damage from a weapon, though an adamantine weapon bypasses the reduction.) Once the spell has prevented a total of 10 points of damage per caster level (maximum 150 points), it is discharged.
Material Component: Granite and 250 gp worth of diamond dust sprinkled on the target's skin.
]]

pwr_black_tentacles_d=[[
]]
--[[
黑觸手（Black Tentacles）
 咒法系（創造）
等級：術士/法師 4
法術成分：言語，姿勢，材料
施法時間：一個標準動作
距離：中距（100英尺+10英尺/每施法者等級）
區域：20英尺半徑擴散
持續時間：1輪/每等級（可解消）
豁免：無
法術抗力：不可
 這個法術產生一片強韌的黑觸手，每條長10英尺。這些湧動的觸手看上去是從任何腳下的表面冒出，從泥土中，地板上，以及水面。它們緊緊抓住並纏住進入這片區域的生物，以強大的力量困住它們，之後碾碎它們。
 進入法術區域內的所有生物都必須進行一個擒抱檢定，和觸手的擒抱檢定對抗。這些觸手視作大型生物的一部分，基本攻擊加值等於你的施法者等級，力量值為19。因此，它的擒抱檢定調整值等於你的施法者等級+8。這些觸手免疫所有型別傷害。一旦觸手擒抱住一個敵手，它們會在你的回合中每輪做一次擒抱檢定來產生1d6+4點鈍擊傷害。觸手會一致擠壓敵手，直到法術結束或敵手脫逃。
 任何進入法術區域的生物會立刻被觸手攻擊。儘管沒有被觸手擒抱住的生物可以移出這個區域，但是隻能以正常速度的一半移動。
材料成分：一片巨章魚或巨烏賊的觸手。

Black Tentacles
 Conjuration (Creation)
Level: Sor/Wiz 4
Components: V, S, M
Casting Time: 1 standard action
Range: Medium (100 ft. + 10 ft./level)
Area: 20-ft.-radius spread
Duration: 1 round/level (D)
Saving Throw: None
Spell Resistance: No
 This spell conjures a field of rubbery black tentacles, each 10 feet long. These waving members seem to spring forth from the earth, floor, or whatever surface is underfoot - including water. They grasp and entwine around creatures that enter the area, holding them fast and crushing them with great strength.
 Every creature within the area of the spell must make a grapple check, opposed by the grapple check of the tentacles. Treat the tentacles attacking a particular target as a Large creature with a base attack bonus equal to your caster level and a Strength score of 19. Thus, its grapple check modifier is equal to your caster level +8. The tentacles are immune to all types of damage.
 Once the tentacles grapple an opponent, they may make a grapple check each round on your turn to deal 1d6+4 points of bludgeoning damage. The tentacles continue to crush the opponent until the spell ends or the opponent escapes.
 Any creature that enters the area of the spell is immediately attacked by the tentacles. Even creatures who aren't grappling with the tentacles may move through the area at only half normal speed.
Material Component: A piece of tentacle from a giant octopus or a giant squid.
]]

pwr_dimension_door_d=[[
]]
--[[
任意門（Dimension Door）
 咒法系（傳送）
等級：吟遊詩人 4，術士/法師 4，旅行 4
法術成分：言語
施法時間： 一個標準動作
距離：遠距 （400英尺+40英尺/等級）
目標：你和你接觸到的物品，或其他被接觸的自願生物。
持續時間：立即
豁免檢定：無，以及意志通過則無效（物體）
法術抗力：不可與可（物體）
 你可瞬間將自己傳送到法術距離內的任何地方。你總是可以到達你想到達的位置——不管你是看到那地方還是僅僅聲明瞭方向。使用完此法術後，直到下一輪之前不能再做任何動作。你可以攜帶不超過你最大負載能力的物品，每三級施法者等級可以帶一個自願的中體型或小體型生物（攜帶不超過其最大負載能力的裝備、物品）或相當於此的生物。一個大型生物視作兩個中型生物，一個超大型生物視作兩個大型生物。被傳送的生物之間必須相互接觸，並且它們中至少有一個與你接觸。
 若你傳送到一個由固體佔據的位置，你和隨你旅行的每個生物都受到1d6點傷害，並被擠到100英尺內的固體表面的隨機開放空間開口處。
 若100英尺內沒有空地，你和隨你旅行的生物都會受到額外的2d6點傷害，並被隨機擠到1000英尺內的空地。若1000英尺內沒有空地，你和隨你旅行的生物都受到額外的4d6點傷害，並且施法失敗。

Dimension Door
 Conjuration (Teleportation)
Level: Brd 4, Sor/Wiz 4, Travel 4
Components: V
Casting Time: 1 standard action
Range: Long (400 ft. + 40 ft./level)
Target: You and touched objects or other touched willing creatures
Duration: Instantaneous
Saving Throw: None and Will negates (object)
Spell Resistance: No and Yes (object)
 You instantly transfer yourself from your current location to any other spot within range. You always arrive at exactly the spot desired - whether by simply visualizing the area or by stating direction. After using this spell, you can't take any other actions until your next turn. You can bring along objects as long as their weight doesn't exceed your maximum load. You may also bring one additional willing Medium or smaller creature (carrying gear or objects up to its maximum load) or its equivalent per three caster levels. A Large creature counts as two Medium creatures, a Huge creature counts as two Large creatures, and so forth. All creatures to be transported must be in contact with one another, and at least one of those creatures must be in contact with you.
 If you arrive in a place that is already occupied by a solid body, you and each creature traveling with you take 1d6 points of damage and are shunted to a random open space on a suitable surface within 100 feet of the intended location.
 If there is no free space within 100 feet, you and each creature traveling with you take an additional 2d6 points of damage and are shunted to a free space within 1,000 feet. If there is no free space within 1,000 feet, you and each creature travelling with you take an additional 4d6 points of damage and the spell simply fails.
]]

pwr_obscuring_mist_d=[[
]]
--[[
隱霧術（Obscuring Mist）
 咒法系（創造）
等級：風1，牧師1，德魯伊1，術士/法師1，水1
法術成分：言語，姿勢
施法時間：1個標準動作
距離：20英尺
效果：以你為中心擴散出高20英尺，半徑20英尺的雲霧。
持續時間：1分鐘/施法者每等級
豁免：無
法術抗力：不可
 一團霧氣從你四周升起，霧氣出現後就不再移動。霧氣遮蔽了所有的視線，任何生物都無法看見5英尺外的東西（即使具有黑暗視覺也一樣）。距離5英尺的生物有隱蔽效果（進行攻擊會有20%的失手率），更遠的生物則有全隱蔽效果（50%失手率，並且攻擊者無法以視覺確定對方的位置）。
 和風（時速11英里以上），例如由造風術（gust of wind）產生的風，可以在4輪之內吹散雲霧。強風（時速21英里以上）可以一輪吹散。火球術（fireball）、焰擊術（flame strike）或類似的法術可以將爆炸範圍或火焰範圍內的霧氣燒光。火牆術（wall of fire）則可以把它能造成傷害的範圍內的霧氣燒光。
 此法術在水中無效。

Obscuring Mist
 Conjuration (Creation)
Level: Air 1, Clr 1, Drd 1, Sor/Wiz 1, Water 1
Components: V, S
Casting Time: 1 standard action
Range: 20 ft.
Effect: Cloud spreads in 20-ft. radius from you, 20 ft. high
Duration: 1 min./level
Saving Throw: None
Spell Resistance: No
 A misty vapor arises around you. It is stationary once created. The vapor obscures all sight, including darkvision, beyond 5 feet. A creature 5 feet away has concealment (attacks have a 20% miss chance). Creatures farther away have total concealment (50% miss chance, and the attacker cannot use sight to locate the target).
 A moderate wind (11+ mph), such as from a gust of wind spell, disperses the fog in 4 rounds. A strong wind (21+ mph) disperses the fog in 1 round. A fireball, flame strike, or similar spell burns away the fog in the explosive or fiery spell's area. A wall of fire burns away the fog in the area into which it deals damage.
 This spell does not function underwater.
]]

pwr_fog_cloud_d=[[
濃霧遮住了5英尺外的視覺。5英尺內的生物具有隱蔽（20%失手率）。更遠的生物具有全隱蔽（50%失手率，並且攻擊者不能用視覺來定位目標）。火焰傷害類法術可將其影響範圍內的霧氣燒掉。
]]-- 隱霧術和雲霧術都生成濃霧 雖僅隱霧術提到可被火燒 但二者應該都適用
--[[
雲霧術（Fog Cloud）
 咒法系（創造）
等級：德魯伊 2，術士/法師 2，水 2
法術成分：言語，姿勢
施法時間：一個標準動作
距離：中距（100英尺+10英尺/每等級）
效果：20英尺半徑擴散，20英尺高的霧
持續時間：10分鐘/每等級
豁免：無
法術抗力：不可
 一道霧牆從你指定點翻騰著向外湧出。這道霧遮住了所有5英尺以外的視覺，包括黑暗視覺。在5英尺以內的生物具有隱蔽（攻擊有20%失手率）。更遠的生物具有全隱蔽（50%的失手率，並且攻擊者不能用視覺來定位目標）。
 常風（時速超過11英里）可以在4輪內吹散霧氣；強風（時速超過21英里）可以在1輪內吹散。
 這個法術在水下沒有作用。

Fog Cloud
 Conjuration (Creation)
Level: Drd 2, Sor/Wiz 2, Water 2
Components: V, S
Casting Time: 1 standard action
Range: Medium (100 ft. + 10 ft. level)
Effect: Fog spreads in 20-ft. radius, 20 ft. high
Duration: 10 min./level
Saving Throw: None
Spell Resistance: No
 A bank of fog billows out from the point you designate. The fog obscures all sight, including darkvision, beyond 5 feet. A creature within 5 feet has concealment (attacks have a 20% miss chance). Creatures farther away have total concealment (50% miss chance, and the attacker can't use sight to locate the target).
 A moderate wind (11+ mph) disperses the fog in 4 rounds; a strong wind (21+ mph) disperses the fog in 1 round.
 The spell does not function underwater.
]]

pwr_solid_fog_d=[[
這團霧遮住了5英尺外的視覺。5英尺內的生物具有隱蔽（20%失手率）。更遠的生物具有全隱蔽（50%失手率，並且攻擊者不能用視覺來定位目標）。區域內生物速度降到5英尺且不能5尺快步，近戰攻擊和傷害檢定-2減值，而遠端武器攻擊則被徹底阻止。
]]
--[[
重霧術（Solid Fog）
 咒法系（創造）
等級：術士/法師 4
法術成分：言語，姿勢，材料
持續時間：1分鐘/等級
法術抗力：不可
 與雲霧術（fog cloud） 類似，不過除了遮蔽視線外，重霧會使得任何穿越它的生物速度降到5英尺，不論它的正常速度是多少，同時在近戰攻擊檢定和近戰傷害上獲得-2的減值。霧氣還可阻止遠端攻擊（魔法射線和類似效果除外）。掉進重霧區域的生物或物體會減速，因此每經過10尺霧氣，它所受到的墜落傷害就會減少1d6點。在重霧中，生物不能進行5尺快步。
 與普通霧氣不同，只有烈風（時速31英里以上）才能吹散它，並且需花費1輪時間。
重霧術可以用魔法恆定術（permanency）來永久化。被大風吹散的永久化重霧在10分鐘後會重新形成。
材料成分：一撮乾燥的豌豆粉末，摻以動物蹄粉末。

Solid Fog
 Conjuration (Creation)
Level: Sor/Wiz 4
Components: V, S, M
Duration: 1 min./level
Spell Resistance: No
 This spell functions like fog cloud, but in addition to obscuring sight, the solid fog is so thick that any creature attempting to move through it progresses at a speed of 5 feet, regardless of its normal speed, and it takes a -2 penalty on all melee attack and melee damage rolls. The vapors prevent effective ranged weapon attacks (except for magic rays and the like). A creature or object that falls into solid fog is slowed, so that each 10 feet of vapor that it passes through reduces falling damage by 1d6. A creature can't take a 5-foot step while in solid fog.
 However, unlike normal fog, only a severe wind (31+ mph) disperses these vapors, and it does so in 1 round.
Solid fog can be made permanent with a permanency spell. A permanent solid fog dispersed by wind reforms in 10 minutes.
Material Component: A pinch of dried, powdered peas combined with powdered animal hoof.
]]

pwr_stinking_cloud_d=[[
]]
--[[
臭雲術（Stinking Cloud）
 咒法系（創造）
等級：術士/法師 3
法術成分：言語，姿勢，材料
施法時間：一個標準動作
距離：中距（100英尺+10英尺/每等級）
效果：擴散出半徑20英尺，高20英尺的雲
持續時間：1輪/等級
豁免：強韌，通過則無效
法術抗力：不可
 和雲霧術（fog cloud）一樣，臭雲術會造出一團雲霧，不過這雲霧令人作嘔。被雲霧籠罩的活物會反胃（nauseated）。只要生物還在這團雲霧中，那麼效果會一直持續，離開雲霧後還會持續1d4+1輪。（每個生物分別投骰。）任何通過強韌豁免後仍留在雲霧中的生物，每輪都需重投豁免。
臭雲術可以用魔法恆定術（permanency）來永久化。被風吹散的永久化臭雲術會在十分鐘後重組。
材料成分：一個臭雞蛋或幾根臭菘草葉子。

Stinking Cloud
 Conjuration (Creation)
Level: Sor/Wiz 3
Components: V, S, M
Casting Time: 1 standard action
Range: Medium (100 ft. + 10 ft./level)
Effect: Cloud spreads in 20-ft. radius, 20 ft. high
Duration: 1 round/level
Saving Throw: Fortitude negates; see text
Spell Resistance: No
Stinking cloud creates a bank of fog like that created by fog cloud, except that the vapors are nauseating. Living creatures in the cloud become nauseated. This condition lasts as long as the creature is in the cloud and for 1d4+1 rounds after it leaves. (Roll separately for each nauseated character.) Any creature that succeeds on its save but remains in the cloud must continue to save each round on your turn.
Stinking cloud can be made permanent with a permanency spell. A permanent stinking cloud dispersed by wind reforms in 10 minutes.
Material Component: A rotten egg or several skunk cabbage leaves.
]]

pwr_fire_cloud_d="焚雲術造出一股充滿白熱灰燼的沸騰煙雲。每輪在你的回合中炙熱的灰燼對身處其中的所有生物造成每4級1d6點火焰傷害。目標每輪做反射檢定，成功則只受一半傷害。"
--[[
焚雲術（Incendiary Cloud）
 咒法 (創造) [火]
等級：火8，術士/法師8
法術成分：言語，姿勢
施法時間：1個標準動作
距離：中距（100英尺+10英尺/每等級）
效果：擴散出寬20英尺高20英尺的雲
持續時間：一輪/級別
豁免：反射，通過則減半，見下文
法術抗力：不可

焚雲術造出一股充滿白熱灰燼的沸騰煙雲。該雲霧就如雲霧術（fog cloud）一樣阻礙視線。此外，在你的回合中每輪炙熱的灰燼對身處其中的物品造成4d6點火傷害。目標每輪做反射檢定，成功的話只受一半傷害。

如同死雲術（cloudkill）一樣，該雲霧以每輪十尺的速度移開你。每一輪都要以雲霧新的源發點開始計算新的擴散範圍，源發點的距離為每輪遠離施法時的起點10英尺。通過專注精神，你可以指引雲霧（實際上是它的源發點）以至多每輪60英尺的速度移動。雲霧任何超出最大法術距離的部分都會無害的消散，從而減少剩餘部分的擴散區域。

如同雲霧術一樣，風能吹散雲霧，而且該法術不能在水下施展。

Incendiary Cloud
 Conjuration (Creation) [Fire]
Level: Fire 8, Sor/Wiz 8
Components: V, S
Casting Time: 1 standard action
Range: Medium (100 ft. + 10 ft./level)
Effect: Cloud spreads in 20-ft. radius, 20 ft. high
Duration: 1 round/level
Saving Throw: Reflex half; see text
Spell Resistance: No

An incendiary cloud spell creates a cloud of roiling smoke shot through with white-hot embers. The smoke obscures all sight as a fog cloud does. In addition, the white-hot embers within the cloud deal 4d6 points of fire damage to everything within the cloud on your turn each round. All targets can make Reflex saves each round to take half damage.

As with a cloudkill spell, the smoke moves away from you at 10 feet per round. Figure out the smoke's new spread each round based on its new point of origin, which is 10 feet farther away from where you were when you cast the spell. By concentrating, you can make the cloud (actually its point of origin) move as much as 60 feet each round. Any portion of the cloud that would extend beyond your maximum range dissipates harmlessly, reducing the remainder's spread thereafter.

As with fog cloud, wind disperses the smoke, and the spell can't be cast underwater.
]]

pwr_confusion_d=[[
]]
--[[
困惑術（Confusion）
惑控系（脅迫）[影響心靈]
等級：吟遊詩人3，術士/法師4，詭術4
法術成分：言語，姿勢，材料/法器
施法時間：一個標準動作
距離：中距（100英尺+10英尺/每等級）
目標：半徑15英尺內的所有生物
持續時間：1輪/每等級
豁免檢定：意志，通過則無效
法術抗力：可
此法術讓目標變得困惑（confused）起來，讓他們不能獨自下決心該做什麼。
在每個受術者每一輪開始前投骰查表來決定該輪內他將會做什麼。
百分骰	行為
01-10	用近戰或遠端武器攻擊施法者 (或者在無法攻擊的時候靠近施法者)。
11-20	行為正常。
21-50	不做任何事情但毫無條理的胡言亂語。
51-70	以最快的速度遠離施法者。
71-100	攻擊最接近的生物 (在這裡，魔寵將被認為是受術者身體的一部分)。
困惑中的生物無法完成要做的事情時將什麼也不會做，只能胡言亂語。攻擊困惑中的生物不會有什麼特別優勢。困惑中的生物被攻擊後將自動在下回合反擊攻擊者，只要那時候他依然處於困惑狀態。注意，除了已經準備攻擊的生物（要麼是困惑生物上一輪的目標，要麼是剛攻擊過困惑生物的生物），困惑生物將不會對其他生物進行藉機攻擊。
奧術材料：三個為一組的堅果殼。

Confusion
Enchantment (Compulsion) [Mind-Affecting]
Level: Brd 3, Sor/Wiz 4, Trickery 4
Components: V, S, M/DF
Casting Time: 1 standard action
Range: Medium (100 ft. + 10 ft./level)
Targets: All creatures in a 15-ft. radius burst
Duration: 1 round/level
Saving Throw: Will negates
Spell Resistance: Yes
This spell causes the targets to become confused, making them unable to independently determine what they will do.
Roll on the following table at the beginning of each subject's turn each round to see what the subject does in that round.
d%	Behavior
01-10	Attack caster with melee or ranged weapons (or close with caster if attack is not possible).
11-20	Act normally.
21-50	Do nothing but babble incoherently.
51-70	Flee away from caster at top possible speed.
71-100	Attack nearest creature (for this purpose, a familiar counts as part of the subject's self).
A confused character who can't carry out the indicated action does nothing but babble incoherently. Attackers are not at any special advantage when attacking a confused character. Any confused character who is attacked automatically attacks its attackers on its next turn, as long as it is still confused when its turn comes. Note that a confused character will not make attacks of opportunity against any creature that it is not already devoted to attacking (either because of its most recent action or because it has just been attacked).
Arcane Material Component: A set of three nut shells.
]]

pwr_good_hope_d=[[
這個法術給受術者持續灌輸以強有力的希望。每個受影響的生物在豁免判定，攻擊判定，屬性檢定，技能檢定，武器傷害判定上均獲得+2士氣加值。
]]
--[[
強大希望（Good Hope）
 惑控系（脅迫）[影響心靈]
等級：吟遊詩人 3
法術成分：言語，姿勢
施法時間：一個標準動作
距離：中距（100英尺+10英尺/每等級）
目標：每等級一個活物，任意兩者之間距離不得超過30英尺
持續時間：1分鐘/每等級
豁免：意志，通過則無效（無害）
法術抗力：可（無害）
這個法術給受術者持續灌輸以強有力的希望。每個受影響的生物在豁免判定，攻擊判定，屬性檢定，技能檢定，武器傷害判定上均獲得+2士氣加值。
強大希望反制並解除極度絕望（crushing despair）。

Good Hope
 Enchantment (Compulsion) [Mind-Affecting]
Level: Brd 3
Components: V, S
Casting Time: 1 standard action
Range: Medium (100 ft. + 10 ft./level)
Targets: One living creature/level, no two of which may be more than 30 ft. apart
Duration: 1 min./level
Saving Throw: Will negates (harmless)
Spell Resistance: Yes (harmless)
This spell instills powerful hope in the subjects. Each affected creature gains a +2 morale bonus on saving throws, attack rolls, ability checks, skill checks, and weapon damage rolls.
Good hope counters and dispels crushing despair.
]]

pwr_crushing_despair_d=[[
一股無形的、使人因絕望而悲傷至極的錐狀能量在受影響的區域內爆發。每個受影響的生物以下檢定將受到-2減值：攻擊骰，豁免，屬性檢定，技能檢定，和武器傷害骰。
]]
--[[
極度絕望（Crushing Despair）
 惑控系（脅迫）[影響心靈]
等級：吟遊詩人3，術士/法師4
法術成分：言語，姿勢，材料
施法時間：一個標準動作
距離：30英尺
範圍：錐狀爆發
持續時間：1分鐘/每等級
豁免檢定：意志，通過則無效
法術抗力：可
一股無形的、使人因絕望而悲傷至極的錐狀能量在受影響的區域內爆發。每個受影響的生物以下檢定將受到-2減值：攻擊骰，豁免，屬性檢定，技能檢定，和武器傷害骰。
極度絕望可以反制或解除強大希望（good hope）。
材料成分：一小瓶眼淚。-- 極度絕望

Crushing Despair
 Enchantment (Compulsion) [Mind-Affecting]
Level: Brd 3, Sor/Wiz 4
Components: V, S, M
Casting Time: 1 standard action
Range: 30 ft.
Area: Cone-shaped burst
Duration: 1 min./level
Saving Throw: Will negates
Spell Resistance: Yes
An invisible cone of despair causes great sadness in the subjects. Each affected creature takes a -2 penalty on attack rolls, saving throws, ability checks, skill checks, and weapon damage rolls.
Crushing despair counters and dispels good hope.
Material Component: A vial of tears.
]]

pwr_fire_shield_f=[[
你身上環繞著火焰，觸感溫暖。你被正常觸及的近戰攻擊命中時，攻擊者會受到1d6+每施法者等級1點的火焰傷害。基於寒冷的攻擊對你僅造成一半的傷害。若此攻擊可通過反射豁免來減半傷害，則當豁免成功時，你將不受傷害。
]]

pwr_fire_shield_c=[[
你身上環繞著火焰，觸感寒冷。你被正常觸及的近戰攻擊命中時，攻擊者會受到1d6+每施法者等級1點的寒冷傷害。基於火焰的攻擊對你僅造成一半的傷害。若此攻擊可通過反射豁免來減半傷害，則當豁免成功時，你將不受傷害。
]]

pwr_fire_shield_d=[[
]]
--[[
火焰護盾（Fire Shield）
 塑能系[火或寒冷]
等級：火 5，術士/法師 4，太陽 4
法術成分：言語，姿勢，材料/法器
施法時間：一個標準動作
距離：個人
目標：你自己
持續時間：1輪/每等級（可解消）
 這個法術將火焰環繞在你的身上，並且對所有在近戰中攻擊你的生物造成傷害。這種火焰同時還在基於寒冷的攻擊或基於火的攻擊（由你選擇）中保護你。
 任何用它肢體或手持的武器攻擊到你的人依然造成正常傷害，但是同時攻擊者會受到1d6+每施法者等級1點的傷害。該傷害或者是寒冷傷害（如果護盾防護的是基於火的攻擊），或者是火傷害（如果護盾防護的是基於寒冷的攻擊）。如果攻擊者有法術抗力，那麼它可以應用在該效果上。使用較長觸及範圍武器攻擊的生物在攻擊你時不會受到這個傷害。
 當施展該法術時，你看起來是自焚了，但是火焰很薄也很纖細，只能提供正常火把一半的光照（10英尺）。火焰的顏色是隨機的（各有50%機會），如果是寒冷護盾（chill shield），那麼是藍色或綠色，如果是溫暖護盾（warm shield），那麼是紫羅蘭色或藍色。每種功效的特殊能力見下。
溫暖護盾（Warm Shield）：火焰的觸感是溫暖的。基於寒冷的攻擊只能對你造成一半的傷害。如果這類攻擊允許通過反射豁免來減半傷害，那麼當豁免成功時，你將不受傷害。
寒冷護盾（Chill Shield）：火焰的觸感是寒冷的。基於火的攻擊只能對你造成一半的傷害。如果這類攻擊允許通過反射豁免來減半傷害，那麼當豁免成功時，你將不受傷害。
奧術材料成分：溫暖護盾需要一小塊磷；寒冷護盾需要一隻活的螢火蟲或其幼蟲，或者四隻死螢火蟲的尾部。

Fire Shield
 Evocation [Fire or Cold]
Level: Fire 5, Sor/Wiz 4, Sun 4
Components: V, S, M/DF
Casting Time: 1 standard action
Range: Personal
Target: You
Duration: 1 round/level (D)
 This spell wreathes you in flame and causes damage to each creature that attacks you in melee. The flames also protect you from either cold-based or fire-based attacks (your choice).
 Any creature striking you with its body or a handheld weapon deals normal damage, but at the same time the attacker takes 1d6 points of damage +1 point per caster level (maximum +15). This damage is either cold damage (if the shield protects against fire-based attacks) or fire damage (if the shield protects against cold-based attacks). If the attacker has spell resistance, it applies to this effect. Creatures wielding weapons with exceptional reach are not subject to this damage if they attack you.
 When casting this spell, you appear to immolate yourself, but the flames are thin and wispy, giving off light equal to only half the illumination of a normal torch (10 feet). The color of the flames is determined randomly (50% chance of either color) - blue or green if the chill shield is cast, violet or blue if the warm shield is employed. The special powers of each version are as follows.
Warm Shield: The flames are warm to the touch. You take only half damage from cold-based attacks. If such an attack allows a Reflex save for half damage, you take no damage on a successful save.
Chill Shield: The flames are cool to the touch. You take only half damage from fire-based attacks. If such an attack allows a Reflex save for half damage, you take no damage on a successful save.
Arcane Material Component: A bit of phosphorus for the warm shield; a live firefly or glowworm or the tail portions of four dead ones for the chill shield.
]]

pwr_resilient_sphere_d=[[
一個微微發亮的固定球形力場圍繞著你。沒有東西能穿過或傷害到它，除了解除魔法或解離術能摧毀它但不會傷害到你。
]]
--[[
彈力法球（Resilient Sphere）
 塑能系 [力場]
等級：術士/法師 4
法術成分：言語，姿勢，材料
施法時間：1個標準動作
距離：近距（25英尺+5英尺/每2等級）
效果：直徑1英尺/等級的球形，以一個生物為中心
持續時間：1分鐘/等級（可解消）
豁免：反射通過則無效
法術抗力：可
 一個微微發亮的球形力場圍繞著一個生物，前提是此力場的直徑能夠容納該生物。在法術持續時間內此力場始終包圍著它的目標。除了抹消權杖（rod of cancellation）、否定權杖（rod of negation）、解離術（disintegrate）或者目標型解除魔法（dispel magic）之外此力場球不會受到任何型別的傷害。以上效果會摧毀此力場球並且不會傷害到其中的生物。無論向內還是向外，沒有任何東西能夠穿越該力場球，進出都不可以，但其中的生物可以正常呼吸。
 該生物可以行動，但是此力場球不會被它之外或之內的生物以物理方式移動。
材料成分： 一塊半球形的純淨水晶和一塊形狀相配的半球形樹膠。

Resilient Sphere
 Evocation [Force]
Level: Sor/Wiz 4
Components: V, S, M
Casting Time: 1 standard action
Range: Close (25 ft. + 5 ft./2 levels)
Effect: 1-ft.-diameter/level sphere, centered around a creature
Duration: 1 min./level (D)
Saving Throw: Reflex negates
Spell Resistance: Yes
 A globe of shimmering force encloses a creature, provided the creature is small enough to fit within the diameter of the sphere. The sphere contains its subject for the spell's duration. The sphere is not subject to damage of any sort except from a rod of cancellation, a rod of negation, a disintegrate spell, or a targeted dispel magic spell. These effects destroy the sphere without harm to the subject. Nothing can pass through the sphere, inside or out, though the subject can breathe normally.
 The subject may struggle, but the sphere cannot be physically moved either by people outside it or by the struggles of those within.
Material Component: A hemispherical piece of clear crystal and a matching hemispherical piece of gum arabic.
]]

pwr_phantasmal_killer_d=[[
你操弄法術受體的潛意識中的恐懼，將這恐懼塑造成一個其神志中能看見的魅影幻覺：一隻最恐怖的野獸。該幻覺是法術受體所能想象的最可怕的生物。只有法術受體可以看見這個魅影殺手。而你只能看見一個模糊的外形。

法術受體首先可以做一次意志豁免以判斷所見的影像是虛假的。如果此次檢定失敗，則魅影幻覺接觸受體，而受體此時必須做一次強韌豁免。若強韌豁免失敗，則死於恐懼。即使強韌豁免成功，受體也將承受每2級1d6點傷害。
]]
--[[
魅影殺手（Phantasmal Killer）
 幻術系（魅影幻覺） [恐懼，影響心靈]
等級：術士/法師4
法術成分：言語，姿勢
施法時間：1個標準動作
距離：中距（100英尺+10英尺/每等級）
目標：一個活體生物
持續時間：立即
豁免：意志通過則不相信（如果發生互動），之後強韌部分生效；詳見正文
法術抗力：可
你操弄法術受體的潛意識中的恐懼，將這恐懼塑造成一個其神志中能看見的魅影幻覺：一隻最恐怖的野獸。該幻覺是法術受體所能想象的最可怕的生物。只有法術受體可以看見這個魅影殺手。而你只能看見一個模糊的外形。法術受體首先可以做一次意志豁免以判斷所見的影像是虛假的。如果此次檢定失敗，則魅影幻覺接觸受體，而受體此時必須做一次強韌豁免。若強韌豁免失敗，則死於恐懼。即使強韌豁免成功，受體也將承受3d6點傷害。
如果法術受體佩戴了心靈感應頭盔（helm of telepathy），並在遭受魅影殺手攻擊時成功地通過了第一次意志豁免，則野獸可以轉而攻擊你。你必須通過意志檢定，否則你就會變成魅影殺手的目標並要承受它致命的恐懼攻擊。

Phantasmal Killer
 Illusion (Phantasm) [Fear, Mind-Affecting]
Level: Sor/Wiz 4
Components: V, S
Casting Time: 1 standard action
Range: Medium (100 ft. + 10 ft./level)
Target: One living creature
Duration: Instantaneous
Saving Throw: Will disbelief (if interacted with), then Fortitude partial; see text
Spell Resistance: Yes
You create a phantasmal image of the most fearsome creature imaginable to the subject simply by forming the fears of the subject's subconscious mind into something that its conscious mind can visualize: this most horrible beast. Only the spell's subject can see the phantasmal killer. You see only a vague shape. The target first gets a Will save to recognize the image as unreal. If that save fails, the phantasm touches the subject, and the subject must succeed on a Fortitude save or die from fear. Even if the Fortitude save is successful, the subject takes 3d6 points of damage.
If the subject of a phantasmal killer attack succeeds in disbelieving and is wearing a helm of telepathy, the beast can be turned upon you. You must then disbelieve it or become subject to its deadly fear attack.
]]

pwr_weird_d=[[
與魅影殺手，但可影響多個生物。

若受術者通過強韌檢定，仍會受到每6級1d6點傷害，並震懾1輪。受術者的力量還會受到1d4點暫時傷害。
]]
--[[
怪影殺手（Weird）
 幻術系（魅影幻覺）[恐懼，影響心靈]
等級：術士/法師9
目標：任意數量生物，其中任意兩者間距不得超過30英尺
與魅影殺手（phantasmal killer）相同，但可影響多個生物。只有受術者能看到攻擊他們的魅影生物，但你可看到魅影的陰影輪廓。
若受術者通過強韌檢定，仍會受到3d6點傷害，並震懾1輪。受術者的力量還會受到1d4點暫時傷害。

Weird
 Illusion (Phantasm) [Fear, Mind-Affecting]
Level: Sor/Wiz 9
Targets: Any number of creatures, no two of which can be more than 30 ft. apart
This spell functions like phantasmal killer, except it can affect more than one creature. Only the affected creatures see the phantasmal creatures attacking them, though you see the attackers as shadowy shapes.
If a subject's Fortitude save succeeds, it still takes 3d6 points of damage and is stunned for 1 round. The subject also takes 1d4 points of temporary Strength damage.
]]

pwr_sleet_storm_d=[[
降下的冰雨遮蔽了所有視線，並且使得地面結凍。區域內生物需進行敏捷檢定，成功可半速移動，失敗則本輪無法移動，若失敗5以上或者更多則跌倒。
]]
--[[
雪風暴（Sleet Storm）
 咒法系（創造）[寒冷]
等級：德魯伊 3，術士/法師 3
法術成分：言語，姿勢，材料/法器
施法時間：一個標準動作
距離：遠距（400英尺+40英尺/每等級）
區域：柱狀區域（半徑40英尺，高20英尺）
持續時間：1輪/等級
豁免：無
法術抗力：不可
 降下的冰雨遮蔽了所有視線（包括黑暗視覺），並且使得地面結凍。生物若要進入該區域或在區域內移動，需通過DC=10的平衡檢定才能以半速移動。失敗意味著無法移動，若失敗5或者更多則會跌倒（參見平衡技能說明）。
 冰雨會熄滅火炬和小火。
奧術材料成分： 一撮灰塵和幾滴水。

Sleet Storm
 Conjuration (Creation) [Cold]
Level: Drd 3, Sor/Wiz 3
Components: V, S, M/DF
Casting Time: 1 standard action
Range: Long (400 ft. + 40 ft./level)
Area: Cylinder (40-ft. radius, 20 ft. high)
Duration: 1 round/level
Saving Throw: None
Spell Resistance: No
 Driving sleet blocks all sight (even darkvision) within it and causes the ground in the area to be icy. A creature can walk within or through the area of sleet at half normal speed with a DC 10 Balance check. Failure means it can't move in that round, while failure by 5 or more means it falls (see the Balance skill for details).
 The sleet extinguishes torches and small fires.
Arcane Material Component: A pinch of dust and a few drops of water.
]]

pwr_rage2_d=[[
每個受影響的生物在力量和體質上得到+2士氣加值，意志豁免得到+1士氣加值，防禦受到-2減值。

此效果其他部分與野蠻人的狂暴技能相同，除了在狂暴結束時目標生物不會疲乏。
]]
--[[
狂暴術（Rage）
 惑控系（脅迫） [影響心靈]
等級：吟遊詩人 2，術士/法師 3
法術成分：言語，姿勢
施法時間：1個標準動作
距離：中距（100英尺+10英尺/每等級）
目標：每三等級一個自願的活物，任意兩者不得超過30英尺
持續時間： 專注+1輪/等級（可解消）
豁免：無
法術抗力：可 
每個受影響的生物在力量和體質上得到+2士氣加值，意志豁免得到+1士氣加值，AC受到-2減值。此效果其他部分與野蠻人的狂暴技能相同，除了在狂暴結束時目標生物不會疲乏。

Rage
 Enchantment (Compulsion) [Mind-Affecting]
Level: Brd 2, Sor/Wiz 3
Components: V, S
Casting Time: 1 standard action
Range: Medium (100 ft. + 10 ft./level)
Targets: One willing living creature per three levels, no two of which may be more than 30 ft. apart
Duration: Concentration + 1 round/level (D)
Saving Throw: None
Spell Resistance: Yes
Each affected creature gains a +2 morale bonus to Strength and Constitution, a +1 morale bonus on Will saves, and a -2 penalty to AC. The effect is otherwise identical with a barbarian's rage except that the subjects aren't fatigued at the end of the rage.
]]

pwr_displacement_d=[[
受術者出現在其實際位置的大約2英尺遠處。這使得他如同全隱蔽一般，攻擊者有50%的失手率。
]]
--[[
移位術（Displacement）
 幻術系（五官幻覺）
等級：吟遊詩人 3，術士/法師 3
法術成分：言語，材料
施法時間： 一個標準動作
距離：接觸
目標：接觸到的生物
持續時間：1 輪/等級（可解消）
豁免檢定：意志，通過則無效 （無害）
法術抗力：可（無害）
受術者出現在其實際位置的大約2英尺遠處。這使得他如同全隱蔽一般，攻擊者有50%的失手率。但與全隱蔽不同，敵人仍可以受術者為目標。真知術（True seeing）可揭露受術者的真正位置。
材料成分：一小條皮革，捲成環狀。

Displacement
 Illusion (Glamer)
Level: Brd 3, Sor/Wiz 3
Components: V, M
Casting Time: 1 standard action
Range: Touch
Target: Creature touched
Duration: 1 round/level (D)
Saving Throw: Will negates (harmless)
Spell Resistance: Yes (harmless)
The subject of this spell appears to be about 2 feet away from its true location. The creature benefits from a 50% miss chance as if it had total concealment. However, unlike actual total concealment, displacement does not prevent enemies from targeting the creature normally. True seeing reveals its true location.
Material Component: A small strip of leather twisted into a loop.
]]

pwr_ray_of_exhaustion_d=[[
一條黑色的射線從你的手指射出。你必須進行一次成功的遠端接觸攻擊以擊中一個目標。

目標立刻變為力竭狀態。一次成功的強韌豁免意味著該生物只會變為疲乏。

一個已經處於疲乏狀態的生物將變為力竭。

此法術對已力竭的生物無效。

與正常的力竭或疲乏不同，此效果在此法術持續時間結束後終止。
]]
--[[
力竭射線（Ray of Exhaustion）
 死靈系
等級：術士/法師 3
法術成分：言語，姿勢，材料
施法時間：1個標準動作
距離：近距（25英尺+5英尺/每2等級）
效果：射線
持續時間：1分鐘/等級
豁免：強韌通過則部分有效；見正文
法術抗力：可
一條黑色的射線從你的手指射出。你必須進行一次成功的遠端接觸攻擊以擊中一個目標。
在法術持續時間內，目標立刻變為力竭（exhausted）狀態。一次成功的強韌豁免意味著該生物只會變為疲乏（fatigued）。
一個已經處於疲乏狀態的生物將變為力竭。
此法術對於已經力竭的生物沒有效果。與正常的力竭或疲乏不同，此效果在此法術持續時間結束後終止。
材料成分：一滴汗。

Ray of Exhaustion
 Necromancy
Level: Sor/Wiz 3
Components: V, S, M
Casting Time: 1 standard action
Range: Close (25 ft. + 5 ft./2 levels)
Effect: Ray
Duration: 1 min./level
Saving Throw: Fortitude partial; see text
Spell Resistance: Yes
A black ray projects from your pointing finger. You must succeed on a ranged touch attack with the ray to strike a target.
The subject is immediately exhausted for the spell's duration. A successful Fortitude save means the creature is only fatigued.
A character that is already fatigued instead becomes exhausted.
This spell has no effect on a creature that is already exhausted. Unlike normal exhaustion or fatigue, the effect ends as soon as the spell's duration expires.
Material Component: A drop of sweat.
]]

pwr_vampiric_touch_d=[[
你必須成功通過一次近戰接觸攻擊。你的接觸會造成每2級1d6點傷害。你獲得等同於此傷害的暫時生命值。但獲得的生命值不能超過受害者的目前生命值+10點。
]]
--[[
吸血鬼之觸（Vampiric Touch）
 死靈系
等級：術士/法師3
法術成分：言語，姿勢
施法時間：1個標準動作
距離：接觸
目標：被接觸的生物
持續時間：立即/1小時，見下文
豁免：無
法術抗力：可
你必須成功通過一次近戰接觸攻擊。如果成功，那麼你的接觸會造成每兩個施法者等級1d6點傷害（最大10d6）。你獲得等同於此傷害的暫時生命值。但獲得的生命值不能超過受害者的目前生命值+10點，因為這已經足以殺死對方。暫時生命值會在1小時後消失。

Vampiric Touch
 Necromancy
Level: Sor/Wiz 3
Components: V, S
Casting Time: 1 standard action
Range: Touch
Target: Living creature touched
Duration: Instantaneous/1 hour; see text
Saving Throw: None
Spell Resistance: Yes
You must succeed on a melee touch attack. Your touch deals 1d6 points of damage per two caster levels (maximum 10d6). You gain temporary hit points equal to the damage you deal. However, you can't gain more than the subject's current hit points +10, which is enough to kill the subject. The temporary hit points disappear 1 hour later.
]]

pwr_blink_d=[[
你在主物質位面和以太位面之間來回“閃爍”，看起來像在快速隨機地閃入閃出真實世界。

物理攻擊對你有50%機率失手。你的攻擊有20%機率失手，但此時你視為隱形生物，在攻擊上有+2加值，同時忽略目標防禦上的敏捷加值。

單獨目標型法術對你有50%機率失敗。你的法術有20%機率失敗。

區域攻擊和跌落僅對你造成一半傷害。

你能看到並攻擊到靈體生物。

你的移動速度降至四分之三。

你能穿過固體物體，但每穿5英尺你有50%機率被彈出到最近的開放空間，而且每彈過5英尺你會受到1d6點傷害。
]]
--[[
閃現術（Blink）
 變化系
等級：吟遊詩人 3，術士/法師 3
法術成分：言語，姿勢
施法時間：一個標準動作
距離：個人
目標：你自己
持續時間：1輪/每等級（可解消）
 你在主物質位面和以太位面之間來回“閃爍”。看起來你就像在非常快而亂的閃入閃出真實世界。
閃現術帶來以下幾種效果。
 對你的物理攻擊有50%失手率，盲鬥專長對此無效，因為你是靈化狀態，而不僅僅是隱形。如果該攻擊能攻擊到靈體生物，那麼該失手率會降到20%（隱蔽）。如果攻擊者能看到隱形生物，那麼該失手率也會僅有20%。（又能看到又能攻擊到靈體生物的攻擊者沒有失手率。）同樣的，你自己的攻擊也有20%失手率，這是由於有時正在攻擊的時候你正好處在靈化狀態。
 當你處在閃現術下時，任何針對你的單獨目標型法術都有50%機會失敗，除非你的攻擊者可以瞄準隱形靈體生物。由於啟動法術的時候你有可能處在靈界，而在靈界時法術通常不會影響主物質界，因此你自己的法術也有20%的機會失敗。
 當處在閃現術下時，區域攻擊僅會對你造成一半傷害（但是對那些延伸到靈界的法術來說，傷害是全部的）。你攻擊時是作為隱形生物（攻擊投骰上有+2加值），同時忽視目標的所有AC上的敏捷加值。
 在跌落時，你只會受到一半傷害，因為你只是在物化的時候才算跌落。
 當處在閃現術下時，你可以穿過（但無法看透）固體物體。每穿過5英尺固體物質你就有50%機會物質化。如果這種情況發生了，你將會被彈出到最近的開放空間，每這樣穿過5英尺距離，你就會受到1d6點傷害。你只能以四分之三的速度移動（因為在靈界的移動是半速，而你有一半時間在那裡，另一半時間是物質化的）。
 因為你有一半時間在靈界，因此你能看到甚至攻擊到靈體生物。你和靈體生物之間的互動和你與物質生物互動的方式類似。
 靈體生物是不可見的虛體，而且能向任意方向移動，甚至向上和向下。作為虛體生物，你可以穿過固體物品，甚至活的生物。
 靈體生物能看到和聽到主物質界，但是所有事情看上都是灰濛濛的，虛無縹緲的。對主物質界的視覺和聽覺範圍只有60英尺。
 力場效果和防護系效果可以正常影響你。這些效果從主物質界延伸到靈界，但是反過來不可。靈體生物不能攻擊物質化生物，在靈化時你施展的法術只能影響到其它靈化事物。特定的物質化生物或物品有能對靈界攻擊或影響的能力。此時視其它靈化生物或物品為物質化的。

Blink
 Transmutation
Level: Brd 3, Sor/Wiz 3
Components: V, S
Casting Time: 1 standard action
Range: Personal
Target: You
Duration: 1 round/level (D)
 You \"blink\" back and forth between the Material Plane and the Ethereal Plane. You look as though you're winking in and out of reality very quickly and at random.
Blinking has several effects, as follows.
 Physical attacks against you have a 50% miss chance, and the Blind-Fight feat doesn't help opponents, since you're ethereal and not merely invisible. If the attack is capable of striking ethereal creatures, the miss chance is only 20% (for concealment).
 If the attacker can see invisible creatures, the miss chance is also only 20%. (For an attacker who can both see and strike ethereal creatures, there is no miss chance.) Likewise, your own attacks have a 20% miss chance, since you sometimes go ethereal just as you are about to strike.
 Any individually targeted spell has a 50% chance to fail against you while you're blinking unless your attacker can target invisible, ethereal creatures. Your own spells have a 20% chance to activate just as you go ethereal, in which case they typically do not affect the Material Plane.
 While blinking, you take only half damage from area attacks (but full damage from those that extend onto the Ethereal Plane). You strike as an invisible creature (with a +2 bonus on attack rolls), denying your target any Dexterity bonus to AC.
 You take only half damage from falling, since you fall only while you are material.
 While blinking, you can step through (but not see through) solid objects. For each 5 feet of solid material you walk through, there is a 50% chance that you become material. If this occurs, you are shunted off to the nearest open space and take 1d6 points of damage per 5 feet so traveled. You can move at only three-quarters speed (because movement on the Ethereal Plane is at half speed, and you spend about half your time there and half your time material.)
 Since you spend about half your time on the Ethereal Plane, you can see and even attack ethereal creatures. You interact with ethereal creatures roughly the same way you interact with material ones.
 An ethereal creature is invisible, incorporeal, and capable of moving in any direction, even up or down. As an incorporeal creature, you can move through solid objects, including living creatures.
 An ethereal creature can see and hear the Material Plane, but everything looks gray and insubstantial. Sight and hearing on the Material Plane are limited to 60 feet.
 Force effects and abjurations affect you normally. Their effects extend onto the Ethereal Plane from the Material Plane, but not vice versa. An ethereal creature can't attack material creatures, and spells you cast while ethereal affect only other ethereal things. Certain material creatures or objects have attacks or effects that work on the Ethereal Plane. Treat other ethereal creatures and objects as material.
]]

pwr_color_spray_d=[[
]]
--[[
七彩噴射（Color Spray）
 幻術系（心靈幻覺）[影響心靈]
等級：術士/法師1
法術成分：言語，姿勢，材料
施法時間：一個標準動作
距離：15英尺
影響區域：錐狀爆發
持續時間：立即；見說明
豁免檢定：意志，通過則無效
法術抗力：可
 一道斑斕炫目的光芒由你手中呈錐狀散射而出，被覆蓋其中的生物會被震懾，有可能會導致目盲，甚至不省人事昏迷倒地。
 效果因每個生物的HD不同而異。
2HD或以下：該生物會昏迷、目盲和震懾2d4輪，然後目盲和震懾1d4輪，最後被震懾1輪（只有活物才會昏迷倒地）。
3或4HD：該生物會目盲和震懾1d4輪，然後再被震懾1輪。
5HD或以上：該生物被震懾1輪。
 無視覺的生物不受“七彩噴射”影響。
材料成分：一撮染色粉末或沙子，包含紅、黃、藍三種顏色。

Color Spray
 Illusion (Pattern) [Mind-Affecting]
Level: Sor/Wiz 1
Components: V, S, M
Casting Time: 1 standard action
Range: 15 ft.
Area: Cone-shaped burst
Duration: Instantaneous; see text
Saving Throw: Will negates
Spell Resistance: Yes
 A vivid cone of clashing colors springs forth from your hand, causing creatures to become stunned, perhaps also blinded, and possibly knocking them unconscious.
 Each creature within the cone is affected according to its Hit Dice.
2 HD or less: The creature is unconscious, blinded, and stunned for 2d4 rounds, then blinded and stunned for 1d4 rounds, and then stunned for 1 round. (Only living creatures are knocked unconscious.)
3 or 4 HD: The creature is blinded and stunned for 1d4 rounds, then stunned for 1 round.
5 or more HD: The creature is stunned for 1 round.
 Sightless creatures are not affected by color spray.
Material Component: A pinch each of powder or sand that is colored red, yellow, and blue.
]]

pwr_ray_of_enfeeblement_d=[[
一條閃爍的射線從你的手中射出。你必須進行一次成功的遠端接觸攻擊以擊中目標。目標受到1d6+每2級1（最多1d6+5）點力量減值。目標的力量屬性不能降低到1以下。
]]
--[[
衰弱射線（Ray of Enfeeblement）
 死靈系
等級：術士/法師 1
法術成分：言語，姿勢
施法時間：1個標準動作
距離：近距（25英尺+5英尺/每2等級）
效果：射線
持續時間：1分鐘/等級
豁免：無
法術抗力：可
一條閃爍的射線從你的手中射出。你必須進行一次成功的遠端接觸攻擊以擊中目標。目標受到1d6+1每兩施法等級（最多1d6+5）的力量減值。目標的力量屬性不能降低到1以下。

Ray of Enfeeblement
 Necromancy
Level: Sor/Wiz 1
Components: V, S
Casting Time: 1 standard action
Range: Close (25 ft. + 5 ft./2 levels)
Effect: Ray
Duration: 1 min./level
Saving Throw: None
Spell Resistance: Yes
A coruscating ray springs from your hand. You must succeed on a ranged touch attack to strike a target. The subject takes a penalty to Strength equal to 1d6+1 per two caster levels (maximum 1d6+5). The subject's Strength score cannot drop below 1.
]]

pwr_protection_from_arrows_d=[[
受防護的生物獲得抵抗遠端武器的能力。受術者對遠端武器獲得每5級10點傷害減免。當防護總數為每級10點的傷害後，法術耗散。
]]
--[[
防護箭矢（Protection from Arrows）
 防護系
等級：術士/法師 2
法術成分：言語，姿勢，器材
施法時間：1個標準動作
距離：接觸
目標：接觸的生物
持續時間： 1小時/等級或直到耗散
豁免：意志通過則無效（無害）
法術抗力：可（無害）
受防護的生物獲得抵抗遠端武器的能力。受術者對遠端武器獲得10/魔法的傷害減免。（這個法術不會讓你獲得傷害具有類似傷害減免生物的能力。）一旦這個法術防護掉了總數為每施法者等級10點的傷害（最多100點），這個法術耗散。
器材：一小片烏龜或海龜殼。

Protection from Arrows
 Abjuration
Level: Sor/Wiz 2
Components: V, S, F
Casting Time: 1 standard action
Range: Touch
Target: Creature touched
Duration: 1 hour/level or until discharged
Saving Throw: Will negates (harmless)
Spell Resistance: Yes (harmless)
The warded creature gains resistance to ranged weapons. The subject gains damage reduction 10/magic against ranged weapons. (This spell doesn't grant you the ability to damage creatures with similar damage reduction.) Once the spell has prevented a total of 10 points of damage per caster level (maximum 100 points), it is discharged.
Focus: A piece of shell from a tortoise or a turtle.
]]

pwr_blur_d=[[
受術者的輪廓變得模糊不清，不斷的變化和波動。這種失真會讓受術者獲得隱蔽（20%失手率）。

不能看到目標的敵人會忽略此效果（但是和看不見的對手作戰本身會有懲罰）。
]]
--[[
朦朧術（Blur）
 幻術系（五官幻覺）
等級：吟遊詩人 2，術士/法師 2
法術成分：言語
施法時間：一個標準動作
距離：接觸
目標：接觸的生物
持續時間：1分鐘/每等級（可解消）
豁免：意志，通過則無效（無害）
法術抗力：可（無害）
受術者的輪廓變得模糊不清，不斷的變化和波動。這種失真會讓受術者獲得隱蔽（20%失手率）。
識破隱形（see invisibility）不會抵消朦朧術效果，但是真知術（true seeing）可以。
不能看到目標的敵人會忽略法術的效果（但是和看不見的對手作戰本身會有懲罰）。

Blur
 Illusion (Glamer)
Level: Brd 2,Sor/Wiz 2
Components: V
Casting Time: 1 standard action
Range: Touch
Target: Creature touched
Duration: 1 min./level (D)
Saving Throw: Will negates (harmless)
Spell Resistance: Yes (harmless)
The subject's outline appears blurred, shifting and wavering. This distortion grants the subject concealment (20% miss chance).
A see invisibility spell does not counteract the blur effect, but a true seeing spell does.
Opponents that cannot see the subject ignore the spell's effect (though fighting an unseen opponent carries penalties of its own).
]]

pwr_daze_d=[[
目標類人生物的心智被法術擾亂，從而無法行動。等級比你的施法者等級高2級以上的生物不受影響。

眩暈的受術者不算被震懾，因此攻擊者沒有特殊加值。
]]
--[[
暈眩術（Daze）
 惑控系（脅迫）[影響心靈]
等級：吟遊詩人 0，術士/法師 0
法術成分：言語，姿勢, 材料
施法時間： 一個標準動作
距離：近距（25英尺+5英尺/2等級）
目標：一個HD為4或更少的類人生物
持續時間：1輪
豁免檢定：意志，通過則無效
法術抗力：可
生命骰4或更少的類人生物的心智被法術擾亂，從而無法行動。生命骰5或更多的生物不受影響。眩暈的受術者不算被震懾，因此攻擊者沒有特殊加值。
材料成分： 小撮毛線或類似物品。

Daze
 Enchantment (Compulsion) [Mind-Affecting]
Level: Brd 0, Sor/Wiz 0
Components: V, S, M
Casting Time: 1 standard action
Range: Close (25 ft. + 5 ft./2 levels)
Target: One humanoid creature of 4 HD or less
Duration: 1 round
Saving Throw: Will negates
Spell Resistance: Yes
This enchantment clouds the mind of a humanoid creature with 4 or fewer Hit Dice so that it takes no actions. Humanoids of 5 or more HD are not affected. A dazed subject is not stunned, so attackers get no special advantage against it.
Material Component: A pinch of wool or similar substance.
]]

pwr_daze_monster_d=[[
類似暈眩術，但可影響任何種類的活物。
]]
--[[
怪物暈眩術（Daze Monster）
 惑控系（脅迫）[影響心靈]
等級：吟遊詩人 2，術士/法師 2
距離：中距 （100英尺+10英尺/等級）
目標：一個HD為6或更少的活物
此法術作用類似暈眩術，不過怪物暈眩術可影響任何種類的活物。HD 7或更高的生物不受影響。

Daze Monster
 Enchantment (Compulsion) [Mind-Affecting]
Level: Brd 2, Sor/Wiz 2
Range: Medium (100 ft. + 10 ft./level)
Target: One living creature of 6 HD or less
This spell functions like daze, but daze monster can affect any one living creature of any type. Creatures of 7 or more HD are not affected.
]]

pwr_hideous_laughter_d=[[
該法術使目標陷入無法控制的大笑之中。目標笑得歇斯底里，撲倒在地。在狂笑中，目標無法作任何動作，但不視作無助。

智力等於或低於2的生物無法被影響。與施法者生物種類不相同的受術者在豁免檢定上有+4加值，因為幽默“翻譯”起來可不那麼容易。
]]
--[[
狂笑術（Hideous Laughter）
 惑控系（脅迫） [影響心靈]
等級：吟遊詩人 1，術士/法師2
法術成分：言語，姿勢，材料
施法時間：1個標準動作
距離：近距（25英尺+5英尺/每2等級）
目標：1個生物；見下文
持續時間：一輪/等級
豁免：意志，通過無效
法術抗力：可
該法術使目標陷入無法控制的大笑之中。目標笑得歇斯底里，撲倒在地。在狂笑中，目標無法作任何動作，但不視作無助。法術結束後，目標可正常行動。
智力等於或低於2的生物無法被影響。與施法者生物種類不相同的受術者在豁免檢定上有+4加值，因為幽默“翻譯”起來可不那麼容易。
法術材料：扔向目標的小甜餅和空中揮舞的羽毛。

Hideous Laughter
 Enchantment (Compulsion) [Mind-Affecting]
Level: Brd 1, Sor/Wiz 2
Components: V, S, M
Casting Time: 1 standard action
Range: Close (25 ft. + 5 ft./2 levels)
Target: One creature; see text
Duration: 1 round/level
Saving Throw: Will negates
Spell Resistance: Yes
This spell afflicts the subject with uncontrollable laughter. It collapses into gales of manic laughter, falling prone. The subject can take no actions while laughing, but is not considered helpless. After the spell ends, it can act normally.
A creature with an Intelligence score of 2 or lower is not affected. A creature whose type is different from the caster's receives a +4 bonus on its saving throw, because humor doesn't "translate" well.
Material Component: Tiny tarts that are thrown at the target and a feather that is waved in the air.
]]

pwr_touch_of_idiocy_d=[[
你通過接觸降低目標的智慧。通過成功的近戰接觸攻擊檢定，你能對目標的智力、感知和魅力造成1d6點減值。這種減值不會讓其中任何一項減到低於1。

如果目標的智力值低於施展某等級的法術的最低要求，他將不能施展那些法術。
]]
--[[
愚者之觸（Touch of Idiocy）
 惑控系（脅迫）[影響心靈]
等級：術士/法師2
法術成分：言語，姿勢
施法時間：1個標準動作
距離：接觸
目標：被接觸的活物
持續時間：10分鐘/等級
豁免：無
法術抗力：可
你通過接觸降低目標的智慧。通過成功的近戰接觸攻擊檢定，你能對目標的智力、感知和魅力造成1d6點減值。這種減值不會讓其中任何一項減到低於1。
如果目標的智力值低於施展某等級的法術的最低要求，他將不能施展那些法術。

Touch of Idiocy
 Enchantment (Compulsion) [Mind-Affecting]
Level: Sor/Wiz 2
Components: V, S
Casting Time: 1 standard action
Range: Touch
Target: Living creature touched
Duration: 10 min./level
Saving Throw: No
Spell Resistance: Yes
With a touch, you reduce the target's mental faculties. Your successful melee touch attack applies a 1d6 penalty to the target's Intelligence, Wisdom, and Charisma scores. This penalty can't reduce any of these scores below 1.
This spell's effect may make it impossible for the target to cast some or all of its spells, if the requisite ability score drops below the minimum required to cast spells of that level.
]]

pwr_mirror_image_d=[[
你的身旁出現數個幻象分身，使敵人很難確定到底該攻擊哪個目標。

敵人攻擊你或對你施法時，須隨機擲骰判斷選定的目標是真身還是鏡影。

任何成功的攻擊都會摧毀分身。分身的AC為10+你的體型調整值+你的敏捷調整值。

敵人必須能看到鏡影才會被愚弄。如果你隱形或攻擊者閉上眼睛，鏡影就無效。
]]
--[[
鏡影術（Mirror Image）
 幻術系（虛假幻覺）
等級：吟遊詩人2，術士/法師2
法術成分：言語，姿勢
施法時間：1個標準動作
距離：個人；見說明
目標：你自己
持續時間：1分鐘/施法者每等級（可解消）
 你的身旁出現數個幻象分身，使敵人很難確定到底該攻擊哪個目標。這些分身會一直待在你周圍，被擊中時即消失。
鏡影術會造出1d4個分身，每施法者等級可以再增加一個（總數最多八個）。這些分身和你是獨立分開的，但是又和你靠在一起。每個分身都在其它至少一個分身或你的5英尺之內。你可以進入或穿過這些映象。當你和你的分身分離時，觀察者無法以視覺或聽覺來判斷到底哪個是你的真身。分身與分身之間也可以彼此互相穿越。所有的分身都會模擬你的行為，比如你施法時分身也會做出施法動作，你喝藥水時分身也會喝藥水，你飄在空中分身也會飄起來等等。
 敵人若要攻擊你或對你施法，必須在本體和數個分身中選擇一個作為目標。一般都是隨機擲骰判斷選定的目標是真身還是映象。任何成功的攻擊都會摧毀分身。分身的AC為10+你的體型調整值+你的敏捷調整值。被區域型法術攻擊時，分身也會做出應有的反應（如被火球術（fireball）擊中時，看起來也會被燒傷或燒死）。
 當你移動時，你可以任意跟所有的分身合體再分開，這將使已經搞清楚你實際位置所在的敵人再次被迷惑。
 敵人必須要看到鏡影才會被迷惑。如果你隱形或攻擊者閉上眼睛，法術就沒有效果。（無法視物將受到如同目盲般的帶來的懲罰。）

Mirror Image
 Illusion (Figment)
Level: Brd 2, Sor/Wiz 2
Components: V, S
Casting Time: 1 standard action
Range: Personal; see text
Target: You
Duration: 1 min./level (D)
 Several illusory duplicates of you pop into being, making it difficult for enemies to know which target to attack. The figments stay near you and disappear when struck.
Mirror image creates 1d4 images plus one image per three caster levels (maximum eight images total). These figments separate from you and remain in a cluster, each within 5 feet of at least one other figment or you. You can move into and through a mirror image. When you and the mirror image separate, observers can't use vision or hearing to tell which one is you and which the image. The figments may also move through each other. The figments mimic your actions, pretending to cast spells when you cast a spell, drink potions when you drink a potion, levitate when you levitate, and so on.
 Enemies attempting to attack you or cast spells at you must select from among indistinguishable targets. Generally, roll randomly to see whether the selected target is real or a figment. Any successful attack against an image destroys it. An image's AC is 10 + your size modifier + your Dex modifier. Figments seem to react normally to area spells (such as looking like they're burned or dead after being hit by a fireball).
 While moving, you can merge with and split off from figments so that enemies who have learned which image is real are again confounded.
 An attacker must be able to see the images to be fooled. If you are invisible or an attacker shuts his or her eyes, the spell has no effect. (Being unable to see carries the same penalties as being blinded.)
]]

pwr_command_undead_d=[[
]]
--[[
命令死靈（Command Undead）
 死靈系
等級：術士/法師2
法術成分：言語，姿勢，材料
施法時間：一個標準動作
距離：近距（25英尺+5英尺/每2等級）
目標：一個不死生物
持續時間：1天/每等級
豁免檢定：意志豁免；見說明
法術抗力：可
 此法術允許你部分控制一個不死生物。受影響的不死生物為智慧生物時，它將認為你的言行是最有利於它的（它對你持友善態度）。它在法術結束前不會攻擊你。你可以嘗試讓它去做事，但你必須通過魅力檢定對抗才能讓它去做本不願意的事。（不可再次嘗試）。被控制的智慧不死生物決不可能接受自殺或者作明顯對自己有傷害的命令，但它或許會相信一些非常危險的事情是值得去做的。
 非智慧生物的不死生物不能做豁免檢定。當你控制一個無心智的不死生物，你只能對它下達一些最基本的命令，例如“來”，“去”，“ 戰鬥”，“停下”等等。非智慧不死生物不能反抗例如自殺或明顯傷害自己的命令。
 任何來自於你或者你明顯的同盟者對被控制的不死生物（不管是否是有智慧）的威脅都將破壞該法術。
 你的命令並非心靈感應。這個不死生物必須聽到你的命令。
材料成分：一片生肉和一塊骨頭碎片。

Command Undead
 Necromancy
Level: Sor/Wiz 2
Components: V, S, M
Casting Time: 1 standard action
Range: Close (25 ft. + 5 ft./2 levels)
Targets: One undead creature
Duration: One day/level
Saving Throw: Will negates; see text
Spell Resistance: Yes
 This spell allows you some degree of control over an undead creature. Assuming the subject is intelligent, it perceives your words and actions in the most favorable way (treat its attitude as friendly). It will not attack you while the spell lasts. You can try to give the subject orders, but you must win an opposed Charisma check to convince it to do anything it wouldn't ordinarily do. (Retries are not allowed.) An intelligent commanded undead never obeys suicidal or obviously harmful orders, but it might be convinced that something very dangerous is worth doing.
 A nonintelligent undead creature gets no saving throw against this spell. When you control a mindless being, you can communicate only basic commands, such as "come here," "go there," "fight," "stand still," and so on. Nonintelligent undead won't resist suicidal or obviously harmful orders.
 Any act by you or your apparent allies that threatens the commanded undead (regardless of its Intelligence) breaks the spell.
 Your commands are not telepathic. The undead creature must be able to hear you.
Material Component: A shred of raw meat and a splinter of bone.
]]

pwr_ghoul_touch_c=[[
生物被麻痺，且散發出一股腐肉的惡臭。這股惡臭會導致10英尺擴散範圍內的所有活物（除了此法術的施法者）都進入噁心狀態（強韌通過則無效）。法術中和毒性可將此噁心狀態移除，免疫毒素的生物不受此惡臭影響。
]]

pwr_ghoul_touch_d=[[
你身上浸滿了負能量，通過一個成功的近戰接觸攻擊，你能麻痺一個活體類人生物。

另外，被麻痺的生物散發出一股腐肉的惡臭，這股惡臭會導致10英尺擴散範圍內的所有活物（除了你）都進入噁心狀態（強韌通過則無效）。法術中和毒性可將此噁心狀態移除，免疫毒素的生物不受此惡臭影響。
]]
--[[
食屍鬼之觸（Ghoul Touch）
 死靈系
等級：術士/法師 2
法術成分：言語，姿勢，材料
施法時間：一個標準動作
距離：接觸
目標：接觸的活著的類人生物
持續時間：1d6+2輪
豁免：強韌，通過則無效
法術抗力：可

你身上浸滿了負能量，通過一個成功的近戰接觸攻擊，這個法術能讓你在法術持續時間內麻痺一個活著的類人生物。

另外，被麻痺的生物散發出一股腐肉的惡臭，這股惡臭會導致10英尺擴散範圍內的所有活物（除了你）都進入噁心狀態（強韌通過則無效）。法術中和毒性（neutralize poison）可以將處在噁心狀態的生物身上的此效果移除，免疫毒素的生物不受此惡臭影響。

材料成分：一小片從食屍鬼穿著衣物上取下的布片，或者一撮食屍鬼巢穴的泥土。

Ghoul Touch
 Necromancy
Level: Sor/Wiz 2
Components: V, S, M
Casting Time: 1 standard action
Range: Touch
Target: Living humanoid touched
Duration: 1d6+2 rounds
Saving Throw: Fortitude negates
Spell Resistance: Yes

Imbuing you with negative energy, this spell allows you to paralyze a single living humanoid for the duration of the spell with a successful melee touch attack.

Additionally, the paralyzed subject exudes a carrion stench that causes all living creatures (except you) in a 10-foot-radius spread to become sickened (Fortitude negates). A neutralize poison spell removes the effect from a sickened creature, and creatures immune to poison are unaffected by the stench.

Material Component: A small scrap of cloth taken from clothing worn by a ghoul, or a pinch of earth from a ghoul's lair.
]]

pwr_burning_hands_d=[[
錐形灼熱火焰從你的指尖噴出。火焰區域內的所有生物受到每級1d4點火焰傷害。
]]
--[[
燃燒之手（Burning Hands）
 塑能系[火]
等級：火 1, 術士/法師 1
法術成分：言語，姿勢
施法時間：一個標準動作
距離：15英尺
區域：錐形爆發
持續時間：立即
豁免：反射減半
法術抗力：可
錐形灼熱火焰從你的指尖噴出。所有在火焰區域內的生物都要受到每等級1d4的火傷害（最多5d4）。如果火焰接觸到可燃材料，它們會燒起來。人物可以以一個整輪動作撲滅燃燒的物品。

Burning Hands
 Evocation [Fire]
Level: Fire 1, Sor/Wiz 1
Components: V, S
Casting Time: 1 standard action
Range: 15 ft.
Area: Cone-shaped burst
Duration: Instantaneous
Saving Throw: Reflex half
Spell Resistance: Yes
A cone of searing flame shoots from your fingertips. Any creature in the area of the flames takes 1d4 points of fire damage per caster level (maximum 5d4). Flammable materials burn if the flames touch them. A character can extinguish burning items as a full-round action.
]]

pwr_chill_touch_d=[[
你的一隻手散發出幽藍的能量，它的觸控會摧毀活物的生命力。成功的近戰接觸攻擊造成每級1d6點負能量傷害。如果未能通過強韌檢定則額外造成1點力量傷害。

被你接觸到的不死生物不會受到任何一種傷害，但它需要進行意志豁免檢定，失敗則如同進入恐慌狀態並四散逃走1d4+每級1輪。
]]
--[[
寒冷之觸（Chill Touch）
 死靈系
等級：術士/法師1
法術成分：言語、姿勢
施法時間：一個標準動作
距離：接觸
目標：1個接觸到的生物/每等級
持續時間：立即
豁免檢定：強韌通過則部分有效，或意志通過則無效；見說明
法術抗力：可
你的一隻手散發出幽藍的能量，它的觸控會摧毀活物的生命力。每一下接觸會造成1d6點的負能量傷害。如果未能通過強韌檢定則額外造成1點力量屬性傷害。該法術使用近戰接觸攻擊，能攻擊次數等同施法者等級。
被你接觸到的不死生物不會受到任何一種傷害，但它需要進行意志豁免檢定，失敗則四散逃走持續1d4輪，額外加上每施法者等級1輪，並使他們處於恐慌狀態（panicked）。

Chill Touch
 Necromancy
Level: Sor/Wiz 1
Components: V, S
Casting Time: 1 standard action
Range: Touch
Targets: Creature or creatures touched (up to one/level)
Duration: Instantaneous
Saving Throw: Fortitude partial or Will negates; see text
Spell Resistance: Yes
A touch from your hand, which glows with blue energy, disrupts the life force of living creatures. Each touch channels negative energy that deals 1d6 points of damage. The touched creature also takes 1 point of Strength damage unless it makes a successful Fortitude saving throw. You can use this melee touch attack up to one time per level.
An undead creature you touch takes no damage of either sort, but it must make a successful Will saving throw or flee as if panicked for 1d4 rounds +1 round per caster level.
]]

pwr_shocking_grasp_d=[[
若近戰接觸攻擊檢定成功，則你可造成每級1d6點電擊傷害。對穿著金屬盔甲（或目標本身由金屬製成，或攜帶大量金屬物品）的敵人攻擊有+3加值。
]]
--[[
電爪（Shocking Grasp）
 塑能系[電擊]
等級：術士/法師 1
法術成分：言語，姿勢
施法時間：一個標準動作
距離：接觸
目標： 被接觸的生物或物品
持續時間：立即
豁免：無
法術抗力：可
若近戰接觸攻擊檢定成功，則你可造成每施法者等級1d6的電擊傷害（最多5d6點）。對穿著金屬盔甲（或由金屬製成，或攜帶大量金屬物品）的敵人攻擊有+3加值。

Shocking Grasp
 Evocation [Electricity]
Level: Sor/Wiz 1
Components: V, S
Casting Time: 1 standard action
Range: Touch
Target: Creature or object touched
Duration: Instantaneous
Saving Throw: None
Spell Resistance: Yes
Your successful melee touch attack deals 1d6 points of electricity damage per caster level (maximum 5d6). When delivering the jolt, you gain a +3 bonus on attack rolls if the opponent is wearing metal armor (or made out of metal, carrying a lot of metal, or the like).
]]

pwr_scorching_ray_d=[[
你用熾熱的射線衝擊你的敵人。3級時1道射線，7級2道，11級達到最多3道射線。每道射線都需要一個遠端接觸攻擊來命中並造成4d6點火焰傷害（12級後為每2級1d6）。
]]
--[[
灼熱射線（Scorching Ray）
 塑能系[火]
等級：術士/法師 2
法術成分：言語，姿勢
施法時間：一個標準動作
距離：近距（25英尺+5英尺/每2等級）
效果：一或多條射線
持續時間：立即
豁免：無
法術抗力：可
你用熾熱的射線衝擊你的敵人。你可以發射一道射線，比3級每多四個等級還可以再加一道射線（11級時達到最多三道射線）。每道射線都需要一個遠端接觸攻擊來命中，並且造成4d6的火傷害。
射線可以對準同一個目標發射，也可以瞄準不同目標，但是所有射線都必須瞄準彼此處在30尺之內的目標，而且必須同時發射。

Scorching Ray
 Evocation [Fire]
Level: Sor/Wiz 2
Components: V, S
Casting Time: 1 standard action
Range: Close (25 ft. + 5 ft./2 levels)
Effect: One or more rays
Duration: Instantaneous
Saving Throw: None
Spell Resistance: Yes
You blast your enemies with fiery rays. You may fire one ray, plus one additional ray for every four levels beyond 3rd (to a maximum of three rays at 11th level). Each ray requires a ranged touch attack to hit and deals 4d6 points of fire damage.
The rays may be fired at the same or different targets, but all bolts must be aimed at targets within 30 feet of each other and fired simultaneously.
]]

pwr_shout_d=[[
你發出震耳欲聾的咆哮，聲音所及之處生物均被震聾且受到傷害。

影響區域內的生物耳聾2d6輪，並受到每3級2d6點音波傷害。豁免成功則不會耳聾且傷害減半。
]]
--[[
咆哮術（Shout）
 塑能系 [音波]
等級：吟遊詩人 4，術士/法師 4
法術成分：言語
施法時間：一個標準動作
距離：30 英尺
區域：錐狀爆發區域
持續時間：立即
豁免：強韌，通過則部分生效；或反射，通過則無效（物體）；見正文
法術抗力：可（物體）
你發出震耳欲聾的咆哮，聲音所及之處生物均被震聾且受到傷害。影響區域內的生物耳聾2d6輪，並受到5d6點音波傷害。豁免成功則不會耳聾且傷害減半。暴露的易碎物、晶質物或晶體生物受到每施法者等級1d6音波傷害（最多15d6）。晶體生物可通過強韌豁免以使傷害減半，手持易碎物品的生物可通過反射檢定來使其不受傷害。
咆哮術無法穿透沉默術（silence）。

Shout
 Evocation [Sonic]
Level: Brd 4, Sor/Wiz 4
Components: V
Casting Time: 1 standard action
Range: 30 ft.
Area: Cone-shaped burst
Duration: Instantaneous
Saving Throw: Fortitude partial or Reflex negates (object); see text
Spell Resistance: Yes (object)
You emit an ear-splitting yell that deafens and damages creatures in its path. Any creature within the area is deafened for 2d6 rounds and takes 5d6 points of sonic damage. A successful save negates the deafness and reduces the damage by half. Any exposed brittle or crystalline object or crystalline creature takes 1d6 points of sonic damage per caster level (maximum 15d6). An affected creature is allowed a Fortitude save to reduce the damage by half, and a creature holding fragile objects can negate damage to them with a successful Reflex save.
A shout spell cannot penetrate a silence spell.
]]

pwr_greater_shout_d=[[
類似咆哮術，不過此法術可造成每3級2d6點音波傷害，外加震懾1輪，耳聾4d6輪。強韌豁免成功則不會被震懾，且耳聾時間和所受傷害減半。
]]
--[[
高等咆哮術（Shout, Greater）
 塑能系 [音波]
等級：吟遊詩人 6，術士/法師 8
法術成分：言語，姿勢，器材
距離：60 ft.
豁免：強韌，通過則部分生效；或反射，通過則無效（物體）；見正文
與咆哮術相同，不過此法術可造成10d6點音波傷害（對暴露的易碎物、晶質物或晶體生物造成每施法者等級1d6音波傷害，最多20d6）。它還會使生物震懾1輪，耳聾4d6輪。強韌豁免成功則生物不會被震懾，且耳聾時間和所受傷害減半。手持易碎物品的生物可通過反射檢定以使其免受傷害。
奧術 器材成分：一支金屬或象牙小號角。

Shout, Greater
 Evocation [Sonic]
Level: Brd 6, Sor/Wiz 8
Components: V, S, F
Range: 60 ft.
Saving Throw: Fortitude partial or Reflex negates (object); see text
This spell functions like shout, except that the cone deals 10d6 points of sonic damage (or 1d6 points of sonic damage per caster level, maximum 20d6, against exposed brittle or crystalline objects or crystalline creatures). It also causes creatures to be stunned for 1 round and deafened for 4d6 rounds. A creature in the area of the cone can negate the stunning and halve both the damage and the duration of the deafness with a successful Fortitude save. A creature holding vulnerable objects can attempt a Reflex save to negate the damage to those objects.
Arcane Focus: A small metal or ivory horn.
]]

pwr_cone_of_cold_d=[[
寒冰錐製造出一片極度嚴寒的區域，它從你掌心出現，延伸出一片錐狀區域。它耗乾熱量，造成每級1d6點寒冷傷害。
]]
--[[
寒冰錐（Cone of Cold）
 塑能系[寒冷]
