法術抗力：可
寒冰錐製造出一片極度嚴寒的區域，它從你掌心出現，延伸出一片錐狀區域。它耗乾熱量，造成每施法者等級1d6的寒冷傷害（最高15d6）。
奧術材料：一個非常小的水晶或玻璃錐。

Cone of Cold
 Evocation [Cold]
