pwr_spiritual_weapon_d=[[
]]
--[[
靈能武器（Spiritual Weapon）
 塑能系[力場]
等級：牧師 2，戰爭 2
法術成分：言語，姿勢，法器
施法時間：一個標準動作
距離：中距（100英尺+10英尺/每等級）
效果：力場魔法武器
持續時間： 1輪/等級（可解消）
豁免：無
法術抗力：可
 你可以造出一把由純力場構成的武器，並指揮它來攻擊遠處敵人，該武器每一擊可造成1d8點力場傷害，每三級施法者等級可多造成一點傷害（最多為15級時的+5）。武器形狀是你信奉神祉的偏好武器，或者是對你意義重大，有某種精神象徵的武器（見下文），它的重擊範圍與重擊倍數與和它同形體的真實武器相同。從施法那輪開始，該武器即會攻擊你指定的敵人，此後每一輪都在你行動之後進行攻擊。它用你的基本攻擊加值（因此有可能讓它在後面的輪次內每輪進行多次攻擊）加上施法者的感知調整值作為它的攻擊加值。它的攻擊視為法術而非武器，因此它可以對有傷害減免的生物造成傷害。作為力場效果，它攻擊虛體生物時不會有失手率。該武器只能從你的方向發動攻擊。它不能獲得夾擊加值，也不能幫助隊友夾擊。你的專長和戰鬥行動對它沒有影響。如果武器離開法術的有效距離，或離開你的視野，或你不再指揮它，它便會回到你身邊盤旋待命。
 第一輪之後的每一輪裡，你都可以用一個移動動作來指揮該武器攻擊另一個目標。如果你不這麼做，它會繼續攻擊前一輪的目標。改變目標的那一輪，該武器只能攻擊一次。之後若不改變目標，且你的基本攻擊加值允許，它可以進行多重攻擊。即便造出的靈能武器是遠端武器，武器的攻擊範圍仍舊受法術範圍的限制，而不是原來武器的攻擊範圍，並且改變目標仍舊是個移動動作。
 物理攻擊無法攻擊或損傷靈能武器，但是解除魔法（dispel magic），解離術（disintegrate），毀滅黑洞（sphere of annihilation），抹消權杖（rod of cancellation）都會影響它。靈能武器的接觸AC為12（10+超小型物體的體型調整值）。
 若受攻擊生物有法術抗力，你需要在靈能武器第一次攻擊它時作施法者等級檢定（1d20+施法者等級）來對抗對方的法術抗力。若這個武器被成功的抵抗了，則法術解消。反之則在法術持續時間內，武器對該生物能發揮全部正常效果。
 你造出的武器通常都是你信奉神祗的偏好武器。無神牧師根據其陣營獲得武器。中立無神牧師可以造出任何陣營的武器，但他當時的行為必須符合該陣營性質。各陣營的武器如下：
混亂：戰斧
邪惡：輕型鏈枷
善良：戰錘
守序：長劍

Spiritual Weapon
 Evocation [Force]
Level: Clr 2, War 2
Components: V, S, DF
Casting Time: 1 standard action
Range: Medium (100 ft. + 10 ft./level)
Effect: Magic weapon of force
Duration: 1 round/level (D)
Saving Throw: None
Spell Resistance: Yes
 A weapon made of pure force springs into existence and attacks opponents at a distance, as you direct it, dealing 1d8 force damage per hit, +1 point per three caster levels (maximum +5 at 15th level). The weapon takes the shape of a weapon favored by your deity or a weapon with some spiritual significance or symbolism to you (see below) and has the same threat range and critical multipliers as a real weapon of its form. It strikes the opponent you designate, starting with one attack in the round the spell is cast and continuing each round thereafter on your turn. It uses your base attack bonus (possibly allowing it multiple attacks per round in subsequent rounds) plus your Wisdom modifier as its attack bonus. It strikes as a spell, not as a weapon, so, for example, it can damage creatures that have damage reduction. As a force effect, it can strike incorporeal creatures without the normal miss chance associated with incorporeality. The weapon always strikes from your direction. It does not get a flanking bonus or help a combatant get one. Your feats or combat actions do not affect the weapon. If the weapon goes beyond the spell range, if it goes out of your sight, or if you are not directing it, the weapon returns to you and hovers.
 Each round after the first, you can use a move action to redirect the weapon to a new target. If you do not, the weapon continues to attack the previous round's target. On any round that the weapon switches targets, it gets one attack. Subsequent rounds of attacking that target allow the weapon to make multiple attacks if your base attack bonus would allow it to. Even if the spiritual weapon is a ranged weapon, use the spell's range, not the weapon's normal range increment, and switching targets still is a move action.
 A spiritual weapon cannot be attacked or harmed by physical attacks, but dispel magic, disintegrate, a sphere of annihilation, or a rod of cancellation affects it. A spiritual weapon's AC against touch attacks is 12 (10 + size bonus for Tiny object).
 If an attacked creature has spell resistance, you make a caster level check (1d20 + caster level) against that spell resistance the first time the spiritual weapon strikes it. If the weapon is successfully resisted, the spell is dispelled. If not, the weapon has its normal full effect on that creature for the duration of the spell.
 The weapon that you get is often a force replica of your deity's own personal weapon. A cleric without a deity gets a weapon based on his alignment. A neutral cleric without a deity can create a spiritual weapon of any alignment, provided he is acting at least generally in accord with that alignment at the time. The weapons associated with each alignment are as follows.
Chaos: Battleaxe
Evil: Light flail
Good: Warhammer
Law: Longsword
]]

pwr_resist_energy_d=[[
對5種能量類別之一的傷害，此防護法術給予一個生物一定的有限保護，能量類別由你選擇：強酸、寒冷、電擊、火焰或音波。

該目標生物得到對於選定能量形式的10點能量抗性，意味著每次它受到該類能量傷害（無論是來源於自然還是魔法）時，該生物的生命值受到的傷害降低10點。此能量抗性在7級時增加到20點，11級時30點，以此類推。

抵抗能量傷害只吸收能量傷害。目標仍然會受到其他負面效果的影響。

注意：防護能量傷害會覆蓋（而非疊加）抵抗能量傷害。如果角色同時被防護能量傷害和抵抗能量傷害所防護，則防護能量傷害會先吸收傷害，直到其能力耗盡。
]]
--[[
抵抗能量傷害（Resist Energy）
 防護系
等級：牧師 2，德魯伊 2，火 3，聖武士 2，巡林客 1，術士/法師 2
法術成分：言語，姿勢，法器
施法時間：1個標準動作
距離：接觸
目標：接觸的生物
持續時間： 10分鐘/等級
豁免：強韌通過則無效（無害）
法術抗力：可（無害）
對以下五種能量類別之一的傷害，此防護法術給予一個生物一定的有限保護，能量類別由你選擇：強酸、寒冷、電擊、火焰或音波。該目標生物得到對於選定能量形式的10點能量抗性，意味著每次它受到該類能量傷害（無論是來源於自然還是魔法）時，該生物的生命值受到的傷害降低10點。此能量抗性在第7級時增加為20點，第11級時達到最高，為30點。此法術也會保護目標生物的裝備。
抵抗能量傷害只吸收能量傷害。目標仍然會受到其他負面效果的影響。
注意：防護能量傷害覆蓋（而非疊加）了抵抗能量傷害（resist energy）。如果一個人被防護能量傷害和抵抗能量傷害所同時防護，那麼防護能量傷害會吸收傷害，直到它的能力消失。

Resist Energy
 Abjuration
Level: Clr 2, Drd 2, Fire 3, Pal 2, Rgr 1, Sor/Wiz 2
Components: V, S, DF
Casting Time: 1 standard action
Range: Touch
Target: Creature touched
Duration: 10 min./level
Saving Throw: Fortitude negates (harmless)
Spell Resistance: Yes (harmless)
This abjuration grants a creature limited protection from damage of whichever one of five energy types you select: acid, cold, electricity, fire, or sonic. The subject gains energy resistance 10 against the energy type chosen, meaning that each time the creature is subjected to such damage (whether from a natural or magical source), that damage is reduced by 10 points before being applied to the creature's hit points. The value of the energy resistance granted increases to 20 points at 7th level and to a maximum of 30 points at 11th level. The spell protects the recipient's equipment as well.
Resist energy absorbs only damage. The subject could still suffer unfortunate side effects.
Note: Resist energy overlaps (and does not stack with) protection from energy. If a character is warded by protection from energy and resist energy, the protection spell absorbs damage until its power is exhausted.
]]

pwr_protection_from_energy_d=[[
防護能量傷害能提供對一種能量暫時的免疫力，能量型別由你在施法時指定（強酸，寒冷，電擊，火焰，或音波）。當該法術吸收了每級12點能量傷害時，法術耗散。

注意：防護能量傷害會覆蓋（而非疊加）抵抗能量傷害。如果角色同時被防護能量傷害和抵抗能量傷害所防護，則防護能量傷害會先吸收傷害，直到其能力耗盡。
]]
--[[
防護能量傷害（Protection from Energy）
 防護系
等級：牧師 3，德魯伊3，機運 3，保護 3，巡林客2，術士/法師 3
法術成分：言語，姿勢，法器
施法時間：1個標準動作
距離：接觸
目標：接觸的生物
持續時間： 10分鐘/等級或直到耗散
豁免：強韌通過則無效（無害）
法術抗力：可（無害）
防護能量傷害能提供暫時的對一種能量的免疫力，能量型別由你在施法時指定（強酸，寒冷，電擊，火焰，或音波）。當這個法術吸收了每施法者等級12點的能量傷害時（在10級時達到最多120點），法術耗散。
注意：防護能量傷害覆蓋（而非疊加）了抵抗能量傷害（resist energy）。如果一個人被防護能量傷害和抵抗能量傷害所同時防護，那麼防護能量傷害會吸收傷害，直到它的能力消失。

Protection from Energy
 Abjuration
Level: Clr 3, Drd 3, Luck 3, Protection 3, Rgr 2, Sor/Wiz 3
Components: V, S, DF
Casting Time: 1 standard action
Range: Touch
Target: Creature touched
Duration: 10 min./level or until discharged
Saving Throw: Fortitude negates (harmless)
Spell Resistance: Yes (harmless)
Protection from energy grants temporary immunity to the type of energy you specify when you cast it (acid, cold, electricity, fire, or sonic). When the spell absorbs 12 points per caster level of energy damage (to a maximum of 120 points at 10th level), it is discharged.
Note: Protection from energy overlaps (and does not stack with) resist energy. If a character is warded by protection from energy and resist energy, the protection spell absorbs damage until its power is exhausted.
]]

pwr_contagion_d=[[
此法術可傳染從下表所選一種疾病，並立即發病造成傷害（無潛伏期）。

疾病	DC	傷害
==================
失明症	16	1d4力量（可能致盲，見後文）
紅腫症	15	1d6力量
顫慄症	13	1d8敏捷
腐熱症	12	1d3敏捷，1d3體質
膠質症	14	1d4體質
腦熱症	12	1d4智力
失心瘋	16	1d6感知

失明症：每當目標因失明症損失2點或更多的力量時，它必須額外做一次強韌豁免檢定（對抗失明症DC），失敗則永久目盲。

使用此法術時，目標需進行一次強韌豁免檢定（對抗法術DC）。

如果成功，疾病不產生效果--目標的免疫系統擊退了傳染病。

如果失敗，目標將染病且立即遭受一次傷害。之後每5輪它都要進行一次成功的強韌豁免檢定（對抗表中疾病DC）來避免再次傷害。

連續2次豁免檢定成功表明它擊敗了疾病並恢復健康，不再受傷害。
]]
--[[
疫病術（Contagion）
死靈系[邪惡]
等級：牧師3，破壞3，德魯伊3，術士/法師4
法術成分：言語，姿勢
施法時間：一個標準動作
距離：接觸
目標：接觸到的活物
持續時間：立即
豁免檢定：強韌，通過則無效
法術抗力：可

此法術可以傳染下列表格中的疾病，並立即發病（無潛伏期）。

下列註明為病發時的豁免檢定DC（第一次豁免判定使用對抗疫病術的正常豁免DC）。
疾病	DC	傷害
失明症（Blinding sickness）	16	1d4 力量 1
失心瘋（Cackle fever）		16	1d6 感知
腐熱症（Filth fever）		12	1d3 敏捷和1d3體質
腦熱症（Mindfire）			12	1d4 智力
紅腫症（Red ache）			15	1d6 力量
顫慄症（Shakes）			13	1d8 敏捷
噁心症（Slimy doom）		14	1d4 體質
1 每當受害者因為失明症損失2點或更多的力量時，他或她必須作另一次的強韌豁免檢定（用失明症豁免DC），失敗則永久目盲。-- 用感染疾病時的豁免檢定

Contagion
Necromancy [Evil]
Level: Clr 3, Destruction 3, Drd 3, Sor/Wiz 4
Components: V, S
Casting Time: 1 standard action
Range: Touch
Target: Living creature touched
Duration: Instantaneous
Saving Throw: Fortitude negates
Spell Resistance: Yes

The subject contracts a disease selected from the table below, which strikes immediately (no incubation period).

The DC noted is for the subsequent saves (use contagion's normal save DC for the initial saving throw).
Disease				DC	Damage
Blinding sickness	16	1d4 Str 1
Cackle fever		16	1d6 Wis
Filth fever			12	1d3 Dex and 1d3 Con
Mindfire			12	1d4 Int
Red ache			15	1d6 Str
Shakes				13	1d8 Dex
Slimy doom			14	1d4 Con
1 Each time a victim takes 2 or more points of Strength damage from blinding sickness, he or she must make another Fortitude save (using the disease's save DC) or be permanently blinded.

疾病（DISEASE）
當一個人物被髒汙的攻擊所傷，或接觸到帶有疾病源的物品，或吃下被疾病汙染的食物和飲水，他必須立刻進行一次強韌檢定。如果成功，疾病沒產生效果--他的免疫系統擊退了傳染病。如果失敗，在潛伏期後他將受到傷害，之後每過一天他都要進行一次成功的強韌檢定來避免再次傷害。連續兩次豁免檢定成功表明他擊敗了疾病並恢復健康，不再受傷害。
這些強韌豁免檢定可以祕密進行，讓玩家無法得知疾病是否得到控制。

疾病描述：
疾病有許多症狀，並可經由一些傳染源傳播。一些典型疾病的特性在表“疾病”中作了概括說明，定義見下文。
疾病：疾病名稱用斜體印出的屬於超自然能力。其它的屬於特異能力。
感染方式：疾病傳播的方法--攝入（ingested）、吸入（inhaled）、傷口（injury）或接觸（contact）。要注意有些傷口性的疾病可以通過一個很小的傷口傳播，甚至是一個跳蚤咬的傷口，而大部分的吸入性疾病也可通過攝入而被感染（反之亦然）。
DC：用來預防感染（假設該人物已經被感染了）、避免每次的重複傷害、恢復健康的強韌檢定難度等級。
潛伏期：傷害開始前的一段時間。
傷害：在潛伏期結束後以及之後的每天人物將承受的屬性傷害。

疾病的種類：疾病包括以下型別：
失明症（Blinding Sickness）：通過被汙染的水傳播。
失心熱症（Cackle Fever）：症狀包括高燒，意識模糊，以及經常發出陣陣狂笑。也稱為“狂喊症（the shrieks）”。
熱魔症（Demon Fever）：經由老鬼婆（night hags）傳染。能導致永久的屬性吸取。
寒魔症（Devil Chills）：經由巴霸魔（barbazu）和深獄煉魔（pit fiends）傳染。必須經過三次成功的豁免檢定才能恢復健康，而不是通常的兩次。
腐熱症（Filth Fever）：經由凶暴鼠（dire rat）與食腐獸（otyughs）傳染。當傷口處於骯髒的環境中時也會感染。
腦熱症（Mindfire）：患者感到腦袋焦熾般的燒熱。導致昏迷。
腐屍症（Mummy Rot）：經由木乃伊傳染。成功的豁免檢定也不會使感染者恢復健康（但仍能避免傷害）。
紅腫症（Red Ache）：患者膚色轉紅、腫脹、發熱。
顫慄症（The Shakes）：患者會不由自主的抽搐發顫和痙攣。
膠質症（Slimy Doom）：患者會由內到外逐漸變成有感染性的粘稠物。能導致永久的屬性吸取。

表：疾病
疾病		感染方式	DC	潛伏期	傷害
失明症		攝入		16	1d3天	1d4 力量1
失心熱症	吸入		16	1天		1d6 感知
熱魔症		傷口		18	1天		1d6 體質2
寒魔症3		傷口		14	1d4天	1d4 力量
腐熱症		傷口		12	1d3天	1d3 敏捷, 1d3 體質
腦熱症		吸入		12	1天		1d4 智力
腐屍症4		接觸		20	1天		1d6 體質
紅腫症		傷口		15	1d3天	1d6 力量
顫慄症		接觸		13	1天		1d8 敏捷
膠質症		接觸		14	1天		1d4 體質2
1 當人物受到2或更高的傷害時，他必須做一次額外的強韌檢定，失敗則永久目盲。
2 當傷害發作時，他必須成功通過一次額外的強韌豁免，否則受到1點的永久屬性吸取而非原來的屬性傷害。
3 必須經過三次成功的豁免檢定才能恢復健康。
4 成功的豁免檢定也不會使感染者恢復健康。只有魔法醫療才能治癒。

治療疾病
可以使用醫療（Heal）技能照看患者。在每一次患者進行豁免檢定時，醫護者同時進行一次醫療技能判定。如果醫療技能判定結果較高，患者可以採用醫療技能判定結果代替自己的豁免檢定結果來對抗疾病效果。患者必須處於醫療者的照料下，並且必須之前休息了至少8小時。
屬性傷害造成的屬性值丟失會以每天一點的速率回覆，即使人物依然在染病中也是這樣。這意味著患有輕微疾病的人物可以抵抗住疾病而不會積累傷害。

DISEASE
When a character is injured by a contaminated attack touches an item smeared with diseased matter, or consumes disease-tainted food or drink, he must make an immediate Fortitude saving throw. If he succeeds, the disease has no effect—his immune system fought off the infection. If he fails, he takes damage after an incubation period. Once per day afterward, he must make a successful Fortitude saving throw to avoid repeated damage. Two successful saving throws in a row indicate that he has fought off the disease and recovers, taking no more damage.
These Fortitude saving throws can be rolled secretly so that the player doesn’t know whether the disease has taken hold.

Disease Descriptions
Diseases have various symptoms and are spread through a number of vectors. The characteristics of several typical diseases are summarized on Table: Diseases and defined below.
Disease: Diseases whose names are printed in italic in the table are supernatural in nature. The others are extraordinary.
Infection: The disease’s method of delivery—ingested, inhaled, via injury, or contact. Keep in mind that some injury diseases may be transmitted by as small an injury as a flea bite and that most inhaled diseases can also be ingested (and vice versa).
DC: The Difficulty Class for the Fortitude saving throws to prevent infection (if the character has been infected), to prevent each instance of repeated damage, and to recover from the disease.
Incubation Period: The time before damage begins.
Damage: The ability damage the character takes after incubation and each day afterward.

Types of Diseases: Typical diseases include the following:
Blinding Sickness: Spread in tainted water.
Cackle Fever: Symptoms include high fever, disorientation, and frequent bouts of hideous laughter. Also known as “the shrieks”.
Demon Fever: Night hags spread it. Can cause permanent ability drain.
Devil Chills: Barbazu and pit fiends spread it. It takes three, not two, successful saves in a row to recover from devil chills.
Filth Fever: Dire rats and otyughs spread it. Those injured while in filthy surroundings might also catch it.
Mindfire: Feels like your brain is burning. Causes stupor.
Mummy Rot: Spread by mummies. Successful saving throws do not allow the character to recover (though they do prevent damage normally).
Red Ache: Skin turns red, bloated, and warm to the touch.
The Shakes: Causes involuntary twitches, tremors, and fits.
Slimy Doom: Victim turns into infectious goo from the inside out. Can cause permanent ability drain.

Table: Diseases
Disease 			Infection	DC	Incubation	Damage
Blinding sickness	Ingested	16	1d3 days	1d4 Str1
Cackle fever		Inhaled		16	1 day		1d6 Wis
Demon fever			Injury		18	1 day		1d6 Con2
Devil chills3		Injury		14	1d4 days	1d4 Str
Filth fever			Injury		12	1d3 days	1d3 Dex, 1d3 Con
Mindfire			Inhaled		12	1 day		1d4 Int
Mummy rot4			Contact		20	1 day		1d6 Con
Red ache			Injury		15	1d3 days	1d6 Str
Shakes				Contact		13	1 day		1d8 Dex
Slimy doom			Contact		14	1 day		1d4 Con2
1 Each time the victim takes 2 or more damage from the disease, he must make another Fortitude save or be permanently blinded.
2 When damaged, character must succeed on another saving throw or 1 point of damage is permanent drain instead.
3 The victim must make three successful Fortitude saving throws in a row to recover from devil chills.
4 Successful saves do not allow the character to recover. Only magical healing can save the character.

Healing a Disease
Use of the Heal skill can help a diseased character. Every time a diseased character makes a saving throw against disease effects, the healer makes a check. The diseased character can use the healer’s result in place of his saving throw if the Heal check result is higher. The diseased character must be in the healer’s care and must have spent the previous 8 hours resting.
Characters recover points lost to ability score damage at a rate of 1 per day per ability damaged, and this rule applies even while a disease is in progress. That means that a character with a minor disease might be able to withstand it without accumulating any damage.
]]

pwr_remove_disease_d=[[
移除疾病治癒目標所患的所有疾病。

注意：由於本法術的持續時間為立即，它不能預防目標將來受到同樣的疾病感染。
]]
--[[
移除疾病（Remove Disease）
 咒法系（醫療）
等級：牧師 3，德魯伊 3，巡林客 3
法術成分：言語，姿勢
施法時間：1個標準動作
距離：接觸
目標：接觸的生物
持續時間：立即
豁免：強韌通過則無效（無害）
法術抗力：可（無害）

移除疾病治癒目標所患的所有疾病。本法術也能殺死寄生蟲，包括綠色黏怪（green slime）等。某些特殊的疾病不能被本法術消除，或者只能被某一等級以上的施法者抵消。

注意：由於本法術的持續時間為立即，它不能預防目標將來受到同樣的疾病感染。

Remove Disease
 Conjuration (Healing)
Level: Clr 3, Drd 3, Rgr 3
Components: V, S
Casting Time: 1 standard action
Range: Touch
Target: Creature touched
Duration: Instantaneous
Saving Throw: Fortitude negates (harmless)
Spell Resistance: Yes (harmless)

Remove disease cures all diseases that the subject is suffering from. The spell also kills parasites, including green slime and others. Certain special diseases may not be countered by this spell or may be countered only by a caster of a certain level or higher.

Note: Since the spell's duration is instantaneous, it does not prevent reinfection after a new exposure to the same disease at a later date.
]]

pwr_bestow_curse_d=[[
你對目標降下詛咒。

在下列效果中選擇1種：
* 一項屬性值-6（最低1）。
* 攻擊、豁免、屬性和技能檢定-4減值。
* 每一輪目標50%機率正常行動；否則它無法進行動作。
]]
--[[
降咒（Bestow Curse）
 死靈系
等級：牧師 3，術士/法師 4
法術成分：言語，姿勢
施法時間：一個標準動作
距離：接觸
目標：接觸的生物
持續時間：永久
豁免：意志，通過則無效
法術抗力：可

你對目標下了詛咒。在以下三種效果中選擇一種。
* 一項屬性值-6（最低1）。
* 攻擊投骰、豁免、屬性檢定、技能檢定上受到-4懲罰。
* 每一輪裡目標只有50%機會正常行動；另外50%機會它無法進行動作。

你也可以創造出你自己的詛咒，但是不能比上面這些更強。

由此法術產生的詛咒不能被解除，但是可以被破除結界（break enchantment）、有限祈願術（limited wish）、神蹟術（miracle）、移除詛咒（remove curse）、或祈願術（wish）所移除。

降咒反制移除詛咒（remove curse）。

Bestow Curse
 Necromancy
Level: Clr 3, Sor/Wiz 4
Components: V, S
Casting Time: 1 standard action
Range: Touch
Target: Creature touched
Duration: Permanent
Saving Throw: Will negates
Spell Resistance: Yes

You place a curse on the subject. Choose one of the following three effects.

* -6 decrease to an ability score (minimum 1).
* -4 penalty on attack rolls, saves, ability checks, and skill checks.
* Each turn, the target has a 50% chance to act normally; otherwise, it takes no action.

You may also invent your own curse, but it should be no more powerful than those described above.

The curse bestowed by this spell cannot be dispelled, but it can be removed with a break enchantment, limited wish, miracle, remove curse, or wish spell.

Bestow curse counters remove curse.
]]

pwr_remove_curse_d=[[
移除詛咒能立刻移除一個生物身上的所有詛咒。
]]
--[[
移除詛咒（Remove Curse）
 防護系
等級：吟遊詩人 3，牧師 3，聖武士 3，術士/法師 4
法術成分：言語，姿勢
施法時間：1個標準動作
距離：接觸
目標：接觸的生物或物品
持續時間：立即
豁免：意志通過則無效（無害）
法術抗力：可（無害）

移除詛咒即刻移除一個物品或生物上的所有詛咒。移除詛咒不會消除來自於一面受詛咒的盾牌、武器、或一件鎧甲的詛咒，但是本法術可以使受到這些詛咒物品折磨的生物可以卸下並擺脫它。某些特殊的詛咒不能被本法術消除，或者只能被某一等級以上的施法者抵消。

移除詛咒反制並解除降咒（bestow curse）。

Remove Curse
 Abjuration
Level: Brd 3, Clr 3, Pal 3, Sor/Wiz 4
Components: V, S
Casting Time: 1 standard action
Range: Touch
Target: Creature or item touched
Duration: Instantaneous
Saving Throw: Will negates (harmless)
Spell Resistance: Yes (harmless)

Remove curse instantaneously removes all curses on an object or a creature. Remove curse does not remove the curse from a cursed shield, weapon, or suit of armor, although the spell typically enables the creature afflicted with any such cursed item to remove and get rid of it. Certain special curses may not be countered by this spell or may be countered only by a caster of a certain level or higher.

Remove curse counters and dispels bestow curse.
]]

pwr_dominate_person_d=[[
]]
--[[
支配人類（Dominate Person）
 惑控系（脅迫） [影響心靈]
等級：吟遊詩人 4，術士/法師 5
法術成分：言語，姿勢
施法時間： 1輪
距離：近距（25英尺+5英尺/2等級）
目標：一個類人生物
持續時間： 1天/等級
豁免檢定：意志，通過則無效
法術抗力：可
 你可以通過你和目標心智之間的心靈連線來控制任何類人生物的行動。如果你和目標有共通語言，你可以強迫目標在能力範圍內依你的想法行動。若沒有共通語言，你只能用基本命令，如“過來”，“過去”，“戰鬥”，“站住”。你知道受術者的感受，但不會直接得知他的感官知覺，他也無法與你以心靈感應交流。
 一旦你給被支配生物下了指令，他就會全力以赴去完成命令，除了日常生存必需活動（如吃飯、睡覺等）外不會分心做其它事。由於有這種活動限制，因此只需通過DC15的察言觀色檢定（而非25）就可看出此生物的行動是被惑控系法術所控制的（見察言觀色的技能說明）
 對被支配的生物改變指示或下達新的命令相當於指引法術，因此是一個移動動作。
 通過專注於法術（標準動作）你可以完全感受到該生物的感官知覺，但它依舊不能與你交流，你也不可通過它的眼睛視物，所以這不如你實地觀察，但你仍然可以對當地發生的一切相當瞭解。
 當受術者意圖抗拒控制，或強迫對方進行違背天性的行為時，受術者必須重新進行豁免檢定並且有+2加值。明顯的自殺命令不會被執行。一旦控制建立起來，只要你和受術者在同一位面，其有效距離就沒有限制。你不需要看著受術者來控制他。
 你每天都要花一輪時間來專注這個法術，否則受術者就可以通過豁免檢定來擺脫控制。
 當受術者被防護邪惡（Protection from evil）之類的法術保護時，可阻止你對其下令或使用心靈連線，但是不能阻止或解除已建立的支配關係。

你被施法者控制，被迫按其想法行動。
You are controlled by the caster and forced to perform as he desire.

Dominate Person
 Enchantment (Compulsion) [Mind-Affecting]
Level: Brd 4, Sor/Wiz 5
Components: V, S
Casting Time: 1 round
Range: Close (25 ft. + 5 ft./2 levels)
Target: One humanoid
Duration: One day/level
Saving Throw: Will negates
Spell Resistance: Yes
 You can control the actions of any humanoid creature through a telepathic link that you establish with the subject's mind.
 If you and the subject have a common language, you can generally force the subject to perform as you desire, within the limits of its abilities. If no common language exists, you can communicate only basic commands, such as "Come here," "Go there," "Fight," and "Stand still." You know what the subject is experiencing, but you do not receive direct sensory input from it, nor can it communicate with you telepathically.
 Once you have given a dominated creature a command, it continues to attempt to carry out that command to the exclusion of all other activities except those necessary for day-to-day survival (such as sleeping, eating, and so forth). Because of this limited range of activity, a Sense Motive check against DC 15 (rather than DC 25) can determine that the subject's behavior is being influenced by an enchantment effect (see the Sense Motive skill description).
 Changing your instructions or giving a dominated creature a new command is the equivalent of redirecting a spell, so it is a move action.
 By concentrating fully on the spell (a standard action), you can receive full sensory input as interpreted by the mind of the subject, though it still can't communicate with you. You can't actually see through the subject's eyes, so it's not as good as being there yourself, but you still get a good idea of what's going on.
 Subjects resist this control, and any subject forced to take actions against its nature receives a new saving throw with a +2 bonus. Obviously self-destructive orders are not carried out. Once control is established, the range at which it can be exercised is unlimited, as long as you and the subject are on the same plane. You need not see the subject to control it.
 If you don't spend at least 1 round concentrating on the spell each day, the subject receives a new saving throw to throw off the domination.
Protection from evil or a similar spell can prevent you from exercising control or using the telepathic link while the subject is so warded, but such an effect neither prevents the establishment of domination nor dispels it.
]]

pwr_dominate_animal_d=[[
]]
--[[
支配動物（Dominate Animal）
 惑控系（脅迫） [影響心靈]
等級：動物 3，德魯伊 3
法術成分：言語，姿勢
施法時間： 1輪
距離：近距（25英尺+5英尺/2等級）
目標：一個動物
持續時間：1 輪/等級
豁免檢定：意志，通過則無效
法術抗力：可
 你可以迷住一隻動物，並對它下達簡單指令如“攻擊”，“跑”，“取來”。自殺或自殘的指令（包括攻擊體型比被支配動物大兩級或更多的生物）會被忽視。
支配動物會在你和受術生物之間建立心靈連線。只要動物待在法術有效距離內就可以接受無聲的心靈指引。控制它時，你不需要看見它。你無法直接得知它的感官知覺，但可以知道它的感受。由於它受你自己的智慧指引，因此它可以做一些超出它正常理解範圍的事情。你不需要維持專注來控制它，除非你要它做一些它平常不會做的事。改變指令或發出新的命令相當於指引一個法術，因此是個移動動作。

Dominate Animal
 Enchantment (Compulsion) [Mind-Affecting]
Level: Animal 3, Drd 3
Components: V, S
Casting Time: 1 round
Range: Close (25 ft. + 5 ft./2 levels)
Target: One animal
Duration: 1 round/level
Saving Throw: Will negates
Spell Resistance: Yes
 You can enchant an animal and direct it with simple commands such as "Attack," "Run," and "Fetch." Suicidal or self-destructive commands (including an order to attack a creature two or more size categories larger than the dominated animal) are simply ignored.
Dominate animal establishes a mental link between you and the subject creature. The animal can be directed by silent mental command as long as it remains in range. You need not see the creature to control it. You do not receive direct sensory input from the creature, but you know what it is experiencing. Because you are directing the animal with your own intelligence, it may be able to undertake actions normally beyond its own comprehension. You need not concentrate exclusively on controlling the creature unless you are trying to direct it to do something it normally couldn't do. Changing your instructions or giving a dominated creature a new command is the equivalent of redirecting a spell, so it is a move action.
]]

