移除目盲/耳聾能夠治癒目盲或者耳聾（依照你的選擇），不論這目盲和耳聾的效果是魔法還是自然造成的。本法術不會恢復耳朵或眼睛失去的部分，但是能修復受損傷的部分。
移除目盲/耳聾反制並解除目盲/耳聾術（blindness/deafness）。

Remove Blindness/Deafness
 Conjuration (Healing)
Level: Clr 3, Pal 3
Components: V, S
Casting Time: 1 standard action
