Remove blindness/deafness cures blindness or deafness (your choice), whether the effect is normal or magical in nature. The spell does not restore ears or eyes that have been lost, but it repairs them if they are damaged.
Remove blindness/deafness counters and dispels blindness/deafness.
]]

pwr_power_word_blind_d=[[
別名“真言術：盲”。你僅發出一個威力無比的詞就能讓你選定的一個生物目盲，不管它是否能聽見那個詞。

目標當前生命值須低於200或最大生命值的1/4。
]]
--[[
真言術：盲（Power Word Blind）
 惑控系（脅迫） [影響心靈]
等級：術士/法師 7， 戰爭 7
法術成分：言語
施法時間：1個標準動作
距離：近距（25英尺+5英尺/每2等級）
目標：一個200或更少生命值的生物
持續時間： 見正文
豁免：無
法術抗力：可
你僅發出一個威力無比的詞就能讓你選定的一個生物目盲，不管它是否能聽見那個詞。該法術的持續時間和目標的當前總生命值相關。任何當前具有201或者更多生命值的生物都不受真言術：盲影響。
生命值 持續時間 
50或更少 永久 
51–100 1d4+1 分鐘 
101–200 1d4+1 輪 

 Power Word Blind
 Enchantment (Compulsion) [Mind-Affecting]
Level: Sor/Wiz 7, War 7
Components: V
Casting Time: 1 standard action
Range: Close (25 ft. + 5 ft./2 levels)
Target: One creature with 200 hp or less
Duration: See text
Saving Throw: None
Spell Resistance: Yes
You utter a single word of power that causes one creature of your choice to become blinded, whether the creature can hear the word or not. The duration of the spell depends on the target's current hit point total. Any creature that currently has 201 or more hit points is unaffected by power word blind.
Hit Points	Duration
50 or less	Permanent
51-100		1d4+1 minutes
101-200		1d4+1 rounds
]]

pwr_lt_0_n="光亮術"
pwr_lt_0_d=[[
此法術可以使物品像火把一樣發光，從你接觸的那一點發出的光可提供半徑20英尺範圍的明亮照明（外加另外20英尺的昏暗照明）。

法術效果是固定的，但是可施展在可移動的物體上。

進入魔法黑暗區域的光線不起作用。
]]
--[[
光亮術（Light）
 塑能系［光亮］
等級：吟遊詩人 0，牧師 0，德魯伊 0，術士/法師0
法術成分：言語，材料/法器
施法時間：一個標準動作
距離：接觸
目標：接觸到的物品
持續時間：10 分鐘/每等級（可解消）
豁免：無
法術抗力：不可
這個法術可以使物品像火炬一樣發光，從你接觸物體的那一點發出來的光可以照亮20英尺的範圍（並且能微微的照亮另外的20英尺）。法術效果是固定的，但是可施展在可移動的物體上。進入魔法黑暗（darkness）內的光線無法起到作用。
光亮法術（有光亮描述符）可以反制或解除同級或更低等級的黑暗法術（有黑暗描述符）。
奧術材料成分：一隻螢火蟲或一片磷光苔蘚。

Light
 Evocation [Light]
Level: Brd 0, Clr 0, Drd 0, Sor/Wiz 0
Components: V, M/DF
Casting Time: 1 standard action
Range: Touch
Target: Object touched
Duration: 10 min./level (D)
Saving Throw: None
Spell Resistance: No
This spell causes an object to glow like a torch, shedding bright light in a 20-foot radius (and dim light for an additional 20 feet) from the point you touch. The effect is immobile, but it can be cast on a movable object. Light taken into an area of magical darkness does not function.
A light spell (one with the light descriptor) counters and dispels a darkness spell (one with the darkness descriptor) of an equal or lower level.
Arcane Material Component: A firefly or a piece of phosphorescent moss.

light_darkness_note	= "\n\n光亮法術和黑暗法術屬於對立法術：高階覆蓋低階，同級相互抵消。"
light_darkness_note	= "\n\nLight spells and darkness spells are opposite: High levels override low levels, cancel each other out if equal."
光亮術				創造一片魔法光明區域，照亮半徑2格範圍。"..light_darkness_note
黑暗術				使指定半徑2格區域內陷入陰影。區域內的所有生物都獲得掩蔽狀態（20%失手率）。\n\n普通光源和低階光亮法術均無法照亮此區域。"..light_darkness_note
晝明術				創造一片魔法光明區域，將半徑6格範圍照得亮如白晝。"..light_darkness_note
深幽黑暗術			類似黑暗術，但陰影區域半徑為6格。"..light_darkness_note
Light				Creates an area of magical light, shedding bright light in a 2 squares radius."..light_darkness_note
Darkness			Radiates shadowy illumination in a 2 squares radius. All creatures in the area gain concealment (20% miss chance).\n\nNormal lights are incapable of brightening the area, as are light spells of lower level."..light_darkness_note
Daylight			Creates an area of magical light as bright as full daylight in a 6 squares radius."..light_darkness_note
Deeper Darkness		Functions like Darkness, except that radiates shadowy illumination in a 6 squares radius."..light_darkness_note
]]

pwr_lt_0_dance_n="舞光術"
pwr_lt_0_dance_d=[[
此法術能製造一個微微發光的模糊人形，照明效果等同火把，並且每輪自動向黑暗區域移動。
]]-- 它每輪自動向黑暗區域移動，和你的距離不會超過法術範圍。一旦超過，則光源熄滅。, and the distance between you and it will not exceed the spell's range. Once exceeded, the light source winks out.	廢棄範圍 應用性差 且原法術距離很大 可視為無限制
--[[
舞光術（Dancing Lights）
塑能系[光亮]
等級：吟遊詩人0，術士/法師0
法術成分：言語，姿勢
施法時間：一個標準動作
距離：中距（100英尺+10英尺/每等級）
效果：至多四個光源，所有均出現在半徑10英尺區域內
持續時間：1分鐘（可解消）
豁免檢定：無
法術抗力：不可
按照你選擇的不同功效，你可以造出至多四個類似於油燈或火把的光源（併發出同等亮度的光），或者至多四個光球（看起來就像鬼火（will-o’-wisps）），或是一個微微發光的模糊人形。舞光術的光源必須彼此處在10英尺半徑內，在此限制下可以按照你的意願隨意移動（不需要專注精神），包括：向前向後、向上向下、直行或轉彎等等。光源每輪最多可以移動100英尺。光源將會在與你距離超過法術範圍時熄滅。
舞光術可以用魔法恆定術（permanency）恆定。

Dancing Lights
Evocation [Light]
Level: Brd 0, Sor/Wiz 0
Components: V, S
Casting Time: 1 standard action
Range: Medium (100 ft. + 10 ft./level)
Effect: Up to four lights, all within a 10- ft.-radius area
Duration: 1 minute (D)
Saving Throw: None
Spell Resistance: No
Depending on the version selected, you create up to four lights that resemble lanterns or torches (and cast that amount of light), or up to four glowing spheres of light (which look like will-o'-wisps), or one faintly glowing, vaguely humanoid shape. The dancing lights must stay within a 10-foot-radius area in relation to each other but otherwise move as you desire (no concentration required): forward or back, up or down, straight or turning corners, or the like. The lights can move up to 100 feet per round. A light winks out if the distance between you and it exceeds the spell's range.
Dancing lights can be made permanent with a permanency spell.
]]

pwr_lt_1_fey_n="妖火"
pwr_lt_1_fey_d=[[
一團微光籠罩並勾勒出目標的輪廓。被籠罩的目標發出蠟燭般的光芒，顏色一般為藍色、綠色或紫色。

被籠罩的生物無法從黑暗中獲得正常的隱蔽好處（但2級以上的黑暗效果可正常作用），也無法從朦朧術、位移、隱形或類似效果中獲得好處。

妖火對那些被籠罩的物品或生物無法造成任何損害。同時，其光亮非常黯淡，因此也無法對那些會被光所傷的不死生物或居住在黑暗中的生物產生影響。
]]
--[[
妖火（Faerie Fire）
塑能系[光亮]
等級：德魯伊 1
法術成分：言語，姿勢，法器
施法時間：一個標準動作
距離：遠距（400英尺+40英尺/每等級）
區域：5英尺半徑爆發範圍內的生物和物品
持續時間：1分鐘/每等級（可解消）
豁免：無
法術抗力：可
一團微光籠罩並勾勒出目標的輪廓。被籠罩的目標發出蠟燭般的光芒。被籠罩的生物無法從黑暗中獲得正常的隱蔽好處（但是2級或更高等級的黑暗（darkness）效果依然可以正常運作），也無法從朦朧術（blur）、位移（displacement）、隱形，或類似的效果中獲得好處。這種光亮太黯淡了，因此無法對那些會被光所傷的不死生物或居住在黑暗中的生物產生影響。根據你施法時的選擇，妖火可以是藍色、綠色或者是紫色。妖火對那些被籠罩的物品或生物無法造成任何損害。

Faerie Fire
Evocation [Light]
Level: Drd 1
Components: V, S, DF
Casting Time: 1 standard action
Range: Long (400 ft. + 40 ft./level)
Area: Creatures and objects within a 5-ft.-radius burst
Duration: 1 min./level (D)
Saving Throw: None
Spell Resistance: Yes
A pale glow surrounds and outlines the subjects. Outlined subjects shed light as candles. Outlined creatures do not benefit from the concealment normally provided by darkness (though a 2nd-level or higher magical darkness effect functions normally), blur, displacement, invisibility, or similar effects. The light is too dim to have any special effect on undead or dark-dwelling creatures vulnerable to light. The faerie fire can be blue, green, or violet, according to your choice at the time of casting. The faerie fire does not cause any harm to the objects or creatures thus outlined.
]]

pwr_lt_2_fire_n="不滅明焰"
pwr_lt_2_fire_d=[[
火焰從你接觸的物體上向外躍出，帶來和火把相同的光亮。

該效果看上去和普通火焰無異，但它並不散發熱量也不需要消耗氧氣。

不滅明焰可以被遮擋和掩藏，但無法被熄滅。
]]
--[[
不滅明焰（Continual Flame）
塑能系[光]
等級：牧師3，術士/法師2
法術成分：言語、姿勢、材料
施法時間：一個標準動作
距離：接觸
目標：接觸到的物品
效果：沒有熱量的魔法火焰
持續時間：永久
豁免檢定：無
法術抗力：不可
火焰從你接觸的物體上向外躍出，帶來和火炬相同的光亮。該效果看上去和普通火焰無異，但它並不散發熱量也不需要消耗氧氣。一個不滅明焰可以被掩藏起來，但無法熄滅它。
光明法術可以反制或解除相同級別或更低階的黑暗法術。
材料成分：將紅寶石粉末（價值50金幣）鋪灑在物體上來點燃火焰。

Continual Flame
Evocation [Light]
Level: Clr 3, Sor/Wiz 2
Components: V, S, M
Casting Time: 1 standard action
Range: Touch
Target: Object touched
Effect: Magical, heatless flame
Duration: Permanent
Saving Throw: None
Spell Resistance: No
A flame, equivalent in brightness to a torch, springs forth from an object that you touch. The effect looks like a regular flame, but it creates no heat and doesn't use oxygen. A continual flame can be covered and hidden but not smothered or quenched.
Light spells counter and dispel darkness spells of an equal or lower level.
Material Component: You sprinkle ruby dust (worth 50 gp) on the item that is to carry the flame.
]]

pwr_lt_3_n="晝明術"	pwr_lt_3_u="半徑60英尺的魔法光亮"	pwr_lt_3_d=[[
被接觸的物體發出光亮，將半徑60英尺的範圍照得亮如白晝，此範圍外額外60英尺範圍內有昏暗光線。

會因明亮光線而遭受減值的生物在此魔法光亮下也會受影響。但與法術名稱不同的是，對於會被陽光所傷或所摧毀的生物而言，此法術不能取代真正的陽光。

若將晝明術施放在一個小物體上，然後把此物體放在遮光的掩蓋物裡面或下面，則法術效果會被阻隔，直到掩蓋物被移開。

進入魔法黑暗區域內的晝明術會暫時無效，反之亦然。所以，兩者效果重疊的區域會保持原來的亮度。
]]
--[[
晝明術（Daylight）
塑能系[光亮]
等級：吟遊詩人 3，牧師 3，德魯伊 3，聖武士 3，術士/法師 3
法術成分：言語，姿勢
施法時間： 一個標準動作
距離：接觸
目標：被接觸的物體
持續時間：10 分鐘/等級（可解消）
豁免檢定：無
法術抗力：不可
被接觸的物體發出光亮，將半徑60英尺的範圍照得亮如白晝，此範圍外60英尺範圍內有昏暗的光亮。會因光亮而受到減值的生物在這樣的魔法光亮下也會受影響。但是和法術名字不同的是，對於會被陽光所傷或所摧毀的生物來說，這個法術不能取代真正的陽光。
若將法術施展與小物體上，然後用擋光物體完全遮住，則法術效果會被遮擋，直到覆蓋物被移開。
被帶入魔法黑暗區域內的晝明術會暫時無效，反之亦然。所以，兩者效果重疊的區域會保持原來的亮度。
晝明術可以反制或解除任何同等級或更低等級的黑暗法術，如黑暗術（darkness）。

Daylight
 Evocation [Light]
Level: Brd 3, Clr 3, Drd 3, Pal 3, Sor/Wiz 3
Components: V, S
Casting Time: 1 standard action
Range: Touch
Target: Object touched
Duration: 10 min./level (D)
Saving Throw: None
Spell Resistance: No
The object touched sheds light as bright as full daylight in a 60-foot radius, and dim light for an additional 60 feet beyond that. Creatures that take penalties in bright light also take them while within the radius of this magical light. Despite its name, this spell is not the equivalent of daylight for the purposes of creatures that are damaged or destroyed by bright light.
If daylight is cast on a small object that is then placed inside or under a light- proof covering, the spell's effects are blocked until the covering is removed.
Daylight brought into an area of magical darkness (or vice versa) is temporarily negated, so that the otherwise prevailing light conditions exist in the overlapping areas of effect.
Daylight counters or dispels any darkness spell of equal or lower level, such as darkness.
]]

pwr_dk_2_n="黑暗術"	pwr_dk_2_u="半徑20英尺的魔法黑暗"	pwr_dk_2_d=[[
此法術使一個物體周圍20英尺半徑內陷入陰影。區域內的所有生物都獲得隱蔽（20%失手率）。即便生物通常能在此條件下正常視物（如黑暗視覺或昏暗視覺），攻擊魔法黑暗區域內的目標也將有此失手率。

普通光源（火把、蠟燭、提燈等）無法照亮此區域，較低等級的光亮魔法也一樣。較高等級的光亮魔法不受黑暗術影響。

若將黑暗術施放在一個小物體上，然後把此物體放在遮光的掩蓋物裡面或下面，則法術效果將被阻隔，直到掩蓋物被移開。
]]
--[[
黑暗術（Darkness）
 塑能系[黑暗]
等級：吟遊詩人2，牧師2，術士/法師2
法術成分：言語，材料/法器
施法時間：一個標準動作
距離：接觸
目標：接觸到的物體
持續時間：10分鐘/每等級（可解消）
豁免檢定：無
法術抗力：不可
此法術使一個物體周圍20英尺半徑內陷入陰影。區域內的生物都得到掩蔽（20%的失手率）。即便生物通常能在此條件下正常視物（例如黑暗視覺或微光視力），在黑暗術區域內也將有此失手率。
普通光源（火把、蠟燭、提燈等等）無法照亮此區域，較低等級的光亮魔法也一樣。較高階的光亮魔法在黑暗術中不受影響。
如果黑暗術施放在一個小物體上，當此物體被放在遮光的掩蓋物裡面或下面時，此法術效果將被阻隔，直到遮蓋物移去。
黑暗術可反制或解除任何同等級或更低的光亮法術。
奧術材料成分：一小片蝙蝠的皮毛，以及一滴瀝青或一塊煤炭。

Darkness
 Evocation [Darkness]
Level: Brd 2, Clr 2, Sor/Wiz 2
Components: V, M/DF
Casting Time: 1 standard action
Range: Touch
Target: Object touched
Duration: 10 min./level (D)
Saving Throw: None
Spell Resistance: No
This spell causes an object to radiate shadowy illumination out to a 20-foot radius. All creatures in the area gain concealment (20% miss chance). Even creatures that can normally see in such conditions (such as with darkvision or low-light vision) have the miss chance in an area shrouded in magical darkness.
Normal lights (torches, candles, lanterns, and so forth) are incapable of brightening the area, as are light spells of lower level. Higher level light spells are not affected by darkness.
If darkness is cast on a small object that is then placed inside or under a lightproof covering, the spell's effect is blocked until the covering is removed.
Darkness counters or dispels any light spell of equal or lower spell level.
Arcane Material Component: A bit of bat fur and either a drop of pitch or a piece of coal.
]]

pwr_dk_3_n="深幽黑暗術"
pwr_dk_3_d=[[
類似黑暗術，但陰影區域半徑為60英尺，且黑暗持續時間更長。

進入深幽黑暗術區域內的晝明術會暫時無效，反之亦然。所以，兩者效果重疊的區域會保持原來的亮度。
]]
--[[
深幽黑暗術（Deeper Darkness）
 塑能系[黑暗]
等級：牧師 3
持續時間：1天/等級（可解消）
和黑暗術（darkness）一樣，只是陰影區域半徑為60英尺，且黑暗持續時間更長。
施展在深幽黑暗術內的晝明術（daylight）會暫時無效，反之亦然。所以，兩者效果重疊的區域會保持原來的亮度。
深幽黑暗術可反制或解除任何同等級或較低等級的光亮法術，包括晝明術和光亮術（light）。

Deeper Darkness
 Evocation [Darkness]
Level: Clr 3
Duration: One day/level (D)
This spell functions like darkness, except that the object radiates shadowy illumination in a 60-foot radius and the darkness lasts longer.
Daylight brought into an area of deeper darkness (or vice versa) is temporarily negated, so that the otherwise prevailing light conditions exist in the overlapping areas of effect.
Deeper darkness counters and dispels any light spell of equal or lower level, including daylight and light.
]]

pwr_glitterdust_d=[[
一團金色微粒的煙雲籠罩在區域內的所有人和物品上，法術期間內生物會因此目盲，隱形事物會被勾勒出可見的輪廓。整個區域的一切都被光塵所覆蓋，無法被移除，一直閃爍著直到熄滅為止。
]]
--[[
閃光塵（Glitterdust）
 咒法系（創造）
等級：吟遊詩人 2，術士/法師 2
法術成分：言語，姿勢，材料
施法時間：一個標準動作
距離：中距（100英尺+10英尺/每等級）
區域：10英尺半徑擴散範圍內的生物和物品
持續時間：1輪/每等級
豁免：意志，通過則無效（僅對目盲而言）
法術抗力：不可
 一團金色微粒的煙雲籠罩在區域內的所有人和物品上，法術期間內生物會因此目盲，隱形物品會被勾勒出可見的輪廓。整個區域的一切都被光塵所覆蓋，光塵無法被移除，它會一直閃爍著直到熄滅為止。
 任何被光塵所籠罩的生物在躲藏上受到-40減值。
材料成分：雲母粉。

Glitterdust
 Conjuration (Creation)
Level: Brd 2, Sor/Wiz 2
Components: V, S, M
Casting Time: 1 standard action
Range: Medium (100 ft. + 10 ft./level)
Area: Creatures and objects within 10-ft.-radius spread
Duration: 1 round/level
Saving Throw: Will negates (blinding only)
Spell Resistance: No
 A cloud of golden particles covers everyone and everything in the area, causing creatures to become blinded and visibly outlining invisible things for the duration of the spell. All within the area are covered by the dust, which cannot be removed and continues to sparkle until it fades.
 Any creature covered by the dust takes a -40 penalty on Hide checks.
Material Component: Ground mica.
]]

pwr_invisibility_d=[[
你變得不可見，從視線中消失。如果你攻擊任何生物，則此效果結束。此類攻擊包括武器攻擊和向敵人或敵人所在區域施法。祝福術等隻影響盟友的法術不算攻擊，就算範圍內有敵人存在。
]]
--[[
隱形術（Invisibility）
 幻術系（五官幻覺）
等級：吟遊詩人 2，術士/法師2，詭計2
法術成分：言語，姿勢，材料/法器
施法時間：1個標準動作
距離：個人或接觸
目標：自身，或一個生物，或不重於100磅/每等級的物品
持續時間：1分鐘/每等級（可解消）
豁免：意志通過無效（無害） ，或意志通過無效（無害，物品）
法術抗力：可（無害），或可（無害，物品）
 被接觸的生物或物品變得不可見，從視線中消失，就算有黑暗視覺也無法發現他們。若受術者有裝備，也一併消失。如果是放在別人身上，你和你的盟友也無法看見他，除非你能看見隱性的物品或者使用魔法來這麼做。
 從隱形者身上掉出或放下的物品會顯形；被其拿起的物品如果放入他穿戴的衣服或口袋內則會消失。光線是不會隱形的，儘管光源可以隱形（因此效果是光從看不見的光源上發出）。被攜帶的物品超出10尺的部分不會隱形。
 當然目標並非被魔法消聲，而且在有些情況下依然會被注意到（如在泥地中行走）。如果受術者攻擊任何生物，則法術結束。可中止法術的攻擊包括：向敵人或是包含有敵人的區域施法。（誰是敵人是根據隱形生物的態度判斷。）只針對未被持用物品的動作不會結束該法術。間接傷害不是攻擊。所以隱形者可以開門、交談、進食、爬樓梯、召喚怪獸並指引它們攻擊，當敵人過橋時剪斷繫住橋的繩索，或是遠端觸動陷阱，開門放狗等等。如果直接攻擊，那麼隱形者將和他的裝備一起立即現形。隻影響盟友而不影響敵人的法術（如祝福（bless））並不算攻擊，就算範圍內有敵人存在。
 可以使用魔法恆定術（permanency）恆定隱形術（僅能用在物品上）。
奧術材料：一小根包在透明膠內的睫毛。

Invisibility
 Illusion (Glamer)
Level: Brd 2, Sor/Wiz 2, Trickery 2
Components: V, S, M/DF
Casting Time: 1 standard action
Range: Personal or touch
Target: You or a creature or object weighing no more than 100 lb./level
Duration: 1 min./level (D)
Saving Throw: Will negates (harmless) or Will negates (harmless, object)
Spell Resistance: Yes (harmless) or Yes (harmless, object)
 The creature or object touched becomes invisible, vanishing from sight, even from darkvision. If the recipient is a creature carrying gear, that vanishes, too. If you cast the spell on someone else, neither you nor your allies can see the subject, unless you can normally see invisible things or you employ magic to do so.
 Items dropped or put down by an invisible creature become visible; items picked up disappear if tucked into the clothing or pouches worn by the creature. Light, however, never becomes invisible, although a source of light can become so (thus, the effect is that of a light with no visible source). Any part of an item that the subject carries but that extends more than 10 feet from it becomes visible.
 Of course, the subject is not magically silenced, and certain other conditions can render the recipient detectable (such as stepping in a puddle). The spell ends if the subject attacks any creature. For purposes of this spell, an attack includes any spell targeting a foe or whose area or effect includes a foe. (Exactly who is a foe depends on the invisible character's perceptions.) Actions directed at unattended objects do not break the spell. Causing harm indirectly is not an attack. Thus, an invisible being can open doors, talk, eat, climb stairs, summon monsters and have them attack, cut the ropes holding a rope bridge while enemies are on the bridge, remotely trigger traps, open a portcullis to release attack dogs, and so forth. If the subject attacks directly, however, it immediately becomes visible along with all its gear. Spells such as bless that specifically affect allies but not foes are not attacks for this purpose, even when they include foes in their area.
Invisibility can be made permanent (on objects only) with a permanency spell.
Arcane Material Component: An eyelash encased in a bit of gum arabic.
]]

pwr_greater_invisibility_d=[[
類似隱形術，但進行攻擊不會終止法術。
]]
--[[
高階隱形術（Invisibility, Greater）
 幻術系（五官幻覺）
等級：吟遊詩人 4，術士/法師4
法術成分：言語，姿勢
目標：自身或接觸到的生物
持續時間：1輪/每等級（可解消）
豁免：意志，通過無效（無害）
 該法術類似隱形術，但進行攻擊不會終止法術。

Invisibility, Greater
 Illusion (Glamer)
Level: Brd 4, Sor/Wiz 4
Components: V, S
Target: You or creature touched
Duration: 1 round/level (D)
Saving Throw: Will negates (harmless)
 This spell functions like invisibility, except that it doesn't end if the subject attacks.
]]

pwr_mass_invisibility_d=[[
類似隱形術，但法術效果隨著這群生物一起進行，直到其中任意一人攻擊為止。
]]
--[[
群體隱形術（Invisibility, Mass）
 幻術系（五官幻覺）
等級：術士/法師 7
法術成分：言語，姿勢，材料
距離：遠距 （400英尺+40英尺/等級）
目標：任意數量生物，任意兩者之間相距不得超過180英尺
 該法術類似隱形術。但法術效果隨著這群生物一起進行的，直到受術者中的任意一人攻擊為止。受術者無法看見彼此。一個受術者只要移動至距離群體中離他最近的受術者180英尺以上，他身上的法術會中止。（如果只有兩個個體受術，那麼當一個受術者移動離開另外一個受術者180英尺以上時，他身上的法術會中止。如果彼此都互相離開，那麼當它們之間的距離超過180英尺時會同時顯形。）
法術材料：一小根包在透明膠內的睫毛。

Invisibility, Mass
 Illusion (Glamer)
Level: Sor/Wiz 7
Components: V, S, M
Range: Long (400 ft. + 40 ft./level)
Targets: Any number of creatures, no two of which can be more than 180 ft. apart
 This spell functions like invisibility, except that the effect is mobile with the group and is broken when anyone in the group attacks. Individuals in the group cannot see each other. The spell is broken for any individual who moves more than 180 feet from the nearest member of the group. (If only two individuals are affected, the one moving away from the other one loses its invisibility. If both are moving away from each other, they both become visible when the distance between them exceeds 180 feet.)
Material Component: An eyelash encased in a bit of gum arabic.
]]

pwr_invisibility_sphere_d=[[
你周圍半徑10英尺內的所有生物隱形。效果區域中心點會隨你移動。

受影響生物移出此區域後會顯形，而施法後再移入的生物不會隱形。

受影響生物（除了你）進行攻擊只會使其自身顯形。如果你進行攻擊，則此法術結束。

受影響生物能看見彼此和自己，如同未受影響一樣。
]]
--[[
 隱形法球（Invisibility Sphere）
 幻術系（五官幻覺）
等級：吟遊詩人 3，術士/法師3
法術成分：言語，姿勢，材料
區域：接觸的人或物周圍的半徑10英尺球形瀰漫區域
 該法術作用類似隱形術，但會使受術者周圍半徑10英尺內的所有生物隱形。影響區域的起源點會隨著受術者移動。
 受影響的生物可以看見彼此，也能看到自己，如同他們沒有受到影響一樣。任何已經受影響的生物移出該區域後會顯形，而施法後再移入的生物不會隱形。隱形的生物（除了受術者本身）進行攻擊只會使自身顯形。如果受術者本身進行攻擊，則隱形法球結束。

Invisibility Sphere
 Illusion (Glamer)
Level: Brd 3, Sor/Wiz 3
Components: V, S, M
Area: 10-ft.-radius emanation around the creature or object touched
 This spell functions like invisibility, except that this spell confers invisibility upon all creatures within 10 feet of the recipient. The center of the effect is mobile with the recipient.
 Those affected by this spell can see each other and themselves as if unaffected by the spell. Any affected creature moving out of the area becomes visible, but creatures moving into the area after the spell is cast do not become invisible. Affected creatures (other than the recipient) who attack negate the invisibility only for themselves. If the spell recipient attacks, the invisibility sphere ends.
]]

pwr_see_invisibility_d=[[
你能看到視野範圍內任何隱形或靈體生物或物體，如同它們是正常可見狀態一樣。

在你看來，這類生物具有半透明的外形，你可以輕易區分可見、隱形、靈體生物之間的差別。
]]
--[[
識破隱形（See Invisibility）
 預言系
等級：吟遊詩人 3，術士/法師 2
法術成分：言語，姿勢，材料
施法時間：一個標準動作
距離：個人
目標：你自己
持續時間：10分鐘/每等級（可解消）
 你可以看到視野範圍內任何隱形的物體或生物，那些靈化狀態的事物也一樣，如同它們是正常可見狀態一樣。在你看來，這類生物具有半透明的外形，你可以輕易區分出可見、隱形、靈化生物之間的差別。
 這個法術不能覺察出是何種方法造成的隱形。它也不能看穿幻像或讓你看透不透明的物品。對那些僅通過躲藏、隱蔽等方式來很難被看到的事物來說，這個法術也不能看穿它們。
識破隱形可以用魔法恆定術（permanency）恆定。
材料成分：一撮滑石粉和少量銀粉。

See Invisibility
 Divination
Level: Brd 3, Sor/Wiz 2
Components: V, S, M
Casting Time: 1 standard action
Range: Personal
Target: You
Duration: 10 min./level (D)
 You can see any objects or beings that are invisible within your range of vision, as well as any that are ethereal, as if they were normally visible. Such creatures are visible to you as translucent shapes, allowing you easily to discern the difference between visible, invisible, and ethereal creatures.
 The spell does not reveal the method used to obtain invisibility. It does not reveal illusions or enable you to see through opaque objects. It does not reveal creatures who are simply hiding, concealed, or otherwise hard to see.
See invisibility can be made permanent with a permanency spell.
Material Component: A pinch of talc and a small sprinkling of powdered silver.
]]

pwr_invisibility_purge_d=[[
你被一種可以中和任何形式隱形的球形力量所包圍。任何隱形事物在此區域內都會顯形。
]]
--[[
 消除隱形（Invisibility Purge）
 塑能系
等級：牧師 3
法術成分：言語，姿勢
施法時間：1個標準動作
距離：個人
目標：自身
持續時間：1分鐘/每等級（可解消）
 你被一種可以中和任何形式隱形的球形力量所包圍，該球形的半徑是每施法者等級5英尺。
 任何隱形事物在此區域內都會顯形。

Invisibility Purge
 Evocation
Level: Clr 3
Components: V, S
Casting Time: 1 standard action
Range: Personal
Target: You
Duration: 1 min./level (D)
 You surround yourself with a sphere of power with a radius of 5 feet per caster level that negates all forms of invisibility.
 Anything invisible becomes visible while in the area.
]]

pwr_true_seeing_d=[[
你被賦予看到事物真實面目的能力。你可以看穿普通和魔法黑暗，看到受朦朧術或移位術影響的生物或物體的真實位置，看到隱形的生物或物體，看穿幻術，看到靈界位面。

真知術可看穿的距離為120英尺。
]]
--[[
 真知術（True Seeing）
 預言系
等級：牧師5，德魯伊7，知識5，術士/法師6
法術成分：言語，姿勢，材料
施法時間：1個標準動作
距離：接觸
目標：被接觸的生物
持續時間：1分鐘/等級
豁免：意志，通過則無效（無害）
法術抗力：可（無害）
 你賦予受術者以看到事物真實面目的能力。受術者可以看穿普通和魔法的黑暗，注意到被魔法隱藏的暗門，看到受朦朧術（blur）或移位術（displacement）影響的物體的真實位置，看到隱形的生物或物體，看穿幻術，看出變形者的真實樣貌。受術者可以看到靈界位面（但看不到異次元空間）。真知術可看穿的距離為120英尺。
 然而，真知術並不能透視固體。它不能起到X光的效果。它無法看穿隱蔽，包括霧或類似情況造成的。它也不能偵察到躲藏起來的生物或注意到以普通方法隱藏的密門。此法術效果不能為其他魔法增強，所以不能透過水晶球（crystal ball）使用真知術，也不能和銳耳術/鷹眼術（clairaudience/clairvoyance）合併使用。
材料成分：價值250金幣，由蘑菇粉，藏紅花和油脂製成的眼藥膏。

True Seeing
 Divination
Level: Clr 5, Drd 7, Knowledge 5, Sor/Wiz 6
Components: V, S, M
Casting Time: 1 standard action
Range: Touch
Target: Creature touched
Duration: 1 min./level
Saving Throw: Will negates (harmless)
Spell Resistance: Yes (harmless)
 You confer on the subject the ability to see all things as they actually are. The subject sees through normal and magical darkness, notices secret doors hidden by magic, sees the exact locations of creatures or objects under blur or displacement effects, sees invisible creatures or objects normally, sees through illusions, and sees the true form of polymorphed, changed, or transmuted things. Further, the subject can focus its vision to see into the Ethereal Plane (but not into extradimensional spaces). The range of true seeing conferred is 120 feet.
True seeing, however, does not penetrate solid objects. It in no way confers X-ray vision or its equivalent. It does not negate concealment, including that caused by fog and the like. True seeing does not help the viewer see through mundane disguises, spot creatures who are simply hiding, or notice secret doors hidden by mundane means. In addition, the spell effects cannot be further enhanced with known magic, so one cannot use true seeing through a crystal ball or in conjunction with clairaudience/clairvoyance.
Material Component: An ointment for the eyes that costs 250 gp and is made from mushroom powder, saffron, and fat.
]]

pwr_bless_d=[[
祝福術讓你的盟友充滿了勇氣。每個盟友在攻擊投骰和對抗恐懼的豁免上都得到+1士氣加值。
]]
--[[
祝福術（Bless）
 惑控系（脅迫）[影響心靈]
等級：牧師 1，聖武士 1
法術成分：言語，姿勢，法器
施法時間：一個標準動作
距離：50英尺
區域：施法者和所有以施法者為中心50英尺半徑爆發範圍內的所有盟友
持續時間：1分鐘/每等級
豁免：無
法術抗力：可（無害）
祝福術讓你的盟友充滿了勇氣。每個盟友在攻擊投骰和對抗恐懼的豁免上都得到+1士氣加值。
祝福術反制和解除絕望術（bane）。

Bless
 Enchantment (Compulsion) [Mind-Affecting]
Level: Clr 1, Pal 1
Components: V, S, DF
Casting Time: 1 standard action
Range: 50 ft.
Area: The caster and all allies within a 50-ft. burst, centered on the caster
Duration: 1 min./level
Saving Throw: None
Spell Resistance: Yes (harmless)
Bless fills your allies with courage. Each ally gains a +1 morale bonus on attack rolls and on saving throws against fear effects.
Bless counters and dispels bane.
]]

pwr_bane_d=[[
絕望術讓你的敵人充滿恐懼和疑惑。每個被影響的生物在攻擊投骰和對抗恐懼的豁免上都受到-1減值。
]]
--[[
絕望術（Bane）
 惑控系（脅迫）[恐懼，影響心靈]
等級：牧師 1
法術成分：言語，姿勢，法器
施法時間：一個標準動作
距離：50英尺
區域：50英尺內所有敵人
持續時間：1分鐘/每等級
豁免：意志，通過則無效
法術抗力：可
絕望術讓你的敵人充滿恐懼和疑惑。每個被影響的生物在攻擊投骰和對抗恐懼的豁免上都受到-1減值。
絕望術對抗和反制祝福術（bless）。

Bane
 Enchantment (Compulsion) [Fear, Mind-Affecting]
Level: Clr 1
Components: V, S, DF
Casting Time: 1 standard action
Range: 50 ft.
Area: All enemies within 50 ft.
Duration: 1 min./level
Saving Throw:Will negates
Spell Resistance: Yes
Bane fills your enemies with fear and doubt. Each affected creature takes a -1 penalty on attack rolls and a -1 penalty on saving throws against fear effects.
Bane counters and dispels bless.
]]

pwr_prayer_d=[[
你將神之恩寵帶給你自己和你的盟友，同時將厭惡帶給你的敵人。你和你的每個盟友在攻擊、武器傷害、豁免和技能檢定上都獲得+1幸運加值，同時你的每個敵人都會在這類檢定上受到-1減值。
]]
--[[
祈禱術（Prayer）
 惑控系（脅迫） [影響心靈]
等級：牧師 3， 聖武士 3
法術成分：言語，姿勢，法器
施法時間：1個標準動作
距離：40英尺
區域：以你為中心40英尺爆發範圍內所有盟友和敵人
持續時間： 1 輪/每等級
豁免：無
法術抗力：可
你將神之恩寵帶給你自己和你的盟友，同時將厭惡帶給你的敵人。你和你的每個盟友在攻擊、武器傷害、豁免和技能檢定上都獲得+1幸運加值，同時你的每個敵人都會在這類檢定上受到-1減值。

Prayer
 Enchantment (Compulsion) [Mind-Affecting]
Level: Clr 3, Pal 3
Components: V, S, DF
Casting Time: 1 standard action
Range: 40 ft.
Area: All allies and foes within a 40-ft.-radius burst centered on you
Duration: 1 round/level
Saving Throw: None
Spell Resistance: Yes
You bring special favor upon yourself and your allies while bringing disfavor to your enemies. You and your each of your allies gain a +1 luck bonus on attack rolls, weapon damage rolls, saves, and skill checks, while each of your foes takes a -1 penalty on such rolls.
]]

pwr_shield_other_d=[[
此法術在施法者和受術者之間形成某種神祕的聯結，使得受術者遭受的部分傷害可以轉移到施法者身上。

受術者的防禦等級+1偏斜加值，豁免+1抗力加值，所受任何生命值傷害均減半，另一半則由施法者承受。

一旦施法者和受術者之間的距離超出施法距離，則法術結束。
]]
--[[
護衛他人（Shield Other）
 防護系
等級：牧師 2，聖武士 2，保護 2
法術成分：言語，姿勢，器材
施法時間：一個標準動作
距離：近距（25英尺+5英尺/每2等級）
目標：一個生物
持續時間：1小時/等級（可解消）
豁免：意志，通過則無效（無害）
法術抗力：可（無害）
此法術在你和受術者之間形成某種神祕的聯結，使得他遭受的部分傷害可以轉移到你身上。受術者的AC獲得+1偏斜加值，豁免檢定獲得+1抗力加值。另外受術者所受的任何造成生命值損失的傷害均減半（包括由特殊能力造成的），剩下的部分則由施法者承受。不減少生命值的傷害，比如魅惑、暫時性屬性傷害、吸取等級及死亡效果則不受影響。若受術者的生命值因體質降低而減少，施法者亦不受影響。法術結束後，施法者不再承受受術者所受傷害，但已吸收的傷害也不會轉回受術者身上。
 一旦你和受術者之間的距離超出施法距離，則法術結束。
器材成分：一對白金戒指（每隻至少50金幣），分別戴在你和受術者身上。

Shield Other
 Abjuration
Level: Clr 2, Pal 2, Protection 2
Components: V, S, F
Casting Time: 1 standard action
Range: Close (25 ft. + 5 ft./2 levels)
Target: One creature
Duration: 1 hour/level (D)
Saving Throw: Will negates (harmless)
Spell Resistance: Yes (harmless)
This spell wards the subject and creates a mystic connection between you and the subject so that some of its wounds are transferred to you. The subject gains a +1 deflection bonus to AC and a +1 resistance bonus on saves. Additionally, the subject takes only half damage from all wounds and attacks (including that dealt by special abilities) that deal hit point damage. The amount of damage not taken by the warded creature is taken by you. Forms of harm that do not involve hit points, such as charm effects, temporary ability damage, level draining, and death effects, are not affected. If the subject suffers a reduction of hit points from a lowered Constitution score, the reduction is not split with you because it is not hit point damage. When the spell ends, subsequent damage is no longer divided between the subject and you, but damage already split is not reassigned to the subject.
If you and the subject of the spell move out of range of each other, the spell ends.
Focus: A pair of platinum rings (worth at least 50 gp each) worn by both you and the warded creature.
]]

pwr_dismissal_d=[[
此法術可將一個跨位面生物強行送回它的原屬位面（意志檢定DC = 法術豁免檢定DC - 生物的等級 + 你的施法者等級）。

若法術成功，此生物立即被送走，但有20%機率將它送至其原屬位面以外的位面。
]]
--[[
驅逐術（Dismissal）
 防護系
等級：牧師 4，術士/法師 5
法術成分：言語，姿勢，法器
施法時間： 一個標準動作
距離：近距（25英尺+5英尺/2等級）
目標：一個跨位面生物
持續時間：立即
豁免檢定：意志，通過則無效；見說明
法術抗力：可

此法術可將一個跨位面生物強行送回它的原屬位面，前提是它意志檢定失敗（DC=法術豁免檢定DC-生物的HD+你的施法者等級）。若法術成功，生物立即被送走，但有20%的機率將生物送至其原屬位面以外的位面。

Dismissal
 Abjuration
Level: Clr 4, Sor/Wiz 5
Components: V, S, DF
Casting Time: 1 standard action
Range: Close (25 ft. + 5 ft./2 levels)
Target: One extraplanar creature
Duration: Instantaneous
Saving Throw: Will negates; see text
Spell Resistance: Yes

This spell forces an extraplanar creature back to its proper plane if it fails a special Will save (DC = spell's save DC - creature's HD + your caster level). If the spell is successful, the creature is instantly whisked away, but there is a 20% chance of actually sending the subject to a plane other than its own.
]]

pwr_banishment_d=[[
放逐術是驅逐術的強力版本。它可以強迫多個跨位面生物離開你的原屬位面，最多可放逐總等級=你的施法者等級x2的生物。
]]
--[[
放逐術（Banishment）
 防護系
等級：牧師 6，術士/法師 7
法術成分：言語，姿勢，器材
施法時間：一個標準動作
距離：近距（25英尺+5英尺/每2等級）
目標：一個或多個跨位面生物，任意兩者之間不得超過30英尺
持續時間：立即
豁免：意志，通過則無效
法術抗力：可

放逐術是驅逐術（dismissal）的強力版本。它可以強迫跨位面生物離開你的原屬位面。最多可以有HD兩倍於你施法者等級的生物被放逐。

如果在施法的時候有目標仇恨、恐懼或其它對立的物品或物質存在，你可以增大法術成功的機會。每一件這類物品或物質會讓你在超越目標法術抗力（如果有）時的施法者等級檢定上獲得+1加值，而法術豁免DC增加2。

某些稀有的物品在這些加值上會比普通物品強一倍（即每件物品對抗法術抗力的施法者等級檢定提供+2加值，豁免DC增加4）。

奧術器材：任何令目標不適的物品（可選的，見上文）。

Banishment
 Abjuration
Level: Clr 6, Sor/Wiz 7
Components: V, S, F
Casting Time: 1 standard action
Range: Close (25 ft. + 5 ft./2 levels)
Targets: One or more extraplanar creatures, no two of which can be more than 30 ft. apart
Duration: Instantaneous
Saving Throw: Will negates
Spell Resistance: Yes

A banishment spell is a more powerful version of the dismissal spell. It enables you to force extraplanar creatures out of your home plane. As many as 2 Hit Dice of creatures per caster level can be banished.

You can improve the spell's chance of success by presenting at least one object or substance that the target hates, fears, or otherwise opposes. For each such object or substance, you gain a +1 bonus on your caster level check to overcome the target's spell resistance (if any), the saving throw DC increases by 2.

Certain rare items might work twice as well as a normal item for the purpose of the bonuses (each providing a +2 bonus on the caster level check against spell resistance and increasing the save DC by 4).

Arcane Focus: Any item that is distasteful to the subject (optional, see above).
]]

pwr_freedom_of_movement_d=[[
受術者在通常會妨礙行動的魔法影響下，如麻痺，緩慢術，蛛網術等，也可正常移動和攻擊，且對抗或脫離擒抱時自動成功。
]]
--[[
行動自如（Freedom of Movement）
 防護系
等級：吟遊詩人 4，牧師 4，德魯伊 4，機運 4，巡林客 4
法術成分：言語，姿勢，材料，法器
施法時間：一個標準動作
距離：個人或接觸
目標：你自己或接觸的生物
持續時間：10分鐘/每等級
豁免：意志，通過則無效（無害）
法術抗力：可（無害）

該法術持續時間內，你或你所觸控的生物即便處在通常會妨礙移動的魔法影響下也可正常的移動和攻擊，例如麻痺，重霧術（solid fog），緩慢術（slow），蛛網術（web）。受術者在任何用來抗拒擒抱的擒抱檢定時總是自動成功，同樣在用來脫離擒抱或壓制的擒抱檢定或脫逃術檢定時也是如此。

該法術還允許受術者在水下正常移動和攻擊，甚至使用劍斧類揮砍武器或鏈枷、戰錘、硬頭錘等鈍擊類武器也可如此，只要該武器是手持而非投擲即可。但是行動自如不能讓你在水中呼吸。

材料成分：圍繞在胳膊或類似肢體上的一根皮帶。

Freedom of Movement
 Abjuration
Level: Brd 4, Clr 4, Drd 4, Luck 4, Rgr 4
Components: V, S, M, DF
Casting Time: 1 standard action
Range: Personal or touch
Target: You or creature touched
Duration: 10 min./level
Saving Throw: Will negates (harmless)
Spell Resistance: Yes (harmless)

This spell enables you or a creature you touch to move and attack normally for the duration of the spell, even under the influence of magic that usually impedes movement, such as paralysis, solid fog, slow, and web. The subject automatically succeeds on any grapple check made to resist a grapple attempt, as well as on grapple checks or Escape Artist checks made to escape a grapple or a pin.

The spell also allows the subject to move and attack normally while underwater, even with slashing weapons such as axes and swords or with bludgeoning weapons such as flails, hammers, and maces, provided that the weapon is wielded in the hand rather than hurled. The freedom of movement spell does not, however, allow water breathing.

Material Component: A leather thong, bound around the arm or a similar appendage.
]]

pwr_haste_d=[[
受術者的移動和動作速度遠快於平時。

動作的加快會帶來以下效果：
- 全力攻擊時額外攻擊一次。
- 移動速度+30英尺增強加值，最高為正常速度x2。
- 攻擊檢定+1加值，防禦和反射檢定+1閃避加值。

多個加速術的效果不疊加。加速術可解除緩慢術。
]]
--[[
加速術（Haste）
 變化系
等級：吟遊詩人 3，術士/法師3
法術成分：言語，姿勢，材料
施法時間：1個標準動作
距離：近距（25英尺+ 5英尺/每2等級）
目標：彼此相距不超過30英尺的每級別一個生物
持續時間：1輪/級別
豁免：強韌，通過則無效（無害）
法術抗力：可（無害）

受術者的移動和動作速度遠快於平時。動作的加快會帶來以下效果。

當作全力攻擊時，加速後的生物會獲得一次額外的攻擊機會，該次攻擊可以使用任何正在持用的武器做出。這次攻擊使用該生物全部的基本攻擊加值，附加任何符合該情況的調整值。（該效果無法與類似能力疊加，例如追擊（speed）武器，也不會真的帶來額外的動作，因此你也無法利用這效果每輪多行動或施法一次。）

加速的生物在攻擊上有+1的加值，並且在AC和反射檢定上有+1的閃避加值。當你失去你AC的敏捷加值時，你失去該閃避加值。

被加速生物的所有移動方式（包括地面移動、掘地、攀爬、飛行、游泳）上速度會增加30英尺，最高達到受術者該移動方式正常速度的兩倍。增加的速度是增強加值，同時也會按正常方式影響該生物的跳躍距離。

多個加速術無法疊加。加速術會反制或解除緩慢術（slow）。

法術材料：一片甘草的根。

Haste
 Transmutation
Level: Brd 3, Sor/Wiz 3
Components: V, S, M
Casting Time: 1 standard action
Range: Close (25 ft. + 5 ft./2 levels)
Targets: One creature/level, no two of which can be more than 30 ft. apart
Duration: 1 round/level
Saving Throw: Fortitude negates (harmless)
Spell Resistance: Yes (harmless)

The transmuted creatures move and act more quickly than normal. This extra speed has several effects.

When making a full attack action, a hasted creature may make one extra attack with any weapon he is holding. The attack is made using the creature's full base attack bonus, plus any modifiers appropriate to the situation. (This effect is not cumulative with similar effects, such as that provided by a weapon of speed, nor does it actually grant an extra action, so you can't use it to cast a second spell or otherwise take an extra action in the round.)

A hasted creature gains a +1 bonus on attack rolls and a +1 dodge bonus to AC and Reflex saves. Any condition that makes you lose your Dexterity bonus to Armor Class (if any) also makes you lose dodge bonuses.

All of the hasted creature's modes of movement (including land movement, burrow, climb, fly, and swim) increase by 30 feet, to a maximum of twice the subject's normal speed using that form of movement. This increase counts as an enhancement bonus, and it affects the creature's jumping distance as normal for increased speed.

Multiple haste effects don't stack. Haste dispels and counters slow.

Material Component: A shaving of licorice root.
]]

pwr_slow_d=[[
受術者的移動和攻擊均變得相當緩慢。

- 每輪只能做一個移動或標準動作。
- 只能半速移動。
- 攻擊檢定、防禦、反射豁免-1減值。

多個緩慢術的效果不疊加。緩慢術可解除加速術。
]]
--[[
緩慢術（Slow）
 變化系
等級：吟遊詩人 3，術士/法師 3
法術成分：言語，姿勢，材料
施法時間：一個標準動作
距離：近距（25英尺+5英尺/每2等級）
目標：1個生物/等級，每兩個生物之間相距不超過30英尺
持續時間：1輪/等級
豁免：意志，通過則無效
法術抗力：可

受術者的移動、攻擊均變得相當緩慢。

緩慢生物每輪只能做一個移動動作或一個標準動作，但不能都作（也不能做整輪動作）。

另外他在攻擊檢定、AC、反射豁免上得到-1的減值。

他只能以半速移動（以5尺為單位，四捨五入），他的跳躍距離和其他情況下一樣會因為速度的降低而受到影響。

緩慢術的效果不疊加。緩慢術可反制和解除加速術（haste）。
材料成分：一滴糖漿。

Slow
 Transmutation
Level: Brd 3, Sor/Wiz 3
Components: V, S, M
Casting Time: 1 standard action
Range: Close (25 ft. + 5 ft./2 levels)
Targets: One creature/level, no two of which can be more than 30 ft. apart
Duration: 1 round/level
Saving Throw: Will negates
Spell Resistance: Yes

An affected creature moves and attacks at a drastically slowed rate. A slowed creature can take only a single move action or standard action each turn, but not both (nor may it take full-round actions). Additionally, it takes a -1 penalty on attack rolls, AC, and Reflex saves. A slowed creature moves at half its normal speed (round down to the next 5-foot increment), which affects the creature's jumping distance as normal for decreased speed.

Multiple slow effects don't stack. Slow counters and dispels haste.

Material Component: A drop of molasses.
]]

pwr_delay_poison_d=[[
受術者暫時對毒物免疫。

原本在其體內的任何毒素，或在法術持續期間中的毒都不會影響受術者，直到法術結束。

減緩毒發不會治療毒物已經造成的任何傷害。
]]
--[[
減緩毒發（Delay Poison）
 咒法系（醫療）
等級：吟遊詩人 2，牧師 2，德魯伊 2，聖武士 2，巡林客1
法術成分：言語，姿勢，法器
施法時間： 一個標準動作
距離：接觸
目標：接觸到的生物
持續時間： 1小時/等級
豁免檢定：強韌，通過則無效 （無害）
法術抗力：可（無害）

受術者暫時對毒物免疫。原本在體內的任何毒素，或在法術持續期間中的毒都不會影響受術者，直到法術過期。減緩毒發不會治療毒物已經造成的任何傷害。

Delay Poison
 Conjuration (Healing)
Level: Brd 2, Clr 2, Drd 2, Pal 2, Rgr 1
Components: V, S, DF
Casting Time: 1 standard action
Range: Touch
Target: Creature touched
Duration: 1 hour/level
Saving Throw: Fortitude negates (harmless)
Spell Resistance: Yes (harmless)

The subject becomes temporarily immune to poison. Any poison in its system or any poison to which it is exposed during the spell's duration does not affect the subject until the spell's duration has expired. Delay poison does not cure any damage that poison may have already done.
]]

pwr_neutralize_poison_d=[[
中和生物身上任何種類的毒性，目標不再遭受該毒素的附加效果，暫時效果也會終止。

在法術持續時間內，目標免疫任何毒素（無需對毒素做豁免檢定）。

此法術無法治癒已存在的立即傷害，如生命值傷害，暫時屬性傷害，或無法自行復原的效果。
]]
--[[
中和毒性（Neutralize Poison）
 咒法系（醫療）
等級：吟遊詩人4，牧師4，德魯伊3，聖武士4，巡林客3
法術成分：言語，姿勢，材料/法器
施法時間：1個標準動作
距離：接觸
目標：接觸到的單一生物，或體積至多1立方英尺/每等級的物品
持續時間：10分鐘/每等級
豁免：意志，通過則無效（無害，物品）
法術抗力：可（無害，物品）

你可以中和你接觸到的目標生物或物品身上的任何種類的毒性。此法術生效後，中毒生物不會再因為該毒素而受影響，該毒素造成的暫時效果也可以恢復。但此法術無法治癒已經存在的立即傷害，如：生命值傷害，暫時屬性傷害，或任何無法自行復原的效果。

在法術持續時間內，目標生物對任何毒素都免疫。與減緩毒發（delay poison）不同的是，此法術並不是延遲毒發的時刻到該法術持續時間結束——目標生物在法術持續時間內不需要對毒素做任何豁免檢定。

如果施法者願意，此法術也可以在法術持續時間內中和有毒生物體內或物品上的毒性。

奧術材料成分：一塊木炭

Neutralize Poison
 Conjuration (Healing)
Level: Brd 4, Clr 4, Drd 3, Pal 4, Rgr 3
Components: V, S, M/DF
Casting Time: 1 standard action
Range: Touch
Target: Creature or object of up to 1 cu. ft./level touched
Duration: 10 min./level
Saving Throw: Will negates (harmless, object)
Spell Resistance: Yes (harmless, object)

You detoxify any sort of venom in the creature or object touched. A poisoned creature suffers no additional effects from the poison, and any temporary effects are ended, but the spell does not reverse instantaneous effects, such as hit point damage, temporary ability damage, or effects that don't go away on their own.

The creature is immune to any poison it is exposed to during the duration of the spell. Unlike with delay poison, such effects aren't postponed until after the duration - the creature need not make any saves against poison effects applied to it during the length of the spell.

This spell can instead neutralize the poison in a poisonous creature or object for the duration of the spell, at the caster's option.

Arcane Material Component: A bit of charcoal.
]]

