如同一些自然界有毒性的掠食者一樣，你通過一次成功的近戰接觸攻擊向目標體內注入一種劇毒。這種毒立即造成1d10點暫時體質傷害，並且1分鐘後再造成1d10點暫時體質傷害。每一次的傷害都可以通過成功的強韌豁免（DC=10+1/2你的施法者等級+你的感知調整值）來抵消。

Poison
 Necromancy
