pwr_command_d=[[
]]
--[[
命令術（Command）
 惑控系（脅迫）[依賴於語言，影響心靈]
等級：牧師1
法術成分：言語
施法時間：一個標準動作
距離：近距（25英尺+5英尺/每2等級）
目標：一個活物
持續時間：1輪
豁免檢定：意志，通過則無效
法術抗力：可
 你對受術者下達單字的命令，他將盡其所能在最早的時候去完成它。你可以從下列選項中挑選。
來（Approach）：在他的回合內，受術者將盡全力的迅速直接向你靠近。受術者將什麼也不做僅僅是朝你靠近，這期間可能會造成別人對其藉機攻擊。
掉（Drop）：在他的回合內，受術者會將手裡的所有東西都扔掉，在他下一輪之前都將不會撿起來。
倒（Fall）：在他的回合內，受術者會躺倒在地。在俯臥中他可以繼續正常行動，但是要受到對應的懲罰。
逃（Flee）：在他的回合內，受術者將盡全力的迅速遠離你。受術者將什麼也不做僅僅是離開，這期間可能會造成別人對其藉機攻擊。
停（Halt）：受術者將原地不動1輪。他將不能做任何動作，但並非無助狀態。
 如果受術者在他接下來的回合內無法完成你所下達的命令，該法術自動失效。

命令：來				在你的回合中，你將盡可能迅速直接地走向此效果的施法者，其他什麼也不做。
命令：逃				在你的回合中，你將盡可能迅速直接地遠離此效果的施法者，其他什麼也不做。
命令：停				在你的回合中，你將原地不動1輪，不能做任何動作，但並非無助。
命令：倒				在你的回合中，你將躺倒在地1輪。俯臥中你能正常行動，但要受到相應的懲罰。
命令：掉				在你的回合中，你將扔掉手中所有物品，直到你的下一回合之前都不會撿起來。
Command: Approach		On your turn, you may do nothing but move toward the caster as quickly and directly as possible for 1 round.
Command: Flee			On your turn, you may do nothing but move away from the caster as quickly as possible for 1 round.
Command: Halt			On your turn, you stand in place for 1 round. You may not take any actions but are not considered helpless.
Command: Fall			On your turn, you fall to the ground and remains prone for 1 round. You may act normally while prone but take any appropriate penalties.
Command: Drop			On your turn, you drop whatever you are holding. You can't pick up any dropped item until your next turn.

Command
 Enchantment (Compulsion) [Language-Dependent, Mind-Affecting]
Level: Clr 1
Components: V
Casting Time: 1 standard action
Range: Close (25 ft. + 5 ft./2 levels)
Target: One living creature
Duration: 1 round
Saving Throw: Will negates
Spell Resistance: Yes
 You give the subject a single command, which it obeys to the best of its ability at its earliest opportunity. You may select from the following options.
Approach: On its turn, the subject moves toward you as quickly and directly as possible for 1 round. The creature may do nothing but move during its turn, and it provokes attacks of opportunity for this movement as normal.
Drop: On its turn, the subject drops whatever it is holding. It can't pick up any dropped item until its next turn.
Fall: On its turn, the subject falls to the ground and remains prone for 1 round. It may act normally while prone but takes any appropriate penalties.
Flee: On its turn, the subject moves away from you as quickly as possible for 1 round. It may do nothing but move during its turn, and it provokes attacks of opportunity for this movement as normal.
Halt: The subject stands in place for 1 round. It may not take any actions but is not considered helpless.
 If the subject can't carry out your command on its next turn, the spell automatically fails.
]]

