pwr_lesser_restoration_d=[[
次等復原術能解除所有對目標的一項屬性值造成減值的魔法效果，或治療1d4點目標的一項屬性所受暫時屬性傷害。

它也能清除角色的疲乏效果，或由力竭恢復到疲乏。
]]
--[[
次等復原術（Restoration, Lesser）
 咒法系（醫療）
等級：牧師 2，德魯伊2，聖武士 1
法術成分：言語，姿勢
施法時間：3輪
距離：接觸
目標：接觸到的生物
