目標：一個生物
持續時間：立即
豁免檢定：強韌，通過則效果減半
法術抗力：是
此法術可在瞬間殺死目標並摧毀遺體（但不包括其裝備、物品）。若目標通過強韌檢定，則受到10d6點傷害。對於檢定失敗的生物，要復活只能通過完全復生術（true resurrection），措辭嚴謹的祈願術（wish）外加復生術（resurrection），或者神蹟術（miracle）。
