pwr_repulsion_d=[[
一個隱形的移動魔法場包圍著你並阻擋其它生物接近你。

場內或試圖進入的任何生物必須進行一次豁免檢定，失敗則效果持續時間內不能朝你移動。
]]
--[[
排斥術（Repulsion）
 防護系
等級：牧師 7，保護 7，術士/法師 6
法術成分：言語，姿勢，器材/法器
施法時間：1個標準動作
距離：至多10英尺/等級
區域：以你為中心的至多半徑10英尺/等級瀰漫區域
持續時間： 1輪/等級（可解消）
豁免：意志通過則無效
法術抗力：可
 一個隱形的移動魔法場包圍著你並阻擋其它生物接近你。你在施法時決定魔法場的大小（受到你的施法等級限制）。任何魔法場內或試圖進入的生物都必須進行一次豁免檢定。如果失敗，在法術持續時間內它不能朝你移動。試圖離開的生物的行動不會受到影響。
 它們可以與其他生物戰鬥、對你施展法術或使用遠端武器攻擊你。如果你向一個受影響的生物靠近，不會發生任何事。（該生物不會被強迫退後。）如果你進入生物的觸及範圍，那麼它可以自由使用近戰武器攻擊你。如果一個被驅離的生物遠離你之後重新試圖接近你，如果它仍在法術區域內它仍然無法接近你。
 奧術器材：一對小鐵棍，上面有兩個犬科動物的小雕像，一黑一白，總價值50金幣。

Repulsion
 Abjuration
Level: Clr 7, Protection 7, Sor/Wiz 6
Components: V, S, F/DF
Casting Time: 1 standard action
Range: Up to 10 ft./level
Area: Up to 10-ft.-radius/level emanation centered on you
Duration: 1 round/level (D)
Saving Throw: Will negates
Spell Resistance: Yes
 An invisible, mobile field surrounds you and prevents creatures from approaching you. You decide how big the field is at the time of casting (to the limit your level allows). Any creature within or entering the field must attempt a save. If it fails, it becomes unable to move toward you for the duration of the spell. Repelled creatures' actions are not otherwise restricted.
 They can fight other creatures and can cast spells and attack you with ranged weapons. If you move closer to an affected creature, nothing happens. (The creature is not forced back.) The creature is free to make melee attacks against you if you come within reach. If a repelled creature moves away from you and then tries to turn back toward you, it cannot move any closer if it is still within the spell's area.
Arcane Focus: A pair of small iron bars attached to two small canine statuettes, one black and one white, the whole array worth 50 gp.
]]

pwr_antimagic_field_d=[[
一道隱形屏障圍繞著你，並隨你移動。此屏障會壓制其區域內所有法術或魔法效果，包括魔法物品，並使召喚生物消失（反魔場移開後在原地重新出現）。
]]
--[[
反魔場（Antimagic Field）
 防護系
等級：牧師 8，魔法 6，保護6，術士/法師 6
法術成分：言語，姿勢，材料/法器
施法時間：一個標準動作
距離：10英尺
區域：以你為中心的10英尺半徑瀰漫區域
持續時間：10分鐘/每等級（可解消）
豁免：無
法術抗力：見正文
 一道隱形屏障圍繞著你，並隨你移動。在這屏障之內的空間裡大部分魔法效果都無法進入，包括法術、類法術能力、超自然能力。同時，它也阻止了所有範圍內的魔法物品和法術的運轉。
反魔場壓制了在範圍內使用、帶入範圍內、或者對區域內施展的所有法術或魔法效果，但並不是解除它。在反魔場內的時間計入被壓制法術的持續時間內。
 所有種類的召喚生物，以及虛體不死生物在進入反魔場區域時會消失不見。當反魔場移開後它們又會在原地重新出現。消失的時間計入維持生物的咒語持續時間。如果你對一個已經被召喚生物佔據的空間施展反魔場，該生物又具有法術抗力，那麼你必須做一個施法者等級檢定（1d20+施法者等級）來對抗該生物的法術抗力，從而讓它消失。（持續時間為立即的咒法系法術其效果不會受到反魔場影響，因為該咒術本身並不存在於效果，這只是它的結果。）
 普通生物可以進入這一區域，也可以正常的射擊。而且，就算一把魔法劍在這區域內沒有魔法能力，它依然是把劍（而且是精製品劍）。對魔像和其它構裝體來說，它們在製造過程中灌注了魔法，之後就靠自己維持，反魔場隊它們無效（除非它們是被召喚來的，這種情況下將它們視作其它召喚生物）。類似地，元素、實體不死生物、異界生物也不受影響，除非它們是被召喚來的。當然，這些生物的類法術能力和超自然能力暫時會被反魔場無效化。解除魔法（Dispel magic）不會移除反魔場。
 共享同一空間的兩個或多個反魔場不會互相影響。某些法術，例如力場牆（wall of force），虹光法球（prismatic sphere），虹光法牆（prismatic wall）不受反魔場影響（見對應法術說明）。神器和神祗不會被類似此法術的凡間法術所影響。
 如果生物比屏障佔據的空間還要大，那麼所有在屏障外的部分都不受影響。
奧術材料成分：一撮鐵粉或鐵屑。

Antimagic Field
 Abjuration
Level: Clr 8, Magic 6, Protection 6, Sor/Wiz 6
Components: V, S, M/DF
Casting Time: 1 standard action
Range: 10 ft.
Area: 10-ft.-radius emanation, centered on you
Duration: 10 min./level (D)
Saving Throw: None
Spell Resistance: See text
 An invisible barrier surrounds you and moves with you. The space within this barrier is impervious to most magical effects, including spells, spell-like abilities, and supernatural abilities. Likewise, it prevents the functioning of any magic items or spells within its confines.
 An antimagic field suppresses any spell or magical effect used within, brought into, or cast into the area, but does not dispel it. Time spent within an antimagic field counts against the suppressed spell's duration.
 Summoned creatures of any type and incorporeal undead wink out if they enter an antimagic field. They reappear in the same spot once the field goes away. Time spent winked out counts normally against the duration of the conjuration that is maintaining the creature. If you cast antimagic field in an area occupied by a summoned creature that has spell resistance, you must make a caster level check (1d20 + caster level) against the creature's spell resistance to make it wink out. (The effects of instantaneous conjurations are not affected by an antimagic field because the conjuration itself is no longer in effect, only its result.)
 A normal creature can enter the area, as can normal missiles. Furthermore, while a magic sword does not function magically within the area, it is still a sword (and a masterwork sword at that). The spell has no effect on golems and other constructs that are imbued with magic during their creation process and are thereafter self-supporting (unless they have been summoned, in which case they are treated like any other summoned creatures). Elementals, corporeal undead, and outsiders are likewise unaffected unless summoned. These creatures' spell-like or supernatural abilities, however, may be temporarily nullified by the field. Dispel magic does not remove the field.
 Two or more antimagic fields sharing any of the same space have no effect on each other. Certain spells, such as wall of force, prismatic sphere, and prismatic wall, remain unaffected by antimagic field (see the individual spell descriptions). Artifacts and deities are unaffected by mortal magic such as this. 
 Should a creature be larger than the area enclosed by the barrier, any part of it that lies outside the barrier is unaffected by the field.
Arcane Material Component: A pinch of powdered iron or iron filings.
]]

pwr_protection_from_evil_d=[[
一道魔法屏障圍繞著你，並隨你移動。它能讓你在邪惡生物和召喚生物的攻擊中獲得防護，還可壓制精神控制。\n\n- 對抗邪惡生物發起的攻擊或效果時，你的防禦等級+2偏斜加值，豁免檢定+2抗性加值。\n\n- 壓制你身上的精神控制效果。\n\n- 阻止邪惡召喚生物的天生武器攻擊。召喚生物可用法術抗力來突破此防護。如果你對被阻攔的生物進行攻擊，則此針對召喚生物的防護終止。
]]

pwr_protection_from_chaos_d=[[
類似防護邪惡，但針對善良生物。
]]

pwr_protection_from_good_d=[[
類似防護邪惡，但針對混亂生物。
]]

pwr_protection_from_law_d=[[
類似防護邪惡，但針對秩序生物。
]]
--[[
防護邪惡（Protection from Evil）
 防護系 [善良]
等級：牧師 1，善良 1，聖武士 1，術士/法師 1
法術成分：言語，姿勢，材料/法器
施法時間：1個標準動作
距離：接觸
目標：接觸的生物
持續時間：1分鐘/等級（可解消）
豁免：意志通過則無效（無害）
法術抗力：不可；見正文
 這個法術能讓一個生物在邪惡生物的攻擊中獲得防護，也可以防護精神控制，以及對召喚生物獲得防護。它能在受術者身邊1英尺處製造出一道魔法屏障。這個魔法屏障隨著受術者移動，具有以下三種主要效果。
 首先，該受術者AC獲得+2偏斜加值，在豁免上獲得+2抗性加值。所有這些加值都只對邪惡生物發起的攻擊或效果有效。
 第二，這個魔法屏障能阻止任何佔據受防護者的嘗試（例如魔魂壺（magic jar）的攻擊），也能阻止任何嘗試精神控制的嘗試（包括能使施法者控制受術者的惑控系（魅惑）和惑控系（脅迫）效果，例如支配人類（dominate person））。這個防護並不能預防此類效果使其無法針對受保護的生物，但是在防護邪惡效果的持續時間內它能壓制此類效果。如果防護邪惡在精神控制效果結束前結束，那麼控制者又可以精神控制被控制的生物。和此類似的是，這個屏障能阻止嘗試進行佔據的生命力，但是無法驅除在施法前已經佔據了的生命力。這第二項效果和陣營無關，總是起效。
 第三，這個法術能阻止召喚生物進行的肢體接觸。因此此類生物的天生武器攻擊會失敗，如果攻擊需要接觸被防護的生物，那麼它會被彈回去。善良召喚生物免疫此效果。如果被防護的生物對被阻攔的生物進行攻擊，或者嘗試用魔法屏障逼近被阻攔的生物，那麼此種防護召喚生物接觸的保護會終止。可以用法術抗力來突破這種防護從而接觸被防護的生物。
奧術材料成分：一點銀粉和你圍繞著欲防護生物在地板（或地面）上繪製的一個三英尺直徑圓環。

Protection from Evil
Abjuration [Good]
Level: Clr 1, Good 1, Pal 1, Sor/Wiz 1
Components: V, S, M/DF
Casting Time: 1 standard action
Range: Touch
Target: Creature touched
Duration: 1 min./level (D)
Saving Throw: Will negates (harmless)
Spell Resistance: No; see text
This spell wards a creature from attacks by evil creatures, from mental control, and from summoned creatures. It creates a magical barrier around the subject at a distance of 1 foot. The barrier moves with the subject and has three major effects.
First, the subject gains a +2 deflection bonus to AC and a +2 resistance bonus on saves. Both these bonuses apply against attacks made or effects created by evil creatures.
Second, the barrier blocks any attempt to possess the warded creature (by a magic jar attack, for example) or to exercise mental control over the creature (including enchantment (charm) effects and enchantment (compulsion) effects that grant the caster ongoing control over the subject, such as dominate person). The protection does not prevent such effects from targeting the protected creature, but it suppresses the effect for the duration of the protection from evil effect. If the protection from evil effect ends before the effect granting mental control does, the would-be controller would then be able to mentally command the controlled creature. Likewise, the barrier keeps out a possessing life force but does not expel one if it is in place before the spell is cast. This second effect works regardless of alignment.
Third, the spell prevents bodily contact by summoned creatures. This causes the natural weapon attacks of such creatures to fail and the creatures to recoil if such attacks require touching the warded creature. Good summoned creatures are immune to this effect. The protection against contact by summoned creatures ends if the warded creature makes an attack against or tries to force the barrier against the blocked creature. Spell resistance can allow a creature to overcome this protection and touch the warded creature.
Arcane Material Component: A little powdered silver with which you trace a 3-foot -diameter circle on the floor (or ground) around the creature to be warded.

 防護善良（Protection from Good）
 防護系 [邪惡]
等級：牧師 1，邪惡 1，術士/法師 1
這個法術作用類似防護邪惡（protection from evil），只是它的偏斜加值和抗性加值只對善良生物的攻擊起效，也只有善良召喚生物無法接觸受術者。

Protection from Good
Abjuration [Evil]
Level: Clr 1, Evil 1, Sor/Wiz 1
This spell functions like protection from evil, except that the deflection and resistance bonuses apply to attacks from good creatures, and good summoned creatures cannot touch the subject.

防護混亂（Protection from Chaos）
 防護系 [秩序]
等級：牧師 1，秩序 1，聖武士 1，術士/法師 1
這個法術作用類似防護邪惡（protection from evil），只是它的偏斜加值和抗性加值只對混亂生物的攻擊起效，也只有混亂召喚生物無法接觸受術者。

Protection from Chaos
Abjuration [Lawful]
Level: Clr 1, Law 1, Pal 1, Sor/Wiz 1
This spell functions like protection from evil, except that the deflection and resistance bonuses apply to attacks from chaotic creatures, and chaotic summoned creatures cannot touch the subject.

 防護秩序（Protection from Law）
 防護系 [混亂]
等級：混亂 1，牧師 1，術士/法師 1
這個法術作用類似防護邪惡（protection from evil），只是它的偏斜加值和抗性加值只對守序生物的攻擊起效，也只有守序召喚生物無法接觸受術者。

Protection from Law
