法術抗力：可
任何在瀆神之語區域內的非邪惡生物都會受到如下疾病效果。
HD	效果
等於施法者等級	暈眩
至多施法者等級-1	虛弱，暈眩
至多施法者等級-5	麻痺，虛弱，暈眩
至多施法者等級-10	被殺，麻痺，虛弱，暈眩
這些效果是可累加的，並且同時發生。
這些效果不能進行豁免。
