至多為施法者等級-1	緩慢，變聾
至多為施法者等級-5	麻痺, 緩慢, 耳聾
至多為施法者等級-10	被殺，麻痺，緩慢，耳聾

這些效果可疊加，且同時發生。這些效果無豁免檢定。
