緩慢（Slowed）：生物如同受到緩慢術（slow），減緩2d4輪。
麻痺（Paralyzed）：生物麻痺，陷入無助狀態1d10分鐘。
被殺（Killed）：活物死亡。不死生物被摧毀。
此外，若施法時你處於自己的原屬位面，則非守序的跨位面生物會被立即逐回自己的位面。被驅逐的生物24小時內不可返回。不論該生物是否聽見律言，此效果都可發生。若通過意志檢定（受-4懲罰），則不會被驅逐。
HD超過你施法者等級的生物不受律言影響。

Dictum
