[pwr_atk_r					]={n="遠端攻擊",	d="使用弓，弩或投擲等遠端武器，你可以攻擊到武器射程內的任意目標。\n\n與近戰攻擊不同，遠端攻擊可能會觸發鄰接敵人的藉機攻擊。"},
