[pwr_end_turn				]={n="防禦",		d="你可以用一個標準動作來防衛自己，本輪內上防禦等級獲得+2閃避加值（以整輪動作進行防禦則為+4）。\n\n若無法進行動作則只是簡單地結束回合。"},

