[pwr_ch_2_effs				]={n=		"重擊掌握"				,d="造成重擊時，能觸發2種重擊效果。無此專長時，只能觸發1種重擊效果，即使有多個重擊效果專長。"},
-- shd/amr
[pwr_shd_use1				]={n="擅長盾牌"						,d="使用盾牌（塔盾除外）時，攻擊無減值。\n\n<b>通常：</b>當你使用不擅長的盾牌時，攻擊將承受盾牌的防具攻擊減值。"},
[pwr_shd_use2				]={n=	"擅長塔盾"					,d="類似擅長盾牌，但針對塔盾。"},
[pwr_shd_def1				]={n=	"專攻盾牌"					,d="盾牌提供的防禦等級和反射豁免+1加值。"},
[pwr_shd_def2				]={n=		"高等專攻盾牌"			,d="專攻盾牌的加值再+1。"},
[pwr_amr_use1				]={n="擅長輕型盔甲"					,d="穿著輕型盔甲時無攻擊減值。\n\n<b>通常：</b>當人物穿著非擅長的盔甲型別時，攻擊將承受盔甲的防具攻擊減值。"},
[pwr_amr_use2				]={n=	"擅長中型盔甲"				,d="類似擅長輕型盔甲，但針對中型盔甲。"},
[pwr_amr_use3				]={n=		"擅長重型盔甲"			,d="類似擅長輕型盔甲，但針對重型盔甲。"},
-- melee
[pwr_cleave					]={n=	"順勢斬"						,d="如果你對某個目標造成足以使之倒下的傷害（典型的情況是殺死它），你可以立即對攻擊範圍內的另一目標發動一次額外的近戰攻擊。\n\n此攻擊使用的武器和加值，與放倒上個目標的攻擊相同。本能力每輪可使用一次。"	},-- 近戰殺死目標後，順勢向另一目標發動一次額外的攻擊。When facing multiple enemies, if your melee attack kills one, you get a free attack on another.		-- 如：將對手的生命值打到0以下，或殺死對方 typically by dropping it to below 0 hit points or killing it	在進行這次額外攻擊前，你不可做五尺快步。You cannot take a 5-foot step before making this extra attack. 	特殊：戰士可以選本專長作為其戰士獎勵專長。Special: A fighter may select Cleave as one of his fighter bonus feats.
[pwr_cleave_x				]={n=		"大順勢斬"				,d="每輪順勢斬次數不限。"},
[pwr_cleave_ko				]={n=		"精通順勢斬"				,d="擊倒也可引發順勢斬。"},
[pwr_atk_m_tgt2				]={n=		"橫掃攻擊"				,d="對攻擊範圍內的兩個相鄰生物發動一次近戰攻擊。所有攻擊基於你最高基本攻擊加值，但有-2減值。"..use_a},
[pwr_atk_m_tgt2_1			]={n=			"精通橫掃攻擊"		,d="免除橫掃攻擊的懲罰。"},
[pwr_atk_m_tgt2_2			]={n=				"高等橫掃攻擊"	,d="橫掃攻擊可攻擊三個相鄰生物。"},
[pwr_atk_m_tgtx				]={n="旋風攻擊"						,d="對攻擊範圍內的所有生物發動一次近戰攻擊。"..use_b},
[pwr_del_2					]={n="無用能力"						,d="你已忘記為何習得此無用能力。或許去導師那裡重訓忘掉它會更好。"},
[pwr_charge1				]={n="精通衝鋒"						,d="衝鋒時攻擊和傷害檢定+2加值。\n\n無此專長時，加值為1。"},
[pwr_charge2				]={n="高等衝鋒"						,d="精通衝鋒的加值再+2。"},
[pwr_ao_dex					]={n="戰鬥反射"						,d="可額外進行數量等於敏捷加值的藉機攻擊，且措手不及時也可進行藉機攻擊。"},
[pwr_dex_wpn				]={n="武器嫻熟"						,d="當使用適合你的體型的輕武器、細劍、鞭子或刺鏈時，你可以在攻擊檢定中使用你的敏捷調整值代替力量調整值。若你持用盾牌，其防具檢定減值將應用於你的攻擊檢定。\n\n天生武器永遠視為輕型武器。"},
-- skl z_skl_bns
[pwr_s2_athletic			]={n="競技		",d="攀爬、游泳檢定+2加值。"},
[pwr_s2_acrobatic			]={n="雜耍		",d="跳躍、翻滾檢定+2加值。"},
[pwr_s2_agile				]={n="靈活		",d="平衡、脫逃術檢定+2加值。"},
[pwr_s2_deft_hands			]={n="熟練手法	",d="繩技、手上功夫檢定+2加值。"},
[pwr_s2_stealthy			]={n="隱祕		",d="躲藏、潛行檢定+2加值。"},
[pwr_s2_animal_affinity		]={n="動物親和	",d="騎術、馴養動物檢定+2加值。"},
[pwr_s2_nimble_fingers		]={n="靈巧手指	",d="開鎖、解除裝置檢定+2加值。"},
[pwr_s2_diligent			]={n="細緻		",d="估價、解讀文書檢定+2加值。"},
[pwr_s2_deceitful			]={n="欺詐		",d="易容、偽造文書檢定+2加值。"},
[pwr_s2_magical_aptitude	]={n="魔法天賦	",d="辨識法術、使用魔法裝置檢定+2加值。"},
[pwr_s2_investigator		]={n="調查員		",d="搜尋、蒐集資訊檢定+2加值。"},
[pwr_s2_alertness			]={n="警覺		",d="偵察、聆聽檢定+2加值。\n\n特殊：只要魔寵在臂展範圍內（相鄰或同一格內），其主人便可獲得警覺專長的好處。"},
[pwr_s2_self_sufficient		]={n="自救		",d="醫療、生存檢定+2加值。"},
[pwr_s2_negotiator			]={n="談判專家	",d="察言觀色、交涉檢定+2加值。"},
[pwr_s2_persuasive			]={n="說服者		",d="威嚇、唬騙檢定+2加值。"},
