[pwr_imm_m					]={n="魔法免疫"		,d="免疫各種法術傷害（易傷型別除外）和效果。"},
[pwr_er_50p					]={n="能量抵抗"		,d="僅受一半任意能量型別的傷害。"},
[pwr_aura5_atk2				]={n="強擊光環"		,d="光環提供者近距範圍內的隊友的攻擊檢定+2加值。"},
[pwr_aura5_dmg2				]={n="凶殘光環"		,d="光環提供者近距範圍內的隊友的傷害檢定+2加值。"},
[pwr_aura5_heal5			]={n="治癒光環"		,d="光環提供者近距範圍內的隊友每回合恢復5點生命。"},
[pwr_aura1_fire5			]={n="熾焰光環"		,d="光環提供者鄰接範圍內的敵人每回合受到5點火焰傷害。"},
[pwr_aura1_toxic5			]={n="屍毒光環"		,d="光環提供者鄰接範圍內的敵人每回合受到5點毒素傷害。"},
[pwr_aura5_fear				]={n="恐懼光環"		,d="光環提供者鄰接範圍內的敵人每回合需進行恐懼檢定，失敗則逃跑。"},
[pwr_pack_atk				]={n="群毆亂鬥"		,d="從每一個與目標鄰接且擁有此專長的隊友獲得+1攻擊檢定加值。"},
[pwr_pack_dmg				]={n="群體攻擊"		,d="對鄰接兩名以上擁有此專長的隊友的敵人進行攻擊時，傷害檢定+5加值。"},
[pwr_rend					]={n="撕扯"			,d="如果兩次爪抓都命中目標，就能抓住對手的身體並撕裂血肉，額外造成2d6+1.5倍力量調整值的傷害。"},
[pwr_rend_co				]={n="協同撕扯"		,d="和擁有此專長的隊友同時鄰接一個敵人時，只需一次爪抓命中就可以進行撕扯。"},
[pwr_blood_tgt1				]={n="嗜血"			,d="攻擊重傷目標時，攻擊檢定+1加值，傷害檢定+2加值。"},
[pwr_blood_tgt2				]={n="極度嗜血"		,d="攻擊重傷目標時，攻擊檢定+2加值，傷害檢定+5加值。"},
[pwr_blood_rage				]={n="血怒"			,d="重傷時，進入血怒狀態：攻擊檢定+2加值，傷害檢定+5加值，防禦等級-2減值。"},
[pwr_blood_rage2			]={n="極度血怒"		,d="一旦受傷，即進入血怒狀態：攻擊檢定+2加值，傷害檢定+5加值，防禦等級-2減值；重傷時，進入極度血怒狀態：傷害檢定加值變為+10。"},
[pwr_imbue_arrow			]={n="注魔箭"		,d="遠端武器攻擊時，附加1d6點傷害（隨機元素傷害型別）。"},
[pwr_tox					]={n="用毒"			,d="擅長在武器上塗抹毒藥，每次命中都可能使目標中毒。"},
[pwr_tox_drow				]={n="淬毒"			,d="被卓爾的淬毒武器擊中的目標必須成功通過基礎DC13的強韌豁免，否則將昏迷。\n\n1分鐘後，昏迷的目標必須再次成功通過一個同樣DC的強韌豁免，否則將繼續昏迷2d4小時。\n\n一個典型的卓爾一般攜帶1D4-1劑卓爾毒。卓爾一般在箭矢上淬毒，但有時也會將其塗抹在近戰武器上。但要注意的是，卓爾並沒有在用毒時使自己免除中毒危險的特殊能力。該毒素並非魔法效果，卓爾和其他精靈都會受到影響。"},
[pwr_hit_down				]={n="蠻力擊倒"		,d="近戰命中時，自動觸發擊倒檢定。"},
[pwr_charge_ex1				]={n="猛烈衝鋒"		,d="衝鋒時，傷害檢定+5加值，自動觸發擊倒檢定。"},
[pwr_charge_ex2				]={n="暴烈衝鋒"		,d="衝鋒時，傷害檢定+10加值，自動觸發強力擊退檢定：目標被擊退2格，並倒地。"},
[pwr_grap_dmg1				]={n="緊勒"			,d="被擒抱者每回合受到5點傷害。"},
[pwr_grap_dmg2				]={n="熊碾"			,d="被擒抱者每回合受到10點傷害。"},
[pwr_grap_sting1			]={n="釘刺"			,d="被擒抱者每回合受到5點傷害。"},
[pwr_grap_sting2			]={n="巨型釘刺"		,d="被擒抱者每回合受到10點傷害。"},
[pwr_grap_suck				]={n="吸血"			,d="被擒抱者每回合受到5點傷害；擒抱者回復5點生命。"},
[pwr_dead_tox				]={n="屍毒"			,d="死亡時，鄰接生物會被感染屍毒。"},
[pwr_x2_atk					]={n="連擊"			,d="使用單一武器攻擊時，會連續攻擊兩次。"},
[pwr_phalanx2				]={n="步兵方陣"		,d="和至少一個擁有此專長的隊友鄰接時，防禦等級+2加值。"},
[pwr_crowd_ac				]={n="人群掩蔽"		,d="鄰接一個生物時，防禦等級和反射豁免檢定+2加值；鄰接兩個以上生物時，防禦等級和反射豁免檢定+4加值。"},
[pwr_ao_ac2					]={n="靈敏反應"		,d="對抗藉機攻擊時，防禦等級+2加值。"},
[pwr_shift_hard				]={n="優雅步伐"		,d="快步時，無視困難地形。"},
[pwr_mov_no_ao				]={n="游擊戰術"		,d="移動不引發藉機攻擊。"},
[pwr_web_mov				]={n=s_web_mov		,d=s_web_mov_d},
[pwr_swamper				]={n="沼澤居民"		,d="無視油膩區域。"},
[pwr_all_eyes				]={n="全域視野"		,d="不會被夾擊。"},
[pwr_trance					]={n="恍惚"			,d="每回合只能進行一個動作。"},
[pwr_fey_blood				]={n="精靈免疫"		,d="免疫魔法睡眠或類似效果；對抗恐懼/魅惑等影響心靈類法術或效果時+2種族加值。"},
[pwr_cha_spl				]={n="龍脈魔法"		,d="魅力施法：能以魅力代替智力（自動取高），作為施法屬性。"},
[pwr_con_spl				]={n="疤痕巫術"		,d="體質施法：能以體質代替智力（自動取高），作為施法屬性。\n\n通過自殘形體，刻烙疤痕的手段取悅自己的庇護主，藉此獲得魔力。"},
[pwr_ghoul_bite				]={n="食屍鬼之咬"	,d="近戰攻擊昏迷目標時，傷害檢定+10加值。"},
[pwr_cha_hp					]={n="超凡生命"		,d="能以魅力代替體質（自動取高），應用於生命值計算。"},
[pwr_str_hp					]={n="人工生命"		,d="能以力量代替體質（自動取高），應用於生命值計算。"},
[pwr_avg_atk				]={n="保守攻擊"		,d="保守的攻擊方式，傷害穩定但無重擊。"},
[pwr_liz_shock				]={n="電擊"			,d="向目標發出一道閃電，造成電擊傷害。"},
[pwr_pack_shock				]={n="群體放電"		,d="回合開始時，若與其他擁有此能力的生物鄰接，則自動對近距範圍內的所有生物進行電擊。放電群體越大，傷害越高。"},
[pwr_tox_arrow				]={n="毒液噴射"		,d="向目標噴射毒液，造成毒素傷害，並且中毒。"},
[pwr_tox_fog				]={n="毒霧"			,d="生成一片毒氣區域，使其中生物中毒。"},
[pwr_tox_erupt				]={n="毒液噴發"		,d="近距離爆發攻擊，造成毒素傷害，並且中毒。"},
[pwr_spit_f					]={n="火焰吐息"		,d="近距離噴射攻擊，造成火焰傷害。"},
[pwr_spit_a					]={n="強酸吐息"		,d="近距離噴射攻擊，造成強酸傷害。"},
[pwr_heal_cw				]={n="維修"			,d="修理發條機械，使其恢復生命值。"},
[pwr_web_a0					]={n="蛛網"			,d="向目標投擲蛛網，使其無法移動。"},
[pwr_shd_bash				]={n="盾擊"			,d="用盾牌猛擊對手，使其昏迷。"},
[pwr_down_a1				]={n="震地"			,d="猛力震動地面，使所有鄰接生物倒地。"},
[pwr_polym					]={n="變形術"		,d="將目標變成隨機移動的小動物。"},
[pwr_turn					]={n="驅散"			,d="引導正能量驅逐不死生物，使其遠離驅散者。\n\n聖武士驅散亡靈時等同於低3級的牧師。\n\n<c=fc_b>每天使用次數：3 + 魅力調整值。</c>"},
[pwr_fear					]={n="恐懼術"		,d="使範圍內的所有敵人因恐懼而逃跑。"},
[pwr_mad					]={n="發狂"			,d="使目標陷入瘋狂狀態，不分敵我的攻擊最近目標。"},
[pwr_charm					]={n="魅惑"			,d="使敵人成為你的隊友。"},
[pwr_eye_ctrl				]={n="支配凝視"		,d="使敵人完全受你控制。"},
[pwr_eye_stone				]={n="石化凝視"		,d="將目標變成石頭。"},
[pwr_sum_spiders			]={n="召喚巨蜘蛛"		,d="召喚兩隻巨蜘蛛為你戰鬥。"},
-- skl acts
[pwr_intimidate				]={n="威嚇"			,d="用你的威嚇檢定對抗目標的等級檢定，成功則目標戰慄至少1輪。\n\n戰慄的角色在攻擊和豁免上都會受到-2減值。"},
[pwr_feint					]={n="虛招"			,d="用你的唬騙檢定對抗目標的察言觀色檢定，成功則目標在你對他的下次近戰攻擊中將失去防禦上的敏捷加值。\n\n這次攻擊必須在你下回合結束前做出。"},
[pwr_treat_wounds			]={n="急救"			,d="進行一次難度15的醫療檢定，成功則目標恢復其最大生命值的1/4或更多。\n\n<c=to>同一生物在一場戰鬥中最多隻能接受1次這種治療。</c>"},
[pwr_treat_bleeding			]={n="止血"			,d="進行一次難度15的醫療檢定，成功則目標停止出血。"},
[pwr_treat_poison			]={n="驅毒"			,d="進行一次難度15的醫療檢定，成功則目標解除中毒。"},
[pwr_improved_feint			]={n="精通虛招"		,d="以移動動作而非標準動作使用虛招。"},
-- misc
[pwr_dfl_arw				]={n="撥擋飛箭"		,d="每輪一次，當正常狀況下你會被某遠端武器擊中時，你可以擋開該武器而不受任何傷害。\n\n你必須至少空著一隻手，非措手不及狀態，且能察覺到此攻擊。"},-- 一般專長	敏捷13，精通徒手擊打。	撥擋遠端武器不算是一個動作。特別大的遠端武器和法術效果產生的遠端攻擊無法被撥擋。特殊：武僧可以在2級時選擇本專長作為獎勵專長，即使未滿足先決條件。戰士可以選擇本專長作為其戰士獎勵專長。
[pwr_snt_arw				]={n="抓取飛箭"		,d="你可以在使用撥擋飛箭專長時抓住箭矢而非僅僅擋開它，投擲武器則立即被擲回原攻擊者（不會觸發藉機攻擊）。\n\n<c=o>此能力作為開關能力開啟時，抓住投擲武器後也留著備用。</c>"},-- 敏捷15，撥擋飛箭，精通徒手攻擊。	戰士可以選擇本專長作為戰士的獎勵專長。
[pwr_stunning_fist			]={n="震懾拳"		,d=pwr_stunning_fist_d},
[pwr_improved_stunning_fist	]={n="精通震懾拳"	,d="震懾拳強韌檢定+2加值。\n\n特殊：可多次獲得此專長，效果疊加。"},-- Epic 敏捷19，感知19，精通徒手攻擊，震懾拳。
[pwr_ch_mle_dmg				]={n="毀滅重擊"		,d=pwr_ch_mle_dmg_d},
[pwr_sa_1x					]={n="精通偷襲"		,d="你的偷襲更為致命，偷襲傷害+1d6點。\n\n特殊：可多次獲得此專長，效果疊加。"},-- Epic 偷襲+8d6。Sneak attack +8d6.
[pwr_rage_fear				]={n="恐怖狂暴"		,d=pwr_rage_fear_d},
-- mnk 17 + 2
[pwr_unarmed_strike			]={n="徒手擊打"		,d=pwr_unarmed_strike_d},
[pwr_flurry_of_blows		]={n="疾風連擊"		,d=pwr_flurry_of_blows_d},
[pwr_ac_bonus				]={n="防禦加值"		,d=pwr_ac_bonus_d},
[pwr_fast_movement_monk		]={n="快速移動"		,d="武僧擁有更快速的移動能力，其速度每3級+2增強加值（3級時+2，6級時+4...，30級時+20達到頂峰）。\n\n當穿著盔甲、持用盾牌、中載或過載時，將失去此額外速度。"},-- 史詩 21級+70英尺 24級+80英尺。。。
[pwr_still_mind				]={n="心如止水"		,d="武僧的冥思修行使其更能抵抗影響心靈的攻擊，在對抗惑控系法術和效果時，豁免檢定+2加值。"},
[pwr_ki_atk					]={n="鬥氣擊"		,d=pwr_ki_atk_d},
[pwr_slow_fall				]={n="輕身墜"		,d="武僧能利用身旁的牆壁減緩墜落的速度。計算墜落高度時，每武僧等級減5尺。20級起可無傷墜落。"},
[pwr_purity_of_body			]={n="百病不侵"		,d="武僧能控制身體的免疫系統，免疫所有疾病，除了超自然或魔法造成的。"},--（如腐屍症、獸化症等）
[pwr_wholeness_of_body		]={n="混元體"		,d="武僧具有自我療傷的能力。\n\n每日治療點數：等級 x 2，可分多次使用。"},
[pwr_diamond_body			]={n="金剛體"		,d="武僧能控制身體的新陳代謝系統，免疫所有毒素。"},
[pwr_abundant_step			]={n="遁術"			,d="每日一次，武僧能如魔法般在空間內瞬移。"},-- ，如同施展次元門法術（施法者等級=武僧等級/2）
[pwr_diamond_soul			]={n="金剛魂"		,d="武僧獲得法術抗力，數值為武僧等級+10。"},-- 要對此武僧使用魔法，施法者必須在施法者等級檢定（1d20+施法者等級）中得到和武僧法術抗力相等或更高的結果。
[pwr_quivering_palm			]={n="滲透勁"		,d=pwr_quivering_palm_d},
[pwr_timeless_body			]={n="不老身軀"		,d="不再因年齡而遭受屬性減值，也不會因魔法效果而變老。但之前的屬性減值將保留，角色也仍會老死。"},-- 屬性加值仍然可以獲得，	武僧不再因年齡而遭受屬性減值，也不會因魔法效果而變老。但之前的屬性減值將保留，武僧也仍會老死。	A monk no longer takes penalties to her ability scores for aging and cannot be magically aged. Any such penalties that she has already taken, however, remain in place. The monk still dies of old age when her time is up.
[pwr_tongue_monk			]={n="天語通"		,d="武僧能與任何活物交談。"},
[pwr_empty_body				]={n="空靈體"		,d=pwr_empty_body_d},
[pwr_perfect_self			]={n="超凡入聖"		,d="武僧的修練臻於完美，成為魔法生物。\n\n武僧獲得傷害減免10/魔法。在考慮法術或魔法效果時，武僧被視為異界生物，而非凡俗種族。比如魅惑人類便對其無效，但武僧仍可被複活。"},-- 永遠被視為異界生物（或外界生物）而不是原來的類人生物（或者武僧本來的生物型別）。	獲得了10/魔法武器的傷害減免能力	當被非魔法武器或不具有類似的傷害減免能力（見傷害減免，《地下城主指南》291 頁）的生物以天生武器攻擊時，武僧可忽視攻擊的前10點傷害（可以立即再生）。	，如同他還屬於之前的生物型別一樣，這點與其他異界生物不同
-- misc
[pwr_flurry_of_blows_r		]={n="遠端疾風連擊"	,d="類似正常近戰疾風連擊，使用特殊武僧武器手裡劍從遠處施展疾風連擊。"},
[pwr_quivering_palm_kill	]={n="滲透勁：意念殺"	,d="武僧可嘗試用意念殺死中了他的滲透勁的生物。成功則目標立即死亡，失敗則此滲透勁失效。"},
[pwr_end_act				]={n="終止動作"		,d="你可以自由地終止某些進行中的動作或效果。"},
[pwr_end_spl				]={n="解消能力"		,d="某些法術或能力生效後，其施法者可以隨時將之解消掉。"},

[pwr_test					]={n="測試"			,d="測試"},
}


s_dominated	="被支配"	s_dominated_d	="你被施法者控制，被迫按其想法行動。"-- 僅用於命令：xx描述前置
-- z_cond
conds_text={
[cond_rsv_1				]={n="保留狀態1"		,d="暫無描述。"},
[cond_rsv_2				]={n="保留狀態2"		,d="暫無描述。"},
[cond_rsv_3				]={n="保留狀態3"		,d="暫無描述。"},
[cond_rsv_4				]={n="保留狀態4"		,d="暫無描述。"},
[cond_rsv_5				]={n="保留狀態5"		,d="暫無描述。"},
[cond_rsv_6				]={n="保留狀態6"		,d="暫無描述。"},
[cond_rsv_7				]={n="保留狀態7"		,d="暫無描述。"},
[cond_rsv_8				]={n="保留狀態8"		,d="暫無描述。"},
[cond_rsv_9				]={n="保留狀態9"		,d="暫無描述。"},

[cond_burn				]={n="燃燒"			,d="回合開始時，受到指定點數的火焰傷害。"},
[cond_corrode			]={n="腐蝕"			,d="回合開始時，受到指定點數的強酸傷害。"},
[cond_tox				]={n="中毒"			,d="回合開始時，受到指定點數的毒素傷害。"},
[cond_bleed				]={n="流血"			,d="回合開始時，受到指定點數的流血傷害。"},
[cond_hr				]={n="再生"			,d="回合開始時，恢復指定點數的生命值。"},

[cond_thp				]={n="暫時生命值"		,d="某些效果可以讓角色獲得暫時生命值。當角色獲得暫時生命值時，這些生命值記在他的實際總生命值中。當這些暫時生命值消失時，角色的生命值將會降到他的實際總生命值。如果角色的生命值被降低到比他實際總生命值低，所有的暫時生命值都將失去，角色的總生命值不會降低。\n\n當暫時生命值失去後，它們不能象真實生命值那樣被恢復，即使魔法也不行。\n\n增加體質值和實際生命值：增加角色的體質值，甚至是暫時性增加，都將會給他更多的生命值（有效生命值增加），但是這些生命值不是暫時生命值。它們不會像暫時生命值那樣優先失去。"},
[cond_def				]={n="標準防禦"		,d="專注於防禦，直到下回合開始。"},
[cond_def_full			]={n="全力防禦"		,d="全力以赴地進行防禦，直到下回合開始。"},
[cond_fgt_def			]={n=s_fgt_def		,d=s_fgt_def_d},

[cond_dazzled			]={n="目眩"			,d="角色因為眼睛受到嚴重刺激而無法很好地視物。目眩的角色在攻擊、搜尋檢定上受到-1減值。"},-- 和偵察
[cond_blinded			]={n="目盲"			,d="角色看不見東西。\n\n- 攻擊有50%失手率（對手視為全隱蔽）。\n- 防禦-2減值，並失去其上的敏捷加值。\n- 速度減半。\n- 搜尋和大多數基於力量和敏捷的技能檢定-4減值。\n- 所有依靠視力的檢定和活動自動失敗。"},-- 所有依靠視力的檢定和活動（例如閱讀和偵察檢定）自動失敗。一些長時間目盲的人物會習慣於此並克服某些缺點。
[cond_deafened			]={n="耳聾"			,d="角色聽不見東西。\n\n- 先攻檢定-4減值。\n- 聆聽檢定自動失敗。\n- 施展具有語言成分的法術有20%機率失敗。"},-- 一些長時間耳聾的人物會習慣於此並克服某些缺點。
[cond_fatigued			]={n="疲乏"			,d="角色的力量和敏捷-2減值，而且無法衝鋒。疲乏的角色做出正常情況下會導致疲乏狀態的行為時會變為力竭狀態。"},-- 無法奔跑或衝鋒	在8小時完全休息後，疲乏的人物就不再疲乏。
[cond_exhausted			]={n="力竭"			,d="角色的力量和敏捷-6減值，而且速度減半。"},-- 在1小時完全的休息之後，力竭的人物將變得疲乏。
[cond_sickened			]={n="噁心"			,d="角色遭受突如起來的痛苦及熱病，攻擊，傷害，豁免，技能和屬性檢定-2減值。"},
[cond_nauseated			]={n="反胃"			,d="強烈的胃部痛苦使得角色無法攻擊、施法或其他任何需要集中注意力的動作，每輪只能做一個移動動作。"},-- 施法、專注以維持法術
[cond_staggered			]={n="恍惚"			,d="恍惚的角色每輪只能做一個移動或標準動作。"},-- 所受非致命傷害與其生命值相同則恍惚。如果當前生命值超過了所受非致命傷害，那麼人物不再處於恍惚狀態。非致命傷害值超過了生命值的則會陷入昏迷。	（不能二者都做，也不能做整輪動作）
[cond_dazed				]={n="暈眩"			,d="暈眩的角色無法行動，但防禦上並無懲罰。"},-- 角色無法正常行動。暈眩狀態通常持續1輪。
[cond_flat_footed		]={n="措手不及"		,d="戰鬥開始後未開始行動的角色尚不能正常應對當前形勢，防禦失去敏捷加值且無法藉機攻擊。"},
[cond_surprise			]={n="被突襲"		,d="被敵人突襲後，戰鬥開始的首個回合無法行動。"},

[cond_shaken			]={n="戰慄"			,d="攻擊、豁免、技能和屬性檢定-2減值。"},-- 戰慄不如驚懼和恐慌那麼激烈。
[cond_frightened		]={n="驚懼"			,d="驚懼的生物會盡力逃離恐懼源頭。若無法逃離則可能戰鬥。\n\n此外，攻擊、豁免、技能和屬性檢定-2減值。"},-- 驚懼的人物會用特殊能力逃離，包括使用法術；實際上如果只能用特殊能力逃離，那麼人物就必須用那種方式逃離。驚懼類似於戰慄，除了生物只要有可能就必須逃離。恐慌是一種更激烈的恐懼狀態。
[cond_panicked			]={n="恐慌"			,d="恐慌的生物會扔掉手中物品，盡力逃離恐懼源頭。它不能做任何其他動作。\n\n此外，豁免、技能和屬性檢定-2減值。"},-- ，同樣也會避開任何其它遭遇的危險，但路線隨機	恐慌的人物會用特殊能力逃跑，包括使用法術；實際上如果只能用特殊能力逃跑，那麼人物就必須用那種方式逃跑。		如果被逼至絕路，它會陷入畏縮狀態。	恐慌是比驚懼和戰慄更激烈的恐懼狀態。
[cond_cowering			]={n="畏縮"			,d="被嚇住以至於無法行動，防禦-2減值，並失去其上的敏捷加值。"},-- 角色被嚇住以至於無法做動作。畏縮的角色在防禦等級上有-2減值，並失去其上的敏捷加值（如果有的話）。

[cond_dmg_str			]={n="力量傷害"		,d="力量暫時降低。角色力量為0時，無助，倒地。"},-- 屬性傷害	人物在一項或多項屬性上暫時失去點數。除非註明要用其他方法治療，否則失去的點數以每天1點的速率回升。力量為0意味著人物無力的躺在地上。敏捷為0意味著人物麻痺。體質為0意味著人物死亡。智力、感知、魅力為0意味著人物昏迷。屬性傷害與屬性值上的減值不同，後者會隨著狀態的消失而消失。
[cond_dmg_dex			]={n="敏捷傷害"		,d="敏捷暫時降低。角色敏捷為0時，麻痺。"},
[cond_dmg_con			]={n="體質傷害"		,d="體質暫時降低。角色體質為0時，死亡。"},
[cond_dmg_int			]={n="智力傷害"		,d="智力暫時降低。角色智力為0時，昏迷。"},
[cond_dmg_wis			]={n="感知傷害"		,d="感知暫時降低。角色感知為0時，昏迷。"},
[cond_dmg_cha			]={n="魅力傷害"		,d="魅力暫時降低。角色魅力為0時，昏迷。"},
[cond_drn_str			]={n="力量吸取"		,d="力量永久降低。角色力量為0時，無助，倒地。"},-- 屬性吸取
[cond_drn_dex			]={n="敏捷吸取"		,d="敏捷永久降低。角色敏捷為0時，麻痺。"},
[cond_drn_con			]={n="體質吸取"		,d="體質永久降低。角色體質為0時，死亡。"},
[cond_drn_int			]={n="智力吸取"		,d="智力永久降低。角色智力為0時，昏迷。"},
[cond_drn_wis			]={n="感知吸取"		,d="感知永久降低。角色感知為0時，昏迷。"},
[cond_drn_cha			]={n="魅力吸取"		,d="魅力永久降低。角色魅力為0時，昏迷。"},
[cond_dmg_phy			]={n="體能屬性傷害"	,d="體能屬性暫時降低。"},
[cond_dmg_mtl			]={n="心靈屬性傷害"	,d="心靈屬性暫時降低。"},
[cond_dmg_all			]={n="所有屬性傷害"	,d="所有屬性暫時降低。"},
[cond_drn_phy			]={n="體能屬性吸取"	,d="體能屬性永久降低。"},
[cond_drn_mtl			]={n="心靈屬性吸取"	,d="心靈屬性永久降低。"},
[cond_drn_all			]={n="所有屬性吸取"	,d="所有屬性永久降低。"},
[cond_energy_drained	]={n="能量吸取		",d="角色獲得一個或多個負向等級。若負向等級數大於等於角色等級，角色死亡。每個負向等級給予下列懲罰：攻擊、豁免、技能和屬性檢定-1減值；生命值-5；有效等級-1（用來決定法術或特殊能力的強度、持續時間、DC和其它細節）；施法者從可施展的最高法術等級上失去一個法術或一個法術欄位。"},--，這些負向等級有可能會使他等級永久下降

[cond_hf_mov			]={n="遲緩"			,d="移動速度減半，無法衝鋒。"},
[cond_no_mov			]={n="禁足"			,d="無法移動。"},
[cond_prone				]={n="俯臥"			,d="倒地時移動速度減半，近戰攻擊和防禦-4，遠端防禦+4，不能使用弩以外的遠端武器。起立需耗費一個移動動作，並且會引發藉機攻擊。"},
[cond_entangled			]={n="糾纏"			,d="人物被纏繞住。被糾纏會使移動受到限制，但除非被綁在固定的物體上或被相反的力道拉住，否則移動不會被完全阻止。被糾纏的人物只能以正常速度的一半移動，無法奔跑或衝鋒，所有攻擊擲骰上有-2減值，並在敏捷上有-4減值。糾纏中的角色想施法則必須透過專注檢定（DC 15+法術等級），否則失去法術。"},

[cond_grapper			]={n="擒抱"			,d="專注於壓制被擒抱者，無法做其他動作，無威脅區域，失去防禦上的敏捷加值。"},-- 與一個或更多的進攻者從事於短兵相接的角鬥。一個擒抱中的人物僅能做一些有限的動作。他沒有任何威脅區域，並對於沒有和他進行擒抱的對手來說，他失去了在AC上的敏捷加值。
[cond_grap				]={n="被擒抱"		,d="被壓制而無法行動。回合開始時，會自動嘗試掙脫。"},
[cond_pinned			]={n="壓制"			,d="在擒抱中被固定住無法行動（但不是無助）。"},
[cond_stunned			]={n="震懾"			,d="被震懾住的生物手中物品會掉落，無法行動，防禦-2減值，並失去其上的敏捷加值。"},
[cond_helpless			]={n="無助"			,d="無法動彈，無法行動。"},-- 被麻痺、定身、束縛、睡眠中、昏迷、或其它完全暴露於敵手掌控之中的狀態。無助的目標的敏捷當作0（調整值為-5）。對無助的目標進行近身攻擊有+4獎勵（相當於攻擊俯臥中的對手）。遠端攻擊沒有特殊獎勵。遊蕩者可以偷襲無助的目標。敵人可以用近戰武器對無助的目標做一次致命一擊（coup de grace），這是一個整輪動作。如果敵人和目標緊鄰，那麼也可以用弓和弩做致命一擊。攻擊者自動命中，並認為是重擊（遊蕩者在做出致命一擊時還能獲得偷襲傷害值）。如果目標從這次攻擊中倖存，他必須進行一次成功的強韌豁免檢定（DC 10+傷害值）否則死亡。做致命一擊會引發藉機攻擊。免疫重擊的生物不會受到重擊傷害，也不需要進行成功的強韌檢定來避免被致命一擊殺死。
[cond_unconscious		]={n="昏迷"			,d="陷入昏迷，無法行動。"},-- 生物被擊倒並陷入無助狀態。若人物當前生命值在-1到-9之間，或非致命傷害超過其當前生命值，則該人物陷入昏迷。
[cond_paralyzed			]={n="麻痺"			,d="僵在原地，無法行動。"},-- 被麻痺的人物被釘在原地不能移動或做其他行動。被麻痺的人物其有效敏捷值和有效力量值為0，而且處於無助狀態，但他可以進行純粹的心理活動。有翅膀的生物在飛的時候被麻痺，他們將無法舞動翅膀並掉下來。游泳的人被麻痺後無法游泳並有可能遭受淹溺。其它生物可以穿過被麻痺的人物佔據的區域，無論是盟友還是敵人。但是被麻痺的人物所佔據的每個方格都記作兩個方格。
[cond_stone				]={n="石化"			,d="變為石頭並視作昏迷。"},-- 被石化的人物變為石頭並視作昏迷。如果被石化的人物被打碎或打破，但是在被解除石化時那些破損的部份接在了身體上，那麼他將不受傷害。如果石化的身體被解除石化時是不完整的，肉體將同樣的不完整，並會有相應永久性生命值喪失和（或）人物變的衰弱。
[cond_sleep				]={n="睡眠"			,d=pwr_sleep_d},
[cond_turn				]={n="被驅散"		,d="受到驅散亡靈效果的影響，自動逃離驅散者。"},-- 受到驅散亡靈效果的影響。被驅散的不死生物會用其最好最快的方法逃離10輪（1分鐘）。如果無法逃離，則處於畏縮狀態。

[cond_disabled			]={n="癱瘓"			,d="人物的生命值為0，或擁有負值的生命值但已穩定並神智清醒，這些情況為癱瘓狀態。癱瘓人物每輪只能做一個移動動作或一個標準動作（不能兩者都做，也不能進行全回合動作）。他只能以正常速度的一半移動。做移動動作不會招致更多的傷害，但是進行任何標準動作（或其他任何DM認為是費力的事，包括一些即時動作，例如施展瞬發法術等）會在動作完成後受到1點傷害。除非這個動作增加了癱瘓人物的生命值，否則他的生命值將降為負數並因而進入瀕死狀態。有著負數生命值的癱瘓人物如果能受到幫助，他的生命值會自然回升。否則，每天他有10%的機率開始自然回覆生命值（從那天開始），如果沒能自然回覆，他將繼續失去1點生命值。如果沒有援助的癱瘓人物生命值開始自然回升，他就不再有繼續降低生命值的危險（即使當前生命值仍是負數）。"},
[cond_dying				]={n="瀕死"			,d="瀕死的人物處於昏迷狀態並接近死亡。其當前的生命值為-1至-9。瀕死的人物無法做動作並且昏迷。在每輪結束（從生命值降到0以下的那一輪開始），人物擲一個百分骰決定是否傷勢穩定。他有10%的機率進入穩定狀態。如果沒能穩定，生命值將降低1點。如果生命值降到-10，他就死亡。"},
[cond_stable			]={n="穩定"			,d="曾處於瀕死狀態但目前已經不再繼續損失生命值，同時生命值依然為負數的人物是穩定狀態。這類人物不再處於瀕死狀態，但仍舊昏迷。如果其他人利用急救措施（例如醫療技能或魔法治療）使瀕死人物穩定下來，他就不會繼續丟失生命值。他每小時有10%的機會清醒並進入癱瘓狀態（儘管他的生命值可能是負的）。如果人物並沒有受到別人的幫助而是靠自己穩定下來的話，他仍然有丟失生命值的危險。他每小時有10%的機會清醒並進入癱瘓狀態，否則就將失去1點生命值。"},
[cond_dead				]={n="死亡"			,d="人物的生命值降到-10，體質降到0，或被法術及效果徹底殺死。人物的靈魂離開身體。死亡人物無法得益於正常或魔法的治療，但能透過魔法復活。除非用魔法保護，否則屍體會正常腐爛，但是使死亡人物復活的法術會使人物完全康復或回到死亡時的狀態（取決於使用的魔法或裝置）。無論使用什麼手段，被複活的人物都不用擔心諸如屍僵、腐爛和其它影響屍體的效果。"},
[cond_fascinated		]={n="迷魂"			,d="處在迷魂狀態的人物被超自然能力或法術弄得神志恍惚。人物會靜靜的站著或坐著，除了專心於產生迷魂的效果外什麼都不做，直到效果結束。在基於感應的技能檢定上（例如聆聽和偵察檢定）有-4減值。任何潛在的威脅，如敵對生物的接近，將允許被迷魂的生物進行一次新的豁免檢定來對抗迷魂效果。任何明顯的威脅,例如其他人拔出武器、施展法術或以遠端武器瞄準被迷魂的生物，都會自動地打破效果。被迷魂生物的同伴可以透過一個標準動作搖晃他來使他擺脫迷魂狀態。"},
[cond_confused			]={n="困惑"			,d="困惑的人物的行動在他的回合開始時透過百分率決定：01-10，用肉搏或遠端武器攻擊施法者（如果無法攻擊就向施法者靠近）；11-20，正常行動；21-50，除了毫無條理的說胡話外什麼都不做；51-70，以最快的速度逃離施法者；71-100，攻擊最近的生物（在這種情況下，魔寵視作受術者自身的一部分）。無法做上述規定動作的困惑生物只能毫無條理的說胡話。攻擊困惑生物不會有任何特殊獎勵。只要在被攻擊的困惑生物其回合開始時還處於困惑中，他就會自動在接下來的回合內向攻擊他的生物發起攻擊。除了已經準備攻擊的生物（要麼是困惑生物最近一個動作的目標，要麼是剛攻擊過困惑生物的生物），困惑的生物將不會對其他生物進行藉機攻擊。"},
[cond_invisible			]={n="隱形"			,d="無法被視力探察。隱形生物攻擊非隱形生物時在攻擊擲骰上有+2加值，並忽視他的敏捷加值對AC的獎勵。（見特殊能力中隱形的說明。）"},
[cond_incorporeal		]={n="虛體"			,d="沒有肉體。虛體生物免疫一切非魔法類攻擊。只有其它虛體生物的攻擊、+1或更好的魔法武器、法術、類法術能力或超自然能力可以傷害到它。"},
[cond_checked			]={n="受阻"			,d="被一股力量阻止前進，例如風。在地上受阻僅僅是裹足不前。受阻的飛行生物會退後一段距離，這段距離在對應效果的描述中給出。"},
[cond_knocked_down		]={n="吹倒"			,d="由於體型關係，一個生物可以被一陣強風吹倒。在地面上的生物會被吹倒趴下。飛行生物會被吹後1d6x10尺。"},
[cond_blown_away		]={n="吹動"			,d="由於體型關係，一個生物可以被一陣強風吹動。在地面上處於被吹動狀態的生物會被吹倒並翻滾1d4x10尺，每10尺受到1d4點非致命傷害。飛行中處於被吹動狀態的生物會被吹後2d6x10尺並受到2d6點非致命傷害。"},

[cond_red_ache			]={n="紅腫症"		,d="患者膚色轉紅、腫脹、發熱。發病時造成1d6力量傷害。"},-- 傷口	15	1d3天	感染方式 DC 潛伏期
[cond_devil_chills		]={n="寒魔症"		,d="經由巴霸魔和深獄煉魔傳染。發病時造成1d4力量傷害。必須經過三次成功的豁免檢定才能恢復健康，而不是通常的兩次。"},-- 傷口	14	1d4天
[cond_blinding_sickness	]={n="失明症"		,d="透過被汙染的水傳播。發病時造成1d4力量傷害，當此傷害為2或更高時，患者必須做一次額外的強韌檢定，失敗則永久目盲。"},-- 攝入	16	1d3天
[cond_shakes			]={n="顫慄症"		,d="患者會不由自主的抽搐發顫和痙攣。發病時造成1d8敏捷傷害。"},-- 接觸	13	1天
[cond_filth_fever		]={n="腐熱症"		,d="經由兇暴鼠與食腐獸傳染。當傷口處於骯髒的環境中時也會感染。發病時造成1d3敏捷和1d3體質傷害。"},-- 傷口	12	1d3天
[cond_demon_fever		]={n="熱魔症"		,d="經由老鬼婆傳染。發病時造成1d6體質傷害，患者必須成功透過一次額外的強韌豁免，否則受到1點的永久屬性吸取而非原來的屬性傷害。"},-- 傷口	18	1天
[cond_mummy_rot			]={n="腐屍症"		,d="經由木乃伊傳染。發病時造成1d6體質傷害。成功的豁免檢定也不會使感染者恢復健康（但仍能避免傷害），只有魔法醫療才能治癒。"},-- 接觸	20	1天
[cond_slimy_doom		]={n="膠質症"		,d="患者會由內到外逐漸變成有感染性的粘稠物。發病時造成1d4體質傷害，患者必須成功透過一次額外的強韌豁免，否則受到1點的永久屬性吸取而非原來的屬性傷害。"},-- 接觸	14	1天
[cond_mindfire			]={n="腦熱症"		,d="患者感到腦袋焦熾般的燒熱。導致昏迷。發病時造成1d4智力傷害。"},-- 吸入	12	1天
[cond_cackle_fever		]={n="失心瘋"		,d="症狀包括高燒，意識模糊，以及經常發出陣陣狂笑。也稱為“狂喊症”。發病時造成1d6感知傷害。"},-- 吸入	16	1天

[cond_command_fight		]={n="命令：戰"		,d="在你的回合中，你將盡可能地進行戰鬥。"},
[cond_command_approach	]={n="命令：來"		,d="在你的回合中，你將盡可能迅速直接地走向此效果的施法者，其他什麼也不做。"},
[cond_command_flee		]={n="命令：逃"		,d="在你的回合中，你將盡可能迅速直接地遠離此效果的施法者，其他什麼也不做。"},
[cond_command_halt		]={n="命令：停"		,d="在你的回合中，你將原地不動1輪，不能做任何動作，但並非無助。"},
[cond_command_fall		]={n="命令：倒"		,d="在你的回合中，你將躺倒在地1輪。俯臥中你能正常行動，但要受到相應的懲罰。"},
[cond_command_drop		]={n="命令：掉"		,d="在你的回合中，你將扔掉手中所有物品，直到你的下一回合之前都不會撿起來。"},

[cond_warm_shield		]={n="溫暖護盾"		,d=pwr_fire_shield_f},
[cond_chill_shield		]={n="寒冷護盾"		,d=pwr_fire_shield_c},
[cond_prayer_favor		]={n="神之恩寵"		,d="神之恩寵籠罩著你，攻擊、武器傷害、豁免和技能檢定+1幸運加值。"},--祈禱術：
[cond_prayer_disfavor	]={n="神之厭惡"		,d="神之厭惡籠罩著你，攻擊、武器傷害、豁免和技能檢定-1減值。"},
[cond_curse_penalty		]={n="詛咒：懲罰"		,d="攻擊、豁免、屬性和技能檢定上受到-4懲罰。"},
[cond_curse_disorder	]={n="詛咒：錯亂"		,d="50%機率正常行動；否則無法行動。"},
[cond_comatose			]={n="沉睡"			,d="角色陷入僵硬的病態沉眠，無法被叫醒。這並非睡眠效果，因此精靈不能免疫它。"},
[cond_ethereal			]={n="靈體"			,d=pwr_ethereal_jaunt_d},
[cond_death_atk_1		]={n=s_death_atk_1	,d=s_death_atk_d},
[cond_death_atk_2		]={n=s_death_atk_2	,d=s_death_atk_d},
}